insert into institution_regulations (regulation_id, institution_id, title, stage, lifecycle_state, current_state_note, updated_by) values
  ('reg_9ed928e1e75c_support_rules', 'inst_catalog_9ed928e1e75c', '東北大学星陵スタートアップビレッジレンタルスペース使用内規', 4, 'effective', '2025年11月12日制定、附則により2026年3月1日施行。第2条で、本学の教員等が研究シーズの育成や事業化を推進するために使用する場合、および本学の教員等が関係するスタートアップ企業等がその活動に使用する場合に、医学系研究科長が期間を定めてレンタルスペースを使用させると規定。第3条は原則1年単位・最長5年・審査を経た延長可。第4条で医学系研究科長へ申請し、第5条で星陵スタートアップビレッジ運営委員会が使用目的等を審査、研究科長が条件を付して許可。学外者は国立大学法人東北大学不動産等貸付事務取扱細則による貸付契約を締結。第6条に基本料金と付帯料金、第8条に減免。g-reiki.netの東北大学規程集で本文を確認。', 'migration:387'),
  ('reg_f47662863af3_recognition', 'inst_catalog_f47662863af3', '国立研究開発法人森林研究・整備機構の研究開発分野におけるベンチャー支援規程', 4, 'effective', '令和7年3月11日6森林機構1078号、附則により令和7年4月1日施行。全13条＋様式1〜5。第2条で森林総研発ベンチャーを定義、第3条でベンチャー認定委員会を設置、第4条で理事長への申請と諮問・答申・決定の手続、第5条で認定要件（成果活用事業者、設立から概ね10年以内等）と有効期間5年・延長でさらに5年、第6条で支援（場所の貸与、研究設備等の利用許可、成果活用ロゴマークを含む知財の実施許諾、その他）、第8条で年度末の実施状況報告、第9条で取消し、第12条で主管部署を企画部研究管理科と規定。森林総合研究所の産学官民連携ページのベンチャー支援欄から入手。', 'migration:387'),
  ('reg_f47662863af3_ip_license', 'inst_catalog_f47662863af3', '国立研究開発法人森林研究・整備機構知的財産権実施規程', 4, 'effective', '平成13年4月2日13森林総研第72号、最終改正 令和6年3月22日5森林機構第1084号（令和6年4月1日施行）。全16条＋様式。第3条で原則を通常実施権とし、申出があり必要と認めた場合は専用実施権を設定できると規定。第4条で申込書・実施計画書・経歴書・定款写の提出、第6条で実施契約の必須事項、第7〜8条で実施料の算定（実施料率＝基準率×利用率×増減率×開拓率）と銀行振込による支払、第9条で技術指導と実施者負担の派遣費用を規定。別紙様式の申込書には森林総合研究所側の「利益相反の有無」申告欄がある。ベンチャー支援規程第6条第4項が本規程を実施許諾の根拠として指定。産学官民連携ページの実施（使用）許諾契約欄から入手。', 'migration:387'),
  ('reg_dd388f7debe3_conflict_of_interest', 'inst_catalog_dd388f7debe3', '国立研究開発法人産業技術総合研究所利益相反マネジメント実施規程', 4, 'effective', '産総研の規程類一覧ページから到達。令01規程第29号（17規程第68号の全部改正）、最終改正は令和7年3月31日 令06規程第51号。第2条が産学官連携活動等に出資と株式等の処分を含め、個人的利益を兼業・株式等の保有・知財の保有と定義。第3条から第9条で利益相反マネジメント委員会（事務局は法務室）、第10条から第12条で利益相反カウンセラー、第13条・第14条で定期および事前の自己申告を規定。', 'migration:387'),
  ('reg_dd388f7debe3_side_job', 'inst_catalog_dd388f7debe3', '国立研究開発法人産業技術総合研究所兼業等規程', 4, 'effective', '産総研の規程類一覧ページから到達。17規程第13号、最終改正は令和7年7月1日 令07規程第7号。第2条で役員兼業・一般兼業・自営・副業を定義、第3条で兼業等審査委員会、第5条で理事長の許可基準と原則2年以内の許可期間、第7条で役員兼業休職、第10条で勤務時間内役員兼業。第5章（第29条・第30条）が兼業等の従事先から受ける株式等による報酬（エクイティ報酬）の届出を定める。', 'migration:387'),
  ('reg_dd388f7debe3_ip_license', 'inst_catalog_dd388f7debe3', '知的財産権の実施許諾及び譲渡に関する規程', 4, 'effective', '産総研の規程類一覧ページから到達。13規程第15号、最終改正は令和7年3月10日 令06規程第31号（ベンチャー支援規程を廃止する等の規程と同番号）。第2条で非独占・独占・一部独占の実施許諾と有償無償を規定、第3条で独占的許諾の要件と公示・異議申立て、第4条で共同研究相手や役職員等の転出先への独占許諾の特例、第7条で出資業務規程との関係を定める。', 'migration:387'),
  ('reg_dd388f7debe3_equity_stock_option', 'inst_catalog_dd388f7debe3', '国立研究開発法人産業技術総合研究所成果活用事業者出資業務規程', 4, 'effective', '産総研の規程類一覧ページから到達。令01規程第15号（26規程第33号の全部改正）、最終改正は令和7年4月1日 令06規程第37号。第2条で株式等を株式・新株予約権・持分と定義、第4条で金銭および金銭以外の財産（有形固定資産・知的財産権）の出資と議決権3分の1未満の原則、第5条で出資対象要件、第3条で成果活用事業者出資委員会、第13条で知財出資時の発明者補償、第14条で利益相反管理を規定。', 'migration:387'),
  ('reg_dd388f7debe3_joint_research', 'inst_catalog_dd388f7debe3', '国立研究開発法人産業技術総合研究所共同研究規程', 4, 'effective', '産総研の規程類一覧ページから到達。13規程第22号、最終改正は令和7年4月1日 令06規程第37号。スタートアップ専用の共同研究規程ではなく全相手方に共通する規程。第2条で専用実施権・通常実施権・独占的実施権を定義、第3条で実施基準、第3条の2で装置購入が絡む場合の事前承認、第4条で共同研究契約の締結を規定し、研究施設等利用規程に基づき共同研究者に施設の一部を使用させることができる。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_dd388f7debe3_shared_equipment', 'inst_catalog_dd388f7debe3', '国立研究開発法人産業技術総合研究所研究施設等の利用及び貸付に関する規程', 4, 'effective', '産総研の規程類一覧ページから到達。令05規程第49号（令03規程第10号の全部改正、附則第1条で令和6年4月1日施行）、最終改正は令和7年11月28日 令07規程第16号。第2条で一時利用と貸付を区別、第3条で受入要件（産業競争力強化法施行規則第14条の25の施設を新たな事業活動を行う者が利用する場合を含む）、第5条で役務提供・技術指導・技術代行、第6条で利用料等の徴収、第12条でAISolの転貸特例を規定。', 'migration:387'),
  ('reg_33f367188cf9_conflict_of_interest', 'inst_catalog_33f367188cf9', '立命館大学利益相反規程', 4, 'effective', 'PDFを取得し全文を確認。冒頭に「2004年3月24日 規程第593号」。第2条で責務相反と個人としての利益相反を定義、第3条で常任理事会のもとに利益相反委員会を設置し兼業申請の承認・金銭的情報開示・調査等を所掌、第4条で利益相反アドバイザーを置く。第5条から第9条が兼業(責務相反)マネジメントで、第6条第4号は研究成果を活用するための起業を自らの発明等の事業化に限定し、第8条で営利企業の取締役等就任は利益相反委員会が審議・承認する。第10条から第12条が個人としての利益相反マネジメント。立命館大学研究部の利益相反ページからリンクされている。', 'migration:387'),
  ('reg_33f367188cf9_side_job', 'inst_catalog_33f367188cf9', '学校法人立命館教職員兼業規程', 4, 'effective', 'PDFを取得し全文を確認。冒頭に「2020年9月9日 規程第1192号」、附則で2020年10月1日施行、2021年3月17日に技術職員の削除に伴う一部改正。第2条で兼業を定義し第3条で承認なき兼業を禁止。第4条第3項が営利企業の取締役・監査役・顧問就任、研究成果や専門的知見を活用した企業の役員・技術アドバイザー・従業員等の就任を立命館大学利益相反委員会の承認事項とする。第5条に承認の一般的基準、第6条に一週あたり8時間の時間制限、第7条に申請年度内という承認期間と更新、第11条に常任理事会による改廃を定める。立命館大学研究部サイトの共通ファイルとして公開。', 'migration:387'),
  ('reg_7c4c7f7501f8_support_rules', 'inst_catalog_7c4c7f7501f8', '大学発ベンチャーの支援に関する要項', 4, 'effective', '令和3年6月24日国際産学連携本部長決定、改正 令和4年2月22日・令和5年12月26日。支援規程第10条に基づく実施細則でPDF全文を確認。第2項が7区分の名称（研究成果・共同研究・技術移転・出資・学生・職員等・関連ベンチャー）を定義。第3項が支援内容を5つに限定列挙（公募事業での研究費支援と研究場所の貸与／貸与・使用許可した研究室の住所での登記承認／経営・財務・人材・販路・知財等の相談／講習会・起業家教育の案内／認定ロゴ使用権の付与）。第4〜7項で別記様式第1〜3号による申請手続、第8項で称号記の授与と本部サイトでの企業名公表を規定。国際産学連携本部の規則・様式集ページから取得。', 'migration:387'),
  ('reg_7c4c7f7501f8_shared_equipment', 'inst_catalog_7c4c7f7501f8', 'オープンファシリティー推進機構規程', 4, 'effective', '令和4年3月24日法人規程第39号。筑波大学規則集第5章から取得しPDF本文を確認。大学発ベンチャー専用の規程ではなく、研究設備の共用を所管する機構の組織規程である点に注意。第2条が研究設備の学内外への共用の推進と有効活用を目的と定め、第2項で研究設備の共用の全学的な実施等を業務とする。第5条第1項が全学的な運用ルール(1)と利用料金の体系(2)をオープンファシリティー推進委員会の審議事項とする。大学発ベンチャーの法人施設登記申請書（別記様式第2号）が施設の設備を使用する場合にオープンファシリティー登録の証明を求めるため、認定ベンチャーの共用機器利用はこの機構の制度で処理される。', 'migration:387'),
  ('reg_7c4c7f7501f8_external_program_support', 'inst_catalog_7c4c7f7501f8', '2026年度 事業化促進プロジェクト（下期開始分）募集要項', 4, 'effective', '2026年6月、筑波大学国際産学連携本部。年度ごとに改訂される公募要項でありURLも年度単位で変わる点に注意。PDF全文を確認。産学共同研究・ベンチャー創業準備・起業済ベンチャー成長の3コースからなり、C「起業済ベンチャー成長コース」が起業後支援のルールにあたる。要件は筑波大学発ベンチャーの代表等が代表研究者であること、本学常勤教員との共同研究または学術指導で本学へ経費の支払いがあること、貸与開始時点までに認定が完了していること。ILC棟・共同研究棟Aの研究場所を3年以内貸与し継続申請1回で通算最大6年、施設使用料・光熱水料は有償。3億円目安の資金調達後は継続申請不可。', 'migration:387'),
  ('reg_cbd79e6a149d_recognition_committee', 'inst_catalog_cbd79e6a149d', '茨城大学研究・産学官連携推進委員会細則', 4, 'effective', '規程集の現行規則一覧から発見し本文を確認。平成29年12月19日細則第33号として制定、令和8年6月25日細則第11号による改正が令和8年7月1日施行で現行有効。称号内規第5条・第8条および株式等取扱規程第4条が審議を委ねる委員会の組織・運営を定める内規で、第4条の構成(学術担当理事、各学野の研究担当副学野長等、機構長・副機構長、全学共同利用施設長)、第6条の委員長(学術担当理事)、第7条の定足数(3分の2以上)と過半数議決、第11条の庶務(研究推進部)を規定。ベンチャー認定専用の委員会ではなく全学委員会である点に注意。', 'migration:387'),
  ('reg_cbd79e6a149d_shared_equipment', 'inst_catalog_cbd79e6a149d', '茨城大学研究設備共用センター規程', 4, 'effective', '規程集の現行規則一覧から発見し本文を確認。平成27年3月31日規程第127号として制定、令和8年6月25日規程第32号による改正まで現行有効。第2条で「国立大学法人茨城大学における研究設備・機器の共用利用に関する基本方針」に基づき全学の研究設備・機器の共用とコアファシリティ化を推進、第3条第2号・第3号で学内機器情報の収集共有と他機関への共用利用促進を業務とする。学外者の具体的な利用条件と料金は本規程ではなく同センターが公表する学外者用機器利用料金表(基本料金 年20,000円、利用料金 10,000円/時間)に定められる。大学発ベンチャー専用の規程ではない。', 'migration:387'),
  ('reg_cbd79e6a149d_support_rules', 'inst_catalog_cbd79e6a149d', '国立大学法人茨城大学の住所を他の法人が法人登記上の住所として使用する場合の手続に関する要項', 4, 'effective', '規程集の現行規則一覧の「登記」検索で発見し本文を確認。令和5年2月16日要項第1号、改正なしで現行有効。第1条で他の法人(設立予定の個人・団体を含む)を支援し研究成果等の活用促進を図ることを目的とし、第3条で教職員・学生(身分喪失後1年以内を含む)が設立又は経営に深く関与し本学施設を使用又は使用予定であることを申請資格とする。第4条で登記申請予定日の1か月前までの申請と設立前の資料省略を認め、第6条で水戸・日立・阿見の3キャンパス住所を指定、第5条で学長が全学財務・施設委員会の審議を経て許可。大学発スタートアップ向けの本店登記支援を定める実質的な支援細則として登録。', 'migration:387'),
  ('reg_cbd79e6a149d_external_program_support', 'inst_catalog_cbd79e6a149d', '茨城大学学生起業支援基金(村上基金)貸与要項', 4, 'effective', '規程集の現行規則一覧の「起業」検索で発見し本文を確認。平成28年3月9日要項第50号、令和8年6月25日要項第26号による改正が令和8年7月1日施行で現行有効。第1条で村上幸一氏及びダイドードリンコ株式会社からの寄附金を原資とする外部資金型の基金を設置、第2条で学生のベンチャー起業に係る経済的負担の支援を目的とする。第4条で1件150万円以内・3年以内、第13条で無利子、第7条で選考委員会の審査を経て学長が決定、第9条で年1回の業務状況報告、第14条以下で返還・猶予・免除を規定。第6条に基づく選考委員会の内規が別途置かれている。', 'migration:387'),
  ('reg_515e2fa03507_equity_stock_option', 'inst_catalog_515e2fa03507', '長崎大学における大学発ベンチャー企業への支援の対価として取得する株式等取扱規程', 4, 'effective', 'g-reiki.netの本文を開いて全文確認。令和6年3月5日規程第6号、同日施行、改正なし。第2条で株式等＝株式及び新株予約権、大学発ベンチャー企業＝科学技術・イノベーション創出活性化法第34条の4第1項の成果活用事業者等と定義。第3条でライセンス供与等・収益を伴う事業の対価を株式等で取得可、第4条で現金非保有等の取得条件、第5条で株式等取扱委員会の議と役員会の議を経た学長決定、第6条で新株予約権の行使、第8条で経営参加権の原則不行使、第9条で処分信託による売却、第11条で補償金は換金後に支払と規定。規則集の体系目次「第5編 研究及び知的財産」から発見。', 'migration:387'),
  ('reg_d28e96c9a63e_recognition', 'inst_catalog_d28e96c9a63e', '国立大学法人金沢大学認定ベンチャー称号授与規程', 4, 'effective', '令和3年3月19日規程第3511号として制定、令和3年4月1日施行。令和6年4月1日および令和8年3月6日に改正施行。全11条。第2条で3要件と起業準備中の者の申請、第4条で学長が研究企画会議の議を経て決定、第5条で有効期間3年・以後2年ごと更新、第7条で毎年度の事業報告等の提出、第8条で取消事由11号を規定。金沢大学規程集（第1編全学規程 第5章研究）で本文全文を確認。同内容の旧版PDFが先端科学・社会共創推進機構サイトにも掲載。', 'migration:387'),
  ('reg_d28e96c9a63e_support_rules', 'inst_catalog_d28e96c9a63e', '国立大学法人金沢大学認定ベンチャー支援にかかる取扱要領', 4, 'effective', '令和3年4月1日、研究・社会共創担当理事裁定。称号授与規程第6条第2項に基づく支援の細則。第2条で支援10項目（ロゴマーク等の無償使用許諾、HPでの認定事実の公開、広報誌等での情報発信、一定の年限を区切った知的財産権の独占実施の許可、展示会での出展・紹介、協定機関への斡旋・紹介、協定機関とタイアップした経営指導・支援、補助金情報提供、表彰事業への推薦、学長が必要と認める支援）。第3条で申請時と事業報告等の提出時に希望する支援を学長へ申し出る。', 'migration:387'),
  ('reg_d28e96c9a63e_conflict_of_interest', 'inst_catalog_d28e96c9a63e', '金沢大学利益相反マネジメント規程', 4, 'effective', '令和6年5月17日規程第4186号、令和6年6月1日施行。金沢大学利益相反ポリシー（平成17年6月28日制定）に基づく全26条。第3条で起業に関わる活動を含む産学官連携活動のうち、企業等からの株式保有等の経済的利益、共同研究・受託研究、寄附金・設備の供与、施設又は設備の利用提供等を個人としての管理対象とする。第4条で組織としての管理対象、第7条で利益相反マネジメント委員会を設置、第16条で申告・審査・承認又は回避要請の手続を定める。臨床研究は別途、臨床研究利益相反マネジメント委員会が扱う。', 'migration:387'),
  ('reg_d28e96c9a63e_side_job', 'inst_catalog_d28e96c9a63e', '国立大学法人金沢大学職員兼業規程', 4, 'effective', '平成16年4月1日規程第94号。第2条第1号で兼業先との利益相反関係の禁止、第4号で経営上の責任者にならないこと（研究成果活用企業等の一部は学長が認めた場合の例外あり）。第4条で営利企業の役員兼業は原則不承認とし、技術移転事業者・研究成果活用企業の営利役員等、株式会社の監査役、社外取締役、無報酬の役員、学生の起業を支援する役員は勤務時間外に限り学長の承認で可とし、総務企画会議の審査を経る。第5条の2で本学が出資した事業者の役員兼業を承認制とする。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_d28e96c9a63e_equity_stock_option', 'inst_catalog_d28e96c9a63e', '国立大学法人金沢大学におけるベンチャー企業を対象とした収益を伴う事業の対価として取得する株式等取扱規程', 4, 'effective', '令和4年1月21日規程第3677号、令和4年2月1日施行、令和6年4月3日改正。第2条第1号でベンチャー企業を本学の研究成果を基に起業した企業等と定義、第4号で株式等を株式及び新株予約権と定義。第3条で企業側が株式等による支払いを希望し社会実装の進展が期待できるときに取得可。第4条で研究企画会議が財務状況等を審査、第5条で学長が可否を決定し契約を取り交わす。第7条で経営参加権は原則不行使。第8条で補償金は換金し収入を得た後に支払う。', 'migration:387'),
  ('reg_d28e96c9a63e_shared_equipment', 'inst_catalog_d28e96c9a63e', '金沢大学先端科学・社会共創推進機構ベンチャー・ビジネス・ラボラトリーにおけるベンチャー企業等に対する使用に係る取扱要領', 4, 'effective', '令和3年1月14日、先端科学・社会共創推進機構施設委員会決定、令和3年4月1日施行。VBL細則第8条第3項に基づき、学外使用者（設立5年以内の未上場法人、1年以内の起業予定者等）のVBL使用を定める全14条。第4条で使用期間は原則3年以内・最大5年以内。第12条で個室の使用料単価は当初3年間が1平方メートル当たり月額300円、4年目以降が月額1,000円、VBL工房は1席月額2,000円。第12条第3項で学内共同利用設備の設備エリアを使用料算定から除外。第13条でVBL長が認めれば費用の一部又は全部を免除できる。', 'migration:387'),
  ('reg_d28e96c9a63e_joint_research', 'inst_catalog_d28e96c9a63e', '金沢大学共同研究取扱規程', 4, 'effective', '平成16年4月1日規程第100号。企業等との共同研究の取扱いを定める。第2条で共同研究を本学における共同研究と本学及び企業等における共同研究に区分し、知的財産権の範囲を定義。第3条で本学は施設及び設備を共同研究の用に供し維持管理の経常経費を負担、企業等は直接経費、知的貢献費、経費執行管理費、光熱水料等を負担すると定める。大学発スタートアップに固有の減免規定は置かれていない。金沢大学規程集で確認。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_d28e96c9a63e_ip_license', 'inst_catalog_d28e96c9a63e', '金沢大学職務発明等取扱規程', 4, 'effective', '平成16年4月1日規程第6号。第17条で研究担当理事が学外者に対し通常実施権の許諾、専用実施権の設定、権利の譲渡を行うと規定。第20条で実施許諾等により本学が収入を得たときの実施補償金、第21条で譲渡により収入を得たときの譲渡補償金の支払いを定める。認定ベンチャー向けの独占実施や対価減免の特則は本規程には無く、独占実施の許可は認定ベンチャー支援にかかる取扱要領第2条第4号が定める。株式等による対価は株式等取扱規程による。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_dbbf36b7e6aa_recognition', 'inst_catalog_dbbf36b7e6aa', '国立大学法人熊本大学大学発ベンチャー等の支援に関する規則', 4, 'effective', '平成30年3月22日規則第81号、附則により平成30年4月1日施行。全12条＋別記様式第1〜4号。第2条で大学発ベンチャー／熊本大学認定ベンチャー／熊本大学認定法人を定義、第3条で区分別の支援内容（称号の授与と使用、地共ラボ・インキュベーションラボ・VBLの施設使用、認定区分は施設及び設備、登記における住所使用、知財実施権許諾の優遇措置、イベント・ウェブサイトでの紹介）と支援期間、第4条で支援条件、第5条で学長への申請と知的財産審査委員会の議を経た決定、第7条で年次事業報告、第8条で支援の取消、第10条で施設等使用の根拠を固定資産管理規則に接続。ベンチャー推進部門の大学発ベンチャー支援制度ページからPDFで公開。', 'migration:387'),
  ('reg_dbbf36b7e6aa_recognition_committee', 'inst_catalog_dbbf36b7e6aa', '熊本大学研究開発戦略本部知的財産審査委員会細則', 4, 'effective', '令和7年3月28日細則第19号、附則1により令和7年4月1日施行。熊本大学研究開発戦略本部規則（令和7年3月27日制定）第19条第2項に基づく。第3条の審議事項第4号に「大学発ベンチャー企業の認定に関すること」を明記し、支援規則第5条第2項の審査主体にあたる。第2条で本部専任教員・研究支援職員・研究コーディネーター・本部長が必要と認めた者で組織、第4条で委員長は本部長が指名、第5条で過半数出席・過半数議決、第7条で事務は研究開発戦略本部イノベーション推進部門及び研究・社会連携部産学連携推進課。附則2で熊本大学熊本創生推進機構知的財産審査委員会細則（平成30年2月26日制定）を廃止。熊本大学規則集の現行規則一覧から取得。', 'migration:387'),
  ('reg_dbbf36b7e6aa_equity_stock_option', 'inst_catalog_dbbf36b7e6aa', '国立大学法人熊本大学におけるベンチャー企業への支援の対価として取得する株式等取扱規則', 4, 'effective', '平成28年3月24日規則第49号、同日施行。改正は平成29年3月31日規則第166号、平成30年3月22日規則第162号、令和6年12月19日規則第265号、令和7年3月27日規則第133号（令和7年4月1日施行）。第2条第3号で株式等＝株式及び新株予約権、第4号でベンチャー企業を定義。第3条で支援の対価の全部又は一部を株式等で取得できる要件、第4条で知的財産審査委員会の審査と外部専門家の意見聴取、第5条で学長の決定と契約締結、第6条で売却等責任者を総務・財務・施設担当理事、第7条で新株予約権の行使、第8条で株式の売却、第9条で経営参加権の原則不行使、第10条で発明者補償金の支払時期を定める。熊本大学規則集から取得。', 'migration:387'),
  ('reg_dbbf36b7e6aa_conflict_of_interest', 'inst_catalog_dbbf36b7e6aa', '国立大学法人熊本大学利益相反管理に関する規則', 4, 'effective', '平成16年9月30日規則第274号。国立大学法人熊本大学利益相反ポリシーに基づき、産学官連携活動における役員及び職員の利益相反を管理することを目的とする（第1条）。第3条の利益相反管理の対象に、ベンチャー企業経営・コンサルティング活動等の兼業等、及び株式等を取得し保有することを含む。第4条で利益相反検討委員会を設置、第5条で委員に研究開発戦略本部リスクマネジメント部門の専任教員等を充て、第6条で自己申告書の審査と学長・部局長への報告、第7〜8条で委員長と議事、第14条で年度末の自己申告書提出と部局長の随時報告書を義務づける。外部専門家等で構成する利益相反アドバイザリーボードを置き、必要に応じモニタリング及び調査を行う。事務は研究開発戦略本部リスクマネジメント部門及び研究・社会連携部産学連携推進課。', 'migration:387'),
  ('reg_dbbf36b7e6aa_side_job', 'inst_catalog_dbbf36b7e6aa', '国立大学法人熊本大学営利企業役員等兼業及び勤務時間内非役員兼業規則', 4, 'effective', '平成16年4月1日規則第29号。職員兼業規則第6条第3項に基づき、教授・准教授・講師・助教・助手の営利企業役員等兼業及び勤務時間内非役員兼業を定める。第2条で技術移転兼業、研究成果活用兼業（当該教授等の研究成果を活用する事業を実施する企業の役員等との兼業）、監査役兼業を定義し、大学発ベンチャーの役員就任は研究成果活用兼業にあたる。第3条で承認の申出と添付書類、第4条で営利企業役員等兼業審査委員会が審査、第5条・第10条で承認基準、第11条で半期ごとの兼業状況報告と学長による公表、第14条で兼業終了の日から2年間の利害関係業務の制限。支援規則第4条第6号がこの規則の許可を認定条件に接続する。熊本大学規則集から取得。', 'migration:387'),
  ('reg_dbbf36b7e6aa_ip_license', 'inst_catalog_dbbf36b7e6aa', '国立大学法人熊本大学職務発明等規則', 4, 'effective', '平成16年4月1日規則第156号。支援規則第2条第4号・第5号が「発明等」「知的財産権」の定義をこの規則の第2条第1項・第3項に委ねる。第11条第3項で、本学が所有する知的財産権の実施、実施許諾又は処分により収益を得たときは当該知的財産権に係る発明者に補償金を支払うと定め、株式等取扱規則第10条が、支援の対価として株式等を取得した場合の同補償金は株式等を換金し収入を得た時点で支払うと接続する。大学発ベンチャーを名指しした実施料率の減免や独占許諾の優遇を定める条文は確認できなかった。熊本大学規則集から取得。', 'migration:387'),
  ('reg_dbbf36b7e6aa_joint_research', 'inst_catalog_dbbf36b7e6aa', '熊本大学における民間機関等との共同研究規則', 4, 'effective', '平成16年4月1日規則第154号。支援規則第2条第3号が定める熊本大学認定法人の要件「本学と共同研究を行っている企業等」の根拠規則。一定の場合に間接経費を減免できる規定、本学が承継した特許権等及び共有に係る特許権等について民間機関等又はその指定する者の意見を聴取したうえで第三者へ実施を許諾できる規定、実施を許諾したとき又は共有相手が実施するときに実施契約で定める実施料を徴収する規定を置く。大学発ベンチャーを名指しした優遇条項は確認できなかった。熊本大学規則集から取得。', 'migration:387'),
  ('reg_918b6fd6a473_recognition', 'inst_catalog_918b6fd6a473', '芝浦工業大学発ベンチャー登録制度のご案内（2026年4月版）', 4, 'effective', '2026年4月開始の「芝浦工業大学発ベンチャー登録制度」の公式案内資料。BOiCEページからダウンロードできる。制度概要（研究成果・技術・アイデアの社会還元とスタートアップの支援育成）、対象企業（在籍または退職5年以内の教職員、在学生・卒業生が籍を有する企業）、大学発ベンチャー6類型の定義、恩典5項目（称号付与／ロゴ使用／大学HP・広報誌等への掲載／経営相談・支援／情報提供）、支援期間（最長3年・更新2回まで）、申請書類4点を記載。制度の根拠規程本文は公開されておらず、公開文書はこの案内と登録申請書のみ。', 'migration:387'),
  ('reg_918b6fd6a473_support_rules', 'inst_catalog_918b6fd6a473', 'SITインキュベーションスクエア シェアオフィス利用規約', 4, 'effective', '令和4年12月23日版、令和6年3月28日改定。学校法人芝浦工業大学が管理運営するBOiCE内シェアオフィス等の利用条件を定める全13条。第2条で利用申請と可否判断、申込期間は1か月以上・当該年度末まで。第3条で利用料の前払いと既納分の不返還。第5条で登録抹消と退去命令。第6条14項で本施設住所を用いた商業登記等を事前許可制で認める。別表1に所在地（豊洲キャンパス本部棟10階）、事務室開室時間、利用可能スペース（シェアオフィス、コワーキングスペース、会議室2室、個室ブース）。別表2に料金区分と登記時の追加負担を規定。', 'migration:387'),
  ('reg_918b6fd6a473_shared_equipment', 'inst_catalog_918b6fd6a473', '共用研究装置・設備 学外者利用約款', 4, 'effective', '大学公式「共通機器・ものづくりセンター外部利用」ページに、2026年4月15日付で本学が制定し、2026年5月1日からこの約款に同意した外部機関の利用希望者を対象に運用すると明記されている。申請書に基づく大学の書類審査（必要に応じヒアリング）とSIT総合研究所長名の承諾書により、共通機器・ものづくりセンター（豊洲・大宮）の装置設備を利用できる制度。約款本文はこのページからは公開されておらず、利用の流れ、利用時間、料金体系（年間利用登録料＋装置利用料、大学・公的機関と民間企業等の2区分）が案内されている。', 'migration:387'),
  ('reg_918b6fd6a473_conflict_of_interest', 'inst_catalog_918b6fd6a473', '利益相反マネジメント規程', 4, 'effective', '大学公式「利益相反マネジメント」ページで、利益相反の発生およびその事実を適切に管理し、産学官連携活動等の推進と社会的信用の保持を両立するため本規程を定めていると明記。これに基づき教職員に自身の活動等の申告を求め、毎年の状況調査期間外に発生したものも随時受け付ける。同ページには利益相反マネジメント体制図と申告手順へのリンクがあるが、規程本文と関連書類は学内限定の共有サイトに置かれ外部からは閲覧できない。制定日・改定日は公開情報では確認できない。', 'migration:387'),
  ('reg_dbf1e574d1e5_recognition', 'inst_catalog_dbf1e574d1e5', '大阪公立大学発ベンチャー企業取扱規程', 4, 'effective', '令和6年10月29日規程第223号、令和6年11月1日施行、全14条。第2条で特許による技術移転型・特許以外による技術移転型/研究成果活用型・人材移転型・その他関係型の4類型を定義。第3条で学長がスタートアップ創出・支援センターの議を経て認定及び称号を付与。第8条で便宜措置（インキュベータ入居期間中の登記面住所、イベント・HPでの事業紹介、知財ライセンス対価の新株予約権化）を限定列挙。第9条で毎年9月末の事業報告、第11〜12条で取消しと意見聴取手続。附則第2項で旧両大学発ベンチャーを認定済みとみなす。公立大学法人大阪の例規集（g-reiki）本文と大学サイトのPDF（https://www.omu.ac.jp/assets/venturebusinesshandlingguidelines.pdf）の双方で全文を確認。', 'migration:387'),
  ('reg_dbf1e574d1e5_review_checksheet', 'inst_catalog_dbf1e574d1e5', '大学発ベンチャー企業認定事前チェックシート', 4, 'effective', '大学発ベンチャーページに規程の別紙として掲示。規程第4条「申請の条件」の充足性を確認する様式で、(1)第2条の4類型該当と知財・研究成果の使用許諾契約の完了状況（窓口は技術移転推進オフィス）、(2)学生雇用時の雇用契約締結・適切な対価・自由意思・本務との区分、(3)大学等への名誉毀損等のおそれ、(4)兼業申請と利益相反自己申告書の提出完了、大学等の施設・設備利用手続、大学等への物品役務提供、共同研究等の契約状況をチェック。末尾に規程遵守の誓約欄と企業名・署名欄。文書内に制定日の記載はない。', 'migration:387'),
  ('reg_dbf1e574d1e5_equity_stock_option', 'inst_catalog_dbf1e574d1e5', '公立大学法人大阪における知的財産権の運用又は処分の対価として取得する株式等の取扱規程', 4, 'effective', '令和6年9月2日規程第208号、令和6年9月4日施行。第1条で法人が所有する知的財産権の運用又は処分の対価として取得する株式及び新株予約権の取扱いを知財規程と併せて定める。第2条第1項で大学発認定ベンチャー企業を対象とし、現金を保有していない場合、現金支払いで資金繰りに窮する場合、経営に著しい影響を及ぼす場合に理事長が取得を決定できる。第2条第2項で社会的信用に問題がある場合、共益権を行使しないと著しい影響がある場合等は取得禁止。第3条で産学官民共創推進本部の審査を経て、産学官民共創担当理事が財務担当理事へ事前通知。例規集本文で確認。', 'migration:387'),
  ('reg_dbf1e574d1e5_conflict_of_interest', 'inst_catalog_dbf1e574d1e5', '大阪公立大学及び大阪公立大学工業高等専門学校教職員等の利益相反マネジメント規程', 4, 'effective', '令和4年3月31日規程第96号（令和7年3月28日改正施行）。第1条で産学官連携活動その他の社会貢献活動に生じる利益相反の適正管理を目的とする。第2条第2項で技術移転、共同研究、受託研究、教育研究奨励寄附金の受入れ、施設等の利用提供、物品購入、企業での兼業活動を産学官連携活動と定義。第2条第3項で法人職員・附属病院職員・高専教職員・役員等を対象とする。第3条第1項第3号で株式、出資金、新株予約権及び受益権等の個人的な経済的利益を管理対象とする。第4条で利益相反マネジメント委員会を設置、第7条で地区委員会への自己申告義務。発ベンチャー規程第4条第4号が本規程の手続完了を認定条件とする。', 'migration:387'),
  ('reg_dbf1e574d1e5_side_job', 'inst_catalog_dbf1e574d1e5', '公立大学法人大阪教職員兼業規程', 4, 'effective', '制定 平成31年4月1日規程30、最近改正 令和4年3月31日規程382（令和4年4月1日施行）。第2条で兼業を自営兼業、営利企業兼業（営利を目的とする会社その他の団体の職を兼ねる場合）、非営利企業兼業に区分し、大学発ベンチャーの役員就任は営利企業兼業に該当する。第3条で職務遂行への支障、兼業先との特別な利害関係、職務の公正性・信頼性への支障等がある場合は承認しない。第4条で営利企業兼業・非営利企業兼業の承認期間は原則1年以内（任期の定めのある職は4年を限度）。第5条で従事時間は原則勤務時間外。第6条で事前に兼業承認申請書を提出し理事長の承認を得る。大学の兼業依頼ページから規程PDFを取得し全文確認。', 'migration:387'),
  ('reg_dbf1e574d1e5_ip_license', 'inst_catalog_dbf1e574d1e5', '公立大学法人大阪知的財産権取扱規程', 4, 'effective', '令和4年3月31日規程第87号（令和6年4月1日施行）。第1条で学術研究の振興と成果の社会的活用を図るため大学等の役職員の知的財産権の取扱いを定める。第2条第1項で特許権、実用新案権、意匠権、商標権、回路配置利用権、育成者権、プログラム等の著作物、データベースの著作物、ノウハウを対象とする。第19〜22条で知的財産・発明委員会を設置し産学官共創・知財担当副学長が委員長、第22条の2で専門部会を置く。実施許諾の明示条文や大学発ベンチャーへの独占的実施許諾・対価減免の優遇規定は本規程には見当たらず、株式・新株予約権による対価は別途「知的財産権の運用又は処分の対価として取得する株式等の取扱規程」が定める。例規集本文で確認。', 'migration:387'),
  ('reg_dbf1e574d1e5_support_rules', 'inst_catalog_dbf1e574d1e5', '大阪公立大学インキュベータ利用細則', 4, 'effective', '大阪公立大学インキュベータ規程（令和4年4月1日規程第91号）第15条に基づく細則。附則で令和4年4月1日から施行（本文に制定日の記載はない）。第2条で活用予定の研究を行う教員等の承諾を得て学長へ入居申請、第3条で入居延長は1年以内・更新2回を限度とし「大阪公立大学発ベンチャー企業取扱要項に基づき、学長が特に認める場合にはこの限りではない」と例外を置く。第6条で部屋区分別の月額利用料と延滞損害金。第7条で大阪公立大学発ベンチャーに認定された企業等を利用料減免の対象とし、適用月から12か月間減免。第8条で共同研究室・会議室等の共用施設の利用は別途定める。大学サイトのPDFを取得し全文確認。', 'migration:387'),
  ('reg_5dee3c5a2eea_recognition', 'inst_catalog_5dee3c5a2eea', '電気通信大学発ベンチャー認定規程', 4, 'effective', '令和8年6月10日規程第9号、同日施行。全15条。認定対象の定義（第2条）、要件（第3条、経済安全保障上の誓約・情報開示を含む）、産学官連携センターに置く大学発ベンチャー認定審査委員会（第4条）、学長による認定手続（第5条）、称号の付与と5年・通算最長10年の使用期間（第6条）、報告義務（第8条）、辞退・取消し（第10・11条）、公表（第12条）、支援メニューの列挙（第13条）を定める。附則3で従前の申合せを廃止。大学規程集（第8編 研究）から取得。', 'migration:387'),
  ('reg_5dee3c5a2eea_support_rules', 'inst_catalog_5dee3c5a2eea', '電気通信大学インキュベーション施設管理運営細則', 4, 'effective', '平成23年1月18日制定、令和6年7月1日細則第1号最終改正。西11号館のインキュベーション施設の管理運営細則で、電通大発ベンチャーの育成支援を目的に明記（第2条）。ベンチャー育成支援ルーム等5施設の設置（第4条）、管理責任者は産学官連携センター長（第5条）、使用資格区分A・B（第6条）、使用期間と区分Bの最長6年更新（第7条）、産学官連携センター運営委員会の議を経た使用許可（第9条）、半期ごとの事業実績報告（第17条）を定める。大学規程集（第7編 施設）から取得。', 'migration:387'),
  ('reg_5dee3c5a2eea_side_job', 'inst_catalog_5dee3c5a2eea', '国立大学法人電気通信大学職員兼業規程', 4, 'effective', '平成16年4月1日規程第30号、令和4年2月14日規程第37号最終改正。第3条第7項で「研究成果活用企業」を定義し、第4条第2項で技術移転兼業・研究成果活用兼業・監査役兼業・役員兼業等を学長許可制とする。第9条は研究成果活用兼業の許可基準（申請者が当該研究成果を自ら創出、特別な利害関係が無いこと等）、期限付き許可、基準不適合時の取消し、終了後2年間の利害関係業務からの排除を定める。認定規程第3条第5号が本規程の手続履行を認定要件とする。大学規程集（第5編 人事）から取得。', 'migration:387'),
  ('reg_5dee3c5a2eea_ip_license', 'inst_catalog_5dee3c5a2eea', '国立大学法人電気通信大学におけるライセンス等の対価として取得する株式等取扱要項', 4, 'effective', '令和6年6月21日要項第3号、同日施行。本学の研究成果に係る知的財産権のライセンス等の対価を現金に代えて株式・新株予約権で取得する場合の取扱いを定め、ベンチャー活動支援とイノベーション創出促進を目的とする（第1条）。取得は相手方が電通大発ベンチャーで、審査を経て現金支払の免除・軽減が経営の加速に特に必要と学長が認めた場合に限る（第3条）。産学官連携センター長が財務状況等を審査し学長へ報告（第4条）。発明者への実施補償は換金後に支払（第5条）。大学規程集（第8編 研究）から取得。', 'migration:387'),
  ('reg_5dee3c5a2eea_equity_stock_option', 'inst_catalog_5dee3c5a2eea', '国立大学法人電気通信大学株式等管理規程', 4, 'effective', '令和6年6月21日規程第11号、令和7年2月21日規程第30号改正。会計規則に基づき、寄附又はライセンス等の対価として取得した株式・新株予約権の管理を定める。財務責任者が管理責任者（第2条）、上場後は可能な限り速やかに売却が原則で例外を列挙（第3条）、原則として有価証券処分信託により売却（第4条）、新株予約権は売却可能となり次第行使（第6条）、経営参加権等の共益権は原則不行使（第8条）、インサイダー取引防止措置（第9条）。大学規程集（第6編 財務）から取得。', 'migration:387'),
  ('reg_5dee3c5a2eea_shared_equipment', 'inst_catalog_5dee3c5a2eea', '電気通信大学研究設備センターにおける外部からの依頼測定等の実施に関する規程', 4, 'effective', '平成24年12月18日制定、令和2年12月25日最終改正。研究設備センターが管理する大型分析・計測機器について、民間機関等からの依頼測定と機器使用の取扱いを定める。受入条件は料金前納が原則（第4条）、申込様式（第5条）、センター長が教育研究に支障がないと認めた場合に受入れ（第6条）、料金は別表第2・第3（第8条）。第7条第2項は測定データ公表時の大学名使用をセンター長の許可制とする。大学発ベンチャー専用の区分や減免は無い。大学規程集（第11編 部局）から取得。', 'migration:387'),
  ('reg_ec744e776766_recognition', 'inst_catalog_ec744e776766', '国立大学法人豊橋技術科学大学における大学発ベンチャーの認定に関する規程', 4, 'effective', '令和元（2019）年6月19日規程第7号。大学規程集第8章「学術・研究」に全文掲載。第2条で認定対象を定義、第5条で学長が認定委員会及び戦略企画会議の議を経て認定、第6条で称号を3年間付与（再申請可）、第8条で事業報告書等の年次提出、第10条で取消し、第11条で施設貸与・商業登記の許可・研究設備の学内料金使用・起業相談・企業紹介・広報・ライセンス対価の新株予約権化を含む8項目の支援を規定。附則により令和5（2023）年4月1日施行の改正まで6回改正。', 'migration:387'),
  ('reg_ec744e776766_recognition_committee', 'inst_catalog_ec744e776766', '国立大学法人豊橋技術科学大学大学発ベンチャー認定委員会細則', 4, 'effective', '令和元（2019）年6月19日細則第3号。大学規程集第3章「委員会」に掲載。認定規程第4条第2項に基づく細則で、第2条に審議事項（認定、認定の取消し、支援事業、提出された事業報告書及び収支決算書の確認）、第3条に構成（研究推進アドミニストレーションセンター長を委員長、産学官連携推進室長、リサーチ・アドミニストレーター、人事課長、研究推進課長ほか）、第4条に定足数3分の2以上と出席委員の過半数による議決を規定。令和5（2023）年4月1日施行の改正まで2回改正。', 'migration:387'),
  ('reg_ec744e776766_conflict_of_interest', 'inst_catalog_ec744e776766', '国立大学法人豊橋技術科学大学利益相反マネジメント規程', 4, 'effective', '平成16年12月8日規程第123号。第3条で兼業・共同研究等の産学官連携活動、企業等からの金銭・便益・株式等の経済的利益、学生等の従事などを管理対象とする。第4条で最高責任者は学長、第5条で統括責任者は研究推進アドミニストレーションセンター長。第7条の利益相反審査会が第10条の自己申告書・ヒアリング等の調査を経て第11条で許容可否を審査し勧告・モニタリング。認定規程第3条第4号が本規程の手続履行を認定要件として参照する。令和5（2023）年4月1日施行の改正まで多数改正。', 'migration:387'),
  ('reg_ec744e776766_side_job', 'inst_catalog_ec744e776766', '国立大学法人豊橋技術科学大学に勤務する役職員の兼業に関する規程', 4, 'effective', '平成16年4月1日規程第39号。大学規程集第5章「人事・労務」に掲載。第4条で営利企業の役員等兼業は原則不許可としつつ、技術移転事業者、研究成果活用企業、監査役等は許可しうるとし審査会を置く。第2節（第11条から）が研究成果活用企業の役員等の兼業を定め、第13条の許可基準は当該研究成果を自ら発明・考案していること、職務内容が主として研究成果活用事業に関係すること、契約関係等の特別な利害関係がないこと等。第8条に年1回の報告、第10条に終了後2年間の業務制限。', 'migration:387'),
  ('reg_ec744e776766_equity_stock_option', 'inst_catalog_ec744e776766', '国立大学法人豊橋技術科学大学におけるベンチャー企業支援を目的とした新株予約権の取得等に関する規程', 4, 'effective', '令和4（2022）年5月11日規程第2号。第2条第3号で科学技術・イノベーション創出の活性化に関する法律第34条の4第1項の成果活用事業者のうち大学の研究成果に基づく企業等をベンチャー企業と定義。第3条で知的財産権のライセンス等その他の支援業務の対価として新株予約権を取得できる。第4条で新株予約権取得等審査会を設置、第5条で取得可否と経済条件を審議、第6条で学長が契約締結、第8条で発明者等への実施補償金の準用を規定。取得後の管理は同日制定の「取得した新株予約権の管理に関する規程」（規程第3号、rule/777.html）が定める。', 'migration:387'),
  ('reg_ec744e776766_ip_license', 'inst_catalog_ec744e776766', '国立大学法人豊橋技術科学大学知的財産ポリシー', 4, 'effective', '令和7（2025）年7月16日戦略企画会議決定。5項で研究資金・施設設備を用いた成果の特許等を受ける権利を原則として大学へ譲渡すること、譲渡・実施に対する補償制度を定める。6項「知的財産権等の活用と技術移転」の(3)で知的財産権等に基づく大学発ベンチャーの育成推進と事業化支援を掲げ、(5)で長期不実施の場合の契約解除等を規定。7項で推進体制を研究推進アドミニストレーションセンターとし(8)に大学発ベンチャー等の創出支援を含む。具体的な権利帰属と手続は職務発明等規程（平成16年度規程第97号、rule/292.html）が定める。', 'migration:387'),
  ('reg_ec744e776766_joint_research', 'inst_catalog_ec744e776766', '国立大学法人豊橋技術科学大学における民間機関等との共同研究取扱規程', 4, 'effective', '平成16年4月1日規程第99号。第2条で共同研究を定義、第6条で直接経費・知的貢献費・産学連携経費の負担を定め、第9条から第11条で申込み、学長の受入決定、契約締結の手続を規定。第14条で発明等の帰属決定と共同出願、第15条で大学が承継した知的財産権及び共有知的財産権を当該民間機関等又はその指定する者に出願等から10年を超えない範囲で優先的に実施させることができるとし、必要に応じ更新可。大学発ベンチャー専用の共同研究規程は別に置かれておらず、本規程が適用される。', 'migration:387'),
  ('reg_ec744e776766_shared_equipment', 'inst_catalog_ec744e776766', '国立大学法人豊橋技術科学大学における学内共同利用機器に係る学外者の研究設備・機器共同利用等に関する取扱要領', 4, 'effective', '平成18年3月22日制定。学外者からの依頼による学内共同利用機器での試験・測定・検査等の取扱いを定める。第2条で学長への共同利用等申込書の提出、第3条に受入条件（料金の期日納入、中止時の不返還、損害の免責、材料等の搬入出は申込者負担、講習会受講者の自ら使用、可搬型機器の学外利用等）、第4条で財産使用責任者と協議のうえ許可書を交付、第5条で秘密保持と原則として本法人名を使用できない旨、第6条で料金は別に定めるとし学長が必要と認めた場合は収納しないことができる。令和7（2025）年7月1日適用の改正まで4回改正。', 'migration:387'),
  ('reg_ec744e776766_support_rules', 'inst_catalog_ec744e776766', '国立大学法人豊橋技術科学大学イノベーション施設規程', 4, 'effective', '令和2（2020）年3月19日規程第43号。認定規程第11条第1項第1号・第2号の施設貸与と商業登記許可の実施根拠にあたる施設規程。第2条でインキュベーションスペースとオープンラボスペースを置き、第7条で創業後5年以内の個人・中小企業者、1年以内に創業しようとする個人等を使用資格とし、第10条の審査会が使用計画書を審査、第11条で使用期間は原則3年以内、1年単位で2年を限度に延長可。第16条で施設使用料と光熱水料等の負担を定める。料金と様式は同日制定のイノベーション施設使用細則（細則第13号、rule/691.html）別表1による。大学発スタートアップ支援の細則そのものは別に置かれていない。', 'migration:387'),
  ('reg_e99c8b4b8a8a_recognition', 'inst_catalog_e99c8b4b8a8a', '国立大学法人横浜国立大学発ベンチャー称号授与規則', 4, 'effective', '令和3年3月17日規則第26号、令和5年3月22日規則第38号改正、令和3年4月1日施行。全12条＋附則、様式第1号から第6号。第2条に申請資格3類型、第4条に学長申請と研究推進機構運営会議への付議、第5条に授与期間（5年後の年度末、学生は在学期間）と更新、第6条に事業報告義務、第7条に取消し、第8条に公表、第9条に免責、第10条にロゴマーク使用・施設と研究用機器の貸付配慮・学内商業登記・知的財産の使用配慮の各支援、第11条に事務所管を規定。研究推進機構の大学発ベンチャー／学生ベンチャーページからPDFで公開。', 'migration:387'),
  ('reg_e99c8b4b8a8a_equity_stock_option', 'inst_catalog_e99c8b4b8a8a', '国立大学法人横浜国立大学における認定ベンチャーを対象とした収益を伴う事業の対価として取得する株式等取扱規則', 4, 'effective', '令和3年3月17日規則第27号、令和3年4月1日施行。全11条＋別記様式第1号。認定ベンチャーへの知的財産権の譲渡・実施許諾や研究成果有体物の提供等の対価を、現金に代えて株式及び新株予約権で収納する場合の取扱いを定める。第3条に取得要件、第4条に学長申請と研究推進機構運営会議の審議、第5条に契約締結、第6条に新株予約権の行使・処分、第7条に議決権の原則不行使、第8条に売却ルール、第9条にインサイダー取引管理責任者、第10条に補償金の取扱いを規定。研究推進機構の大学発ベンチャー／学生ベンチャーページからPDFで公開。', 'migration:387'),
  ('reg_e99c8b4b8a8a_support_rules', 'inst_catalog_e99c8b4b8a8a', '国立大学法人横浜国立大学産学官連携研究施設使用規則', 4, 'effective', '平成24年12月20日規則第134号、令和7年3月28日規則第44号改正（令和7年4月1日施行）。研究推進機構規則第39条第2項に基づき、共同研究・共同研究講座・本学の研究成果に基づく起業等の支援を目的に、産学官連携研究施設の使用を定める。第3条第6号に起業予定の教職員、第7号に起業後5年以内のベンチャー企業の起業者を申請資格として明記。第4条に使用期間と更新回数、第5条に申請期日、第6条・第7条に産学官連携研究施設使用審査委員会、第9条に使用料区分、第12条に退去、第13条に取消しを規定。附則で横浜国立大学インキュベーション施設使用細則（平成16年規則第597号）を廃止。運用は産学官連携研究施設使用料等徴収方法等及び使用上の義務等に関する要項（平成27年9月30日研究推進機構長裁定）が補う。', 'migration:387'),
  ('reg_e99c8b4b8a8a_conflict_of_interest', 'inst_catalog_e99c8b4b8a8a', '国立大学法人横浜国立大学利益相反マネジメント規則', 4, 'effective', '平成23年1月20日規則第2号、令和5年3月30日規則第49号改正（令和5年4月1日施行）。第1条で産学官連携活動における利益相反の適切な管理を目的とする。第2条第1号で教職員等に役員・雇用関係にある者・産学官連携活動に参画する学生を含め、第3号で兼業報酬・特許収入・未公開株式の保有と大学における責任の衝突を利益相反と定義、第4号で企業等に大学発ベンチャー企業を含むと明記。第3条にマネジメント対象、第4条から第8条に利益相反マネジメント委員会の組織と委員長、第11条に自己申告義務、第13条・第14条に調査と審査、第15条に不服申立て、第18条に利益相反アドバイザーを規定。大学の規則集で全文公開。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_e99c8b4b8a8a_side_job', 'inst_catalog_e99c8b4b8a8a', '国立大学法人横浜国立大学教職員兼業規則', 4, 'effective', '平成16年4月1日規則第106号、令和8年3月26日規則第28号改正。教職員就業規則第46条に基づく兼業規則。第3条で兼業を5種に区分。第8条・第9条で営利企業役員兼業を原則不可としつつ、技術移転事業者役員、研究成果活用企業役員、監査役・社外取締役等を例外とする。第10条から第14条に技術移転事業者の役員兼業、第15条から第22条に研究成果活用企業の役員兼業と発起人兼業を定め、いずれも学長承認制。第12条に承認基準（特別な利害関係が無いこと等）、第14条・第19条に兼業終了後2年間の制限、第30条・第33条に従事時間（職務外兼業は週20時間まで）を規定。大学の規則集で全文公開。', 'migration:387'),
  ('reg_e99c8b4b8a8a_ip_license', 'inst_catalog_e99c8b4b8a8a', '国立大学法人横浜国立大学職務発明規則', 4, 'effective', '平成16年4月1日規則第107号、令和6年3月28日規則第36号改正。第2条第3項で知的財産権（特許権・実用新案権・意匠権・商標権・回路配置利用権・育成者権、出願段階の権利、プログラム著作物及びデータベース著作物の著作権、ノウハウ）を定義。称号授与規則第2条第1項第1号および株式等取扱規則第2条第1号が参照する上位定義。第3条第1項で大学が職務発明等に係る知的財産権を承継・所有、第12条第2項で実施許諾又は譲渡による収入があったときの実施等補償金を定め、収益を伴う事業の対価として株式等を取得した場合の補償金は認定ベンチャー株式等取扱規則（令和3年規則第27号）によるとする。認定ベンチャー固有の実施料減免・独占許諾の規定は本規則に無い。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_e99c8b4b8a8a_joint_research', 'inst_catalog_e99c8b4b8a8a', '国立大学法人横浜国立大学共同研究取扱規則', 4, 'effective', '平成16年4月1日規則第371号、令和8年3月27日規則第41号改正。本学と民間等外部機関との共同研究の取扱いを定め、認定ベンチャーも民間等外部機関として本規則の対象となる。第2条で共同研究を3形態に区分、第4条・第5条で民間機関等の長が申込書・計画書を部局長へ提出し部局長が受入れを決定、学長へ通知して契約を締結。第7条・第8条で民間等共同研究員の研究料、経費負担（大学が施設・設備と維持管理経費、民間機関等が直接必要な経費）、間接経費は直接経費の30％を原則と規定。第10条で設備の帰属を定める。大学発ベンチャー・認定ベンチャーに固有の優遇規定は本規則に無い。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_e99c8b4b8a8a_shared_equipment', 'inst_catalog_e99c8b4b8a8a', '国立大学法人横浜国立大学研究推進機構機器分析評価センター利用細則', 4, 'effective', '平成19年6月29日規則第106号、令和6年3月1日規則第17号改正。研究推進機構機器分析評価センター規則（平成16年規則第561号）第11条に基づく利用細則。第4条で利用対象者に本学の教職員・学生に加え、本学と共同研究・受託研究等の契約を締結している学外の者、機器利用の約款に同意又は個別に契約した学外の者、その他センター長が認めた者を含める。第6条で利用責任者が申請書をセンター長に提出し承認を得る手続、第15条で費用負担と収入配分を規定。称号授与規則第10条第2号の研究用機器等の貸付配慮を受ける実務経路にあたるが、大学発ベンチャー・認定ベンチャーに固有の料金区分や特別規定は本細則に無い。', 'migration:387'),
  ('reg_85fe74ab12b9_conflict_of_interest', 'inst_catalog_85fe74ab12b9', '公立大学法人横浜市立大学利益相反ポリシー', 4, 'effective', '制定 平成17年4月1日、最近改正 令和元年5月1日。上記マネジメント規程の上位文書で、同規程第1条が本ポリシーの定めに基づくものと規定している。産学連携の推進を積極的に進めつつ、教職員が企業等との関係で有する利益と大学の利益が衝突する状況を防止するための基本的な考え方を定める。先端医科学研究センターの利益相反委員会ページからPDFで公開。', 'migration:387'),
  ('reg_85fe74ab12b9_shared_equipment', 'inst_catalog_85fe74ab12b9', '公立大学法人横浜市立大学土地・建物長期貸付要領', 4, 'effective', '制定 平成17年4月1日、最近改正 平成28年4月1日。固定資産管理規程第18条に基づく施設貸付の一般規程で、大学発ベンチャー専用の規程ではないが、大学発スタートアップ創出支援ページが掲げる「土地・建物長期貸付料（居室・研究室長期貸付）の優遇措置」の直接の根拠にあたる。第2条で1月以上を長期と定義、第3条第9号で研究に係る学内の共同利用施設の貸付、第5条で理事長が契約締結、第7条で賃貸借5年以内・使用貸借3年以内、第8条で有償原則、第10条第2項第9号で理事長が特に必要と認める場合は2分の1を限度に減額、第12条で光熱水費・共益費は使用者負担。', 'migration:387'),
  ('reg_85fe74ab12b9_support_rules', 'inst_catalog_85fe74ab12b9', '横浜市立大学研究・産学連携推進センター設置規程', 4, 'effective', '制定 平成31年4月1日規程第53号、最近改正 令和7年10月1日規程第54号。組織規程だが大学発スタートアップ支援の実施体制の根拠にあたる。第2条第7号「アントレプレナーシップ教育及び大学発スタートアップ創出に関すること」と第4条第7号「スタートアップ推進部門」は令和7年8月1日から適用され、支援体制が近年整備されたことが読み取れる。第2条第6号は研究設備・機器の共用、第8号はオープンイノベーションラボ棟を所管事項とし、第7条でセンター会議を規定する。', 'migration:387'),
  ('reg_628eea47a36e_recognition', 'inst_catalog_628eea47a36e', '公立大学法人会津大学の研究成果等を活用したベンチャーへの称号の授与について', 4, 'effective', '称号認定の本体規程。第1目的、第2称号名「会津大学発ベンチャー」、第3申請資格（a特許技術活用型、b研究成果活用型、c人材移転型、d〜g大学資源活用）、第4申請書は会津大学長へ提出、第5学長が可否決定、第6称号記の授与と法的責任の不負担、第7取消しと称号記の返還、第8大学によるPR、第9雑則。附則で平成24年4月1日から適用・施行。UBIC「大学発ベンチャー紹介」ページからリンク。PDFは文字化けするため画像化して確認した。', 'migration:387'),
  ('reg_628eea47a36e_support_rules', 'inst_catalog_628eea47a36e', '会津大学における起業支援に関する規程（平成27年3月31日規程第3号）', 4, 'effective', '起業者向け支援メニューの細則。第2条で起業者・研究開発室・先端ICTラボ等を定義、第3条で8種の支援（称号付与、研究開発室、プロジェクトルーム、UBICインキュベーションスペース、先端ICTラボのリソース、本学住所での法人登記、知的財産権の使用許諾に関する措置、UBIC専任教員等による起業支援）、第4条申請先、第5条決定と学長報告、第6条事業報告（損益計算書・貸借対照表等）、第7条取消し。改正は2023年7月1日、2024年4月1日、2025年4月1日。', 'migration:387'),
  ('reg_628eea47a36e_equity_stock_option', 'inst_catalog_628eea47a36e', '会津大学における大学発ベンチャーに対する対価として取得する株式等の取扱規程', 4, 'effective', 'ライセンス等の対価を株式・新株予約権で取得する規程。第3条に取得できる4事由、第4条で理事長が職務発明審査会に審査させ外部専門家の意見も聴取、第5条取得決定、第6条契約、第7条管理責任者は総務・財務担当理事、第8条財務諸表附属明細書での開示、第9条新株予約権の行使、第10条第2項で議決権等は原則不行使、第11条売却は換金可能時点が原則で処分信託を利用、第12条インサイダー取引防止。附則で2025年4月1日施行。別紙様式1に申請書。法人規程一覧のreg165。', 'migration:387'),
  ('reg_628eea47a36e_conflict_of_interest', 'inst_catalog_628eea47a36e', '公立大学法人会津大学利益相反マネジメントに関する要綱', 4, 'effective', '利益相反マネジメントポリシーに基づく実施要綱。第5条で利益相反委員会を設置、第7条の委員は財務担当理事、産学イノベーションセンター長、コンピュータ理工学部長、同研究科長、先端情報科学研究センター長、学生部長、短期大学部長で、外部有識者の委嘱も可。第9条で委員長は財務担当理事、副委員長は産学イノベーションセンター長。第12条で毎年度4月末までに利益相反自己申告書（様式1）を提出、第13条審議と助言・指導・勧告、第14条異議申立て。平成22年6月28日理事長制定、最終改正2026年4月1日。', 'migration:387'),
  ('reg_628eea47a36e_side_job', 'inst_catalog_628eea47a36e', '公立大学法人会津大学職員兼業規程（平成18年4月1日規程第43号）', 4, 'effective', '第2条で教員が研究成果活用企業の役員等を兼ねる研究成果活用兼業および監査役兼業には学長の許可が必要と定め、同条第2項で研究成果活用企業を「教員の研究成果を活用する事業を実施する営利企業」と定義。第3条に7項目の許可基準（自ら創出した研究成果であること、契約関係等の特別な利害関係がないこと等）、第5条で氏名・企業名・職務内容・従事日時・受領報酬額を1年ごとに学長へ報告、第11条で許可期間は1年以内・更新可、第13条で許可の取消し。平成19年4月1日改正。', 'migration:387'),
  ('reg_628eea47a36e_ip_license', 'inst_catalog_628eea47a36e', '会津大学教員等の職務発明等に関する規程（平成18年4月1日規程第51号）', 4, 'effective', '職務発明の権利承継と実施補償金を定める全学規程。第3条で大学が研究資金・研究施設設備を用いた発明等の特許を受ける権利を承継、第4条勤務発明届兼譲渡証書、第5条で学長が承継の認定と決定、第14条第1項が実施補償金の配分。最終改正2026年4月1日。本規程自体に大学発ベンチャー向けの優遇条項はなく、ベンチャーへの実施料減免と株式等対価は起業支援に関する規程第3条第7号および株式等取扱規程（reg165）が受け皿となっている。', 'migration:387'),
  ('reg_628eea47a36e_joint_research', 'inst_catalog_628eea47a36e', '会津大学共同研究取扱規程（平成18年4月1日規程第58号）', 4, 'effective', '民間機関等との共同研究の全学規程。第2条で共同研究を定義、第3条受入れの原則、第4条で民間機関等が直接経費と間接経費（直接経費の10%を標準）を負担、第5条で共同研究により大学が取得した設備は大学所有、第6条共同研究申込書（様式1）を学長へ提出、第7条で学長が共同研究等受入審査委員会の議を経て受入れを決定、第13条・第14条で特許権等の優先的実施と実施料徴収。大学発スタートアップに限定した条項はない一般規程。', 'migration:387'),
  ('reg_628eea47a36e_shared_equipment', 'inst_catalog_628eea47a36e', '会津大学産学イノベーションセンター使用規程（平成18年4月1日規程第76号）', 4, 'effective', 'センター施設（各部屋と全設備。研究ラボ、運動解析室、3Dシアター、インキュベーションスペースはハードウェア・ソフトウェア・ネットワークサービスを含む）の使用規程。第5条でセンター長の使用許可または使用承認が必要、使用料は会津大学固定資産使用料規則により、減免を受ける場合は使用料減免申請書（様式3）を提出。第7条で研究開発室の使用期間上限は教員・学生5年、その他の使用者3年、1許可1年以内で年度ごとの更新。改正2017年10月1日、2019年3月26日、2024年4月1日。', 'migration:387'),
  ('reg_847658f9e871_recognition', 'inst_catalog_847658f9e871', '国立大学法人鹿児島大学発ベンチャーの認定及び支援に関する規則', 4, 'effective', '平成28年5月26日規則第51号。最終改正は令和8年3月10日施行（令和8年3月10日規則第20号）。鹿児島大学例規集（体系目次 第1編第2章第7節 社会連携）で全文を確認。全13条と別表。第2条で大学発ベンチャーの5類型、第3条で学長への申請と大学発ベンチャー認定審査会への付議、第4条で申請条件、第5条で「鹿児島大学認定ベンチャー」称号の授与、第7条で年度ごとの事業報告書提出義務、第8条でモニタリング、第10条で認定取消し、第11条で支援内容と支援期間、第12条で事務所管（研究推進部社会連携課）を規定。大学サイトにも同内容のPDFと申請様式が掲載。', 'migration:387'),
  ('reg_847658f9e871_equity_stock_option', 'inst_catalog_847658f9e871', '国立大学法人鹿児島大学におけるライセンス等の対価として取得する株式等取扱規則', 4, 'effective', '令和3年4月22日規則第25号。令和4年4月1日施行の改正あり。鹿児島大学例規集の社会連携節で全文確認。全12条。第1条で知的財産権のライセンス等の対価を現金に代えて株式等で取得する場合の取扱いを定めるとし、第2条で株式等を株式および新株予約権（新株予約権付社債を含む）、大学発ベンチャー企業を大学の職務発明等の事業化を目的として起業された会社と定義。第3条で取得の3要件、第4条で知的財産審査会による審査、第5条で学長の決定と契約締結、第7条で共益権の原則不行使、第8条で換金可能後の速やかな売却と処分信託の利用、第9条で新株予約権の行使、第10条でインサイダー取引防止を規定。', 'migration:387'),
  ('reg_847658f9e871_conflict_of_interest', 'inst_catalog_847658f9e871', '国立大学法人鹿児島大学産学官連携に係る利益相反マネジメント規則', 4, 'effective', '平成18年2月21日規則第6号。鹿児島大学例規集の社会連携節で確認。第1条で産学官連携ポリシー、知的財産ポリシー、産学官連携に係る利益相反マネジメントポリシーの趣旨に基づき利益相反マネジメントに必要な事項を定めるとする。定義規定で産学官連携活動（共同研究、受託研究、実施許諾等）、企業等からの経済的利益（給与、謝金、原稿料、株式、新株予約権等）、エクイティ（公開・未公開を問わない株式、新株予約権等）を置き、企業等の株式等の取得または事業への出資を行う場合を自己申告事由に含める。大学発ベンチャー規則第4条第4号が本規則の手続履行を認定申請の条件として引用し、株式等取扱規則第10条が本規則に基づく委員会にインサイダー取引の個別調査を求める。大学発ベンチャー専用規程ではなく産学官連携全般の規程。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_847658f9e871_side_job', 'inst_catalog_847658f9e871', '国立大学法人鹿児島大学職員兼業規則', 4, 'effective', '平成16年4月1日規則第63号。最終改正は令和8年4月1日施行。鹿児島大学例規集（第1編第2章第4節 人事）で全文確認。第3条で兼業を営利企業役員等兼業、自営兼業、弁護士等兼業、その他の4種に分類。第4条で事前に勤務割表を作成し申請書と必要書類を添えて学長の許可を得る手続を定め、第5条で所属学部運営会議等による審査、第6条で共通の許可基準（本務への支障がないこと、職責が重大でないこと、特別な利害関係のおそれがないこと、定期的な兼業は原則週8時間以内等）を規定。第9条は産学官連携活動に関連する兼業に勤務時間の一部を割くことを学長判断で許可でき、その時間の給与を減額できるとする。大学発ベンチャー専用規程ではなく職員兼業一般の規程だが、ベンチャー規則第4条第4号が引用。', 'migration:387'),
  ('reg_847658f9e871_ip_license', 'inst_catalog_847658f9e871', '国立大学法人鹿児島大学知的財産規則', 4, 'effective', '平成16年4月1日規則第41号。鹿児島大学例規集の社会連携節で確認。第1条で職員就業規則第41条に基づき職員等が成した発明等の知的財産の取扱い基準を定めるとする。第3条第4号の知的財産権の定義は、大学発ベンチャー規則第2条第1号と株式等取扱規則第2条第1号がそのまま引用しており、認定ベンチャー制度の知財概念の基礎になっている。第5条で第三者との共同発明について権利の出願、権利維持・保全、第三者に対する実施許諾・使用許諾の協議を定め、第14条で本学が実施許諾や処分により利益を得た場合の発明者への相当の対価の支払を規定。関連細則として職務発明等に対する補償金及び報奨金細則、特許等管理細則、ノウハウ・プログラム等及び研究マテリアル等管理細則が同節に並ぶ。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_847658f9e871_joint_research', 'inst_catalog_847658f9e871', '国立大学法人鹿児島大学共同研究取扱規則', 4, 'effective', '平成19年6月29日規則第75号（国立大学法人鹿児島大学共同研究費取扱規則の全部改正）。鹿児島大学例規集の五十音順目次から確認。第1条で本学と民間等外部の機関との共同研究の実施に必要な事項を定めるとし、直接経費の定義、部局長が学外機関等の所有設備を無償で受け入れ共同使用できる規定、第11条で受入部局が施設設備を利用させ維持管理経費を負担する規定、第13条で研究経費により新たに取得した設備等は原則本学に帰属する規定を置く。大学発ベンチャー規則第2条第4号は「設立後5年以内に本学と共同研究等を行い、その成果を基にした事業を行う企業等」を認定類型としており、本規則がその共同研究の一般手続を担う。認定ベンチャー専用の共同研究規程ではない。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_847658f9e871_shared_equipment', 'inst_catalog_847658f9e871', '国立大学法人鹿児島大学コアファシリティ推進本部規則', 4, 'effective', '令和4年7月21日規則第69号。鹿児島大学例規集（第1編第2章第6節 研究協力）で確認。第1条で、部局等と連携して基盤的・先進的な研究設備・機器を持続的に整備し、学内外の研究者が共用する仕組みを強化（コアファシリティ化）するとともに、研究用共用設備・機器の導入・更新等の一元管理を行うことを目的とする。審議事項に共用機器等の整備運営方針とマネジメント体制方針（戦略的設備整備・運用計画）の決定、技術職員のキャリア形成を含め、第7条で全学の共用機器等整備計画案を審議するコアファシリティ基盤設備整備委員会を置く。認定ベンチャーを名指しした条項はなく、認定ベンチャーの設備利用根拠はベンチャー規則第11条第1項第1号イの有償貸付と同条第6項。', 'migration:387'),
  ('reg_b294f39bda4b_recognition', 'inst_catalog_b294f39bda4b', '国立大学法人新潟大学における新潟大学発ベンチャーの称号授与に関する規程', 4, 'effective', '令和2年2月21日規程第13号。改正は令和2年3月11日規程第37号、令和5年3月22日規程第28号、令和8年3月27日規程第23号（令和8年4月1日施行）。趣旨・申請資格5区分・学長申請と社会連携推進機構会議の議・保持期間3年と更新・ロゴマーク使用及び施設設備利用・使用制限・取消し・公表・免責・事務（研究企画推進部）の全10条と別記様式2種を確認。新潟大学規程集（LegalCRUD）第1編全学 第7章学術・公開講座等 第1節研究支援等に収録。', 'migration:387'),
  ('reg_b294f39bda4b_equity_stock_option', 'inst_catalog_b294f39bda4b', '国立大学法人新潟大学におけるベンチャー企業を対象としたライセンス等の対価として取得する株式等取扱規程', 4, 'effective', '令和7年1月24日規程第2号、令和7年2月1日施行。全13条。ベンチャー企業の定義、株式等（株式及び新株予約権）の取得基準、発明審査委員会による審査と学長決定、会計規則に基づく管理、新株予約権の行使、共益権の原則不行使、換金可能時の速やかな売却、インサイダー取引防止と株式処分信託、職務発明規程第12条の補償金配分の取扱い、事務（研究企画推進部・財務部）を確認。新潟大学規程集で発見。', 'migration:387'),
  ('reg_b294f39bda4b_support_rules', 'inst_catalog_b294f39bda4b', '新潟大学社会連携推進機構ベンチャリング・センター規程', 4, 'effective', '令和5年4月1日社機規程第3号。社会連携推進機構規則第5条第2項に基づく設置規程。第2条で大学発ベンチャーの育成・創出支援とスタートアップ・エコシステム構築を目的とし、第3条で育成・創出及び学外機関との連携、学内ネットワークの構築・運営、研究調査と社会への発信、関連資金の獲得及び運営を業務に列挙。第4条で組織、第5条で運営会議、第6条で事務（研究企画推進部及び学務部）を規定。', 'migration:387'),
  ('reg_b294f39bda4b_recognition_committee', 'inst_catalog_b294f39bda4b', '新潟大学社会連携推進機構会議規程', 4, 'effective', '令和5年3月22日規程第25号、令和7年3月27日規程第36号改正。社会連携推進機構規則第7条第2項に基づく。第2条の協議事項に第6号「大学発ベンチャーの育成・創出に関する事項」を掲げ、称号授与規程第3条第2項が称号授与の決定に際して同会議の議を経ることを求めているため、認定審査を担う会議体の内規に当たる。第3条の組織は機構長、副機構長、各部門長、ベンチャリング・センター長、産業安全文化協創センター長、各学系選出教員等。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_b294f39bda4b_conflict_of_interest', 'inst_catalog_b294f39bda4b', '国立大学法人新潟大学利益相反マネジメント規程', 4, 'effective', '平成21年9月29日規程第32号、平成30年9月19日規程第61号まで改正。利益相反ポリシー（平成21年9月11日制定）に基づく。第3条でマネジメント対象を、産学官連携活動等を行うもの、企業等から一定額以上の金銭又は株式等を取得するもの、便益の供与を受けるもの、学生等を従事させるもの等に定める。第4条で新潟大学利益相反マネジメント委員会を設置。関連細則として産学官連携活動等利益相反マネジメント専門委員会細則も規程集に収録。', 'migration:387'),
  ('reg_b294f39bda4b_side_job', 'inst_catalog_b294f39bda4b', '国立大学法人新潟大学職員兼業規程', 4, 'effective', '平成16年4月1日規程第83号、平成26年3月31日規程第16号及び令和8年3月27日規程第19号改正。第2章営利企業の兼業に、第1節技術移転事業者の役員等の兼業（第4条－第9条）、第2節研究成果活用企業の役員等の兼業（第10条－第16条）、第3節株式会社等の監査役の兼業（第17条－第21条）、第4節その他の役員等の兼業（第22条－第25条）を置く。第12条に研究成果活用兼業の学長許可基準を定める。', 'migration:387'),
  ('reg_b294f39bda4b_ip_license', 'inst_catalog_b294f39bda4b', '国立大学法人新潟大学職務発明規程', 4, 'effective', '平成16年4月1日規程第125号。第3条第4項が知的財産権を定義し、称号授与規程第2条第1号と株式等取扱規程第2条第2号がこの定義を引用する。第4条の発明審査委員会が株式等取扱規程第4条の取得審査も担う。第12条に補償金を規定。届出・承継・任意譲渡・譲渡書の提出等を確認したが、大学発ベンチャー向けの独占的実施許諾や実施料減免の規定は置かれていない。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_b294f39bda4b_shared_equipment', 'inst_catalog_b294f39bda4b', '新潟大学研究統括機構共用設備基盤センター機器分析部門における機器登録及び登録機器の利用に関する細則', 4, 'effective', '平成29年1月24日研機細則第2号、令和5年7月26日研機細則第2号まで改正。共用設備基盤センター規程第10条に基づく。第2条で民間機関に所属する者を「学外者」、登録機器管理者の承認を得た学外者を「学外利用者」と定義。第11条第1項で利用者は経費を負担し、第2項で学外利用者の負担額は機器分析部門登録機器に係る利用料金細則（平成30年細則第36号）の定めによるとする。大学発ベンチャーが学外利用者として共用機器を使う際の根拠。', 'migration:387'),
  ('reg_b294f39bda4b_joint_research', 'inst_catalog_b294f39bda4b', '国立大学法人新潟大学共同研究取扱規程', 4, 'effective', '平成18年3月31日規程第32号。民間機関等との共同研究一般の取扱規程で、大学発ベンチャーを対象とした優遇や特則の条文は見当たらない。関連規程として共同研究講座及び共同研究部門の設置並びに運営に関する取扱細則、共同研究経費取扱細則、受託研究取扱規程が同じ新潟大学規程集に収録されている。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_d8f97d74f01a_recognition', 'inst_catalog_d8f97d74f01a', '名古屋工業大学発ベンチャーに関する規程', 4, 'effective', '平成28年3月24日規程第28号、平成28年4月1日施行。改正は平成29年9月27日規程第7号、2021年2月17日規程第19号、2021年6月23日規程第4号。全11条と様式2種。第2条に対象の限定列挙、第3条に称号授与と永年使用、第4条に学長申請と推進会議の審査、第5条に大学の法的責任の否定、第6条に報告事項、第8条に取消し、第9条にインキュベーション施設の設置、第10条に支援メニュー8号（ロゴ、施設貸与、本店登記、共用設備の学内料金、ファンド・出資対象化、情報提供、知財譲渡、その他）を定める。大学規則集で確認。', 'migration:387'),
  ('reg_d8f97d74f01a_support_rules', 'inst_catalog_d8f97d74f01a', '名古屋工業大学インキュベーション施設細則', 4, 'effective', '平成28年3月24日細則第9号、平成28年4月1日施行。改正は平成29年9月27日細則第2号、平成29年9月29日細則第3号、2021年6月23日細則第1号。発ベンチャー規程第9条第3項に基づく施設運用の細則。第2条の使用資格（名工大発ベンチャーの称号を受けた大学発ベンチャー等）、第3条の学長申請と推進会議の審査による使用許可・使用期間の決定、第5条の使用上の義務、第7条の取消し・中止、第8条の使用料（光熱水料込みの月額、別表第一）、第9条の原状回復、第11条の資産貸付規程の準用を定める。オフィスは13室。', 'migration:387'),
  ('reg_d8f97d74f01a_recognition_committee', 'inst_catalog_d8f97d74f01a', '名古屋工業大学産学官金連携機構規則', 4, 'effective', '平成29年9月27日規則第3号、平成29年10月1日施行。改正は2019年3月11日規則第10号、2023年3月22日規則第21号、2024年3月21日規則第20号。称号授与の審査主体である産学官金連携機構推進会議の設置根拠。第8条第1項で機構運営の重要事項を審議するため推進会議を置き、第2項で機構長・副機構長・学長指名の理事・リサーチアドミニストレーション室長・機構長指名の教員・事務局次長・研究支援課長・財務課長・技術部技術課長らを委員とする。第9条で機構長が委員長。第10条で事務は研究支援課が処理。認定審査に特化した独立の委員会内規は見当たらない。', 'migration:387'),
  ('reg_d8f97d74f01a_conflict_of_interest', 'inst_catalog_d8f97d74f01a', '国立大学法人名古屋工業大学利益相反マネジメント規程', 4, 'effective', '平成16年12月22日制定、最終改正2024年3月27日規程第41号。第1条で役員・職員の利益相反を適正に管理し社会への説明責任を果たすことを目的とする。第2条の対象は法人の役職員と部会が指定する者。第4条で研究インテグリティマネジメント委員会の下に利益相反マネジメント部会を置く。第3条・第6条の2の自己申告事項に、産学官連携や社会貢献活動の実施、学外からの一定額以上の金銭・便益の供与、株式等の経済的利益の取得、学生を社会貢献活動に従事させる場合等を挙げる。大学発ベンチャーを名指しした条項やストックオプションの詳細規定はない。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_d8f97d74f01a_side_job', 'inst_catalog_d8f97d74f01a', '国立大学法人名古屋工業大学職員兼業規程', 4, 'effective', '平成16年4月1日制定。第3条から第11条に営利企業の役員兼業、自営、営利企業以外の団体役員、教育関係、行政機関、独立行政法人、国立大学法人等、社会貢献、短期兼業を類型化。第3条第2号で研究成果活用企業の役員・顧問・評議員を兼ねる場合を明示し、兼業許可基準に適合すれば学長が許可できるとする。許可権者は全類型で学長。第16条に兼業審査会を置く。利益相反委員会の審査を経る旨の接続条文はない。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_d8f97d74f01a_ip_license', 'inst_catalog_d8f97d74f01a', '国立大学法人名古屋工業大学知的財産ポリシー', 4, 'effective', '平成16年4月1日制定、最終改正2026年4月8日。第1条で教育研究成果の戦略的保護と活用による社会実装の最大化を掲げる。第2条の対象は役員・職員・学生・研究員等。第3条で発明、商標、著作物、ノウハウ、研究成果有体物等を知的財産と定義。第5条で大学施設を利用した研究の発明は原則として大学に帰属。第6条で実施許諾等の収益から発明者へ相当の利益を付与。第7条の活用方針で実施許諾・権利譲渡・産学連携・大学発ベンチャー活用を列挙し、第4号で大学発ベンチャーに対し知的財産の活用に関し適切な配慮を行うとする。独占的実施許諾や実施料減免、株式対価の具体的条件は明記されていない。', 'migration:387'),
  ('reg_260332f7323a_recognition', 'inst_catalog_260332f7323a', '国立研究開発法人医薬基盤・健康・栄養研究所発ベンチャーの認定に関する規程', 4, 'effective', '令和2年6月18日令和2規程第3号。改正は令和5年2月1日、令和5年4月1日、令和5年12月1日、令和7年4月1日、令和7年6月26日（令和7規程第27号、令和7年7月1日施行）。全13条で、ベンチャー認定委員会（第3条）、様式1による申請と理事長決定（第4条）、認定条件と失効（第5条）、支援内容（第6条：場所の貸与、研究設備等の利用許可、シーズ開発支援、一定期間の優先的実施許諾、商標等の使用許可）、6か月ごとの報告義務（第8条）、取消し（第9条）、主管部署（第12条）を定める。産官学連携の認定ページの参考リンクから取得。', 'migration:387'),
  ('reg_260332f7323a_equity_stock_option', 'inst_catalog_260332f7323a', '国立研究開発法人医薬基盤・健康・栄養研究所発ベンチャーに対する支援に伴う株式又は新株予約権の取得及び保有に関する規程', 4, 'effective', '令和5年2月1日令和5規程第6号。改正令和7年4月1日（令和7規程第8号）、令和7年10月15日（令和7規程第55号）。科学技術・イノベーション創出の活性化に関する法律と、研究開発法人及び国立大学法人等による成果活用事業者に対する支援に伴う株式又は新株予約権の取得及び保有に係るガイドライン（平成31年1月17日）に基づく。取得基準（第3条）、ベンチャー認定委員会の審査（第4条）、契約記載事項（第5条）、総務部による管理（第6条）、売却と処分信託（第7条）、議決権の原則不行使（第8条）、インサイダー取引防止（第10条）を規定。各種規程等ページから取得。', 'migration:387'),
  ('reg_260332f7323a_ip_license', 'inst_catalog_260332f7323a', '国立研究開発法人医薬基盤・健康・栄養研究所職務発明等規程', 4, 'effective', '平成17年4月1日17規程第44号。改正は平成27年4月1日、平成28年1月1日、令和5年2月16日、令和5年7月19日、令和6年1月17日。発ベンチャー認定規程第6条第3項が、認定ベンチャーへの実施許諾および商標等の使用許可の契約根拠として本規程を指定している。本規程自体にベンチャーを名指しした条項はなく、職務発明の承継、審査委員会、意匠・品種に係る優先実施権（第13条、7年を超えない範囲）等を定める。各種規程等ページから取得。', 'migration:387'),
  ('reg_260332f7323a_side_job', 'inst_catalog_260332f7323a', '国立研究開発法人医薬基盤・健康・栄養研究所職員就業規則', 4, 'effective', '平成17年4月1日17規程第2号。直近改正令和7年7月1日。第9条（兼業の制限）は営利を目的とする団体の役職員・顧問・評議員の兼職および自ら営利事業に従事することを理事長の承認制とし、無報酬の場合も事前届出を求める。第11条（株式等取引の自粛）は医薬品・医療機器関連企業の株式等の取引を自粛としつつ、自らの研究開発に関連した社会実装を目的として設立されるベンチャー企業の設立出資は事前届出により除外する。発ベンチャー専用の兼業規程は公開されていない。各種規程等ページから取得。', 'migration:387'),
  ('reg_260332f7323a_joint_research', 'inst_catalog_260332f7323a', '国立研究開発法人医薬基盤・健康・栄養研究所共同研究規程', 4, 'effective', '平成17年4月1日17規程第41号。改正平成19年6月28日、平成27年4月1日、平成29年4月1日29規程第7号。共同研究の申請（別紙様式第1号）、実施要件（第3条）、契約書記載18事項（費用分担、設備及び機械器具等の使用と持込み、秘密保持、特許等の出願、研究成果に係る発明等の実施、成果公表など）を定める一般規程で、発ベンチャーを名指しした条項はない。各種規程等ページから取得。', 'migration:387'),
  ('reg_dba93faa0485_support_rules', 'inst_catalog_dba93faa0485', 'JAXAパートナースタートアップ支援約款', 4, 'effective', '全19条＋別添1。JAXAスタートアップ支援規程に基づく支援の内容、対象企業の義務、支援の条件を定める。第5条支援期間（1年・自動延長・通算上限10年）、第6条名称とシンボルロゴの使用、第7条支援措置の限定列挙と無償提供、第8条報告、第9条通知義務、第12条解除事由、第16条存続条項、第19条東京地方裁判所の専属的合意管轄。末尾名義は新事業促進部長。文書番号は25宇航新事業0912001。JAXAパートナースタートアップ募集ページから取得。', 'migration:387'),
  ('reg_dba93faa0485_recognition', 'inst_catalog_dba93faa0485', 'JAXAスタートアップ支援規程', 4, 'effective', '名称使用許可の要件を第6条、許可を第7条に置く規程で、JAXAパートナースタートアップ支援約款第1条・第2条が規程名と条番号を引用している。規程本文は公開されていないが、このJAXAパートナースタートアップ募集ページに「JAXAスタートアップ支援規程より抜粋」として許可要件4項目（成果・特許等を活用する事業を主たる事業とすること、事業の成長戦略を有すること、機構の信用を傷つけないこと、日本法に基づき適法かつ有効に設立され存続する会社であること）が逐語掲載されている。2025年8月28日の制度改正で従来のJAXAベンチャー認定制度から移行。', 'migration:387'),
  ('reg_dba93faa0485_shared_equipment', 'inst_catalog_dba93faa0485', '宇宙航空研究開発機構設備等供用約款', 4, 'effective', '全5ページ。施設設備供用制度で外部利用者が機構の設備等を利用する際の標準約款。第2条供用対象設備等（名称・目的・期間・場所は設備等利用承諾書による）、第3条善管注意義務と供用目的外利用の禁止、第4条転貸等の禁止、第5条利用の中止等、第6条中止時の使用料、第7条供用期間の変更、第8条使用料の支払い、第9条毀損等の報告、第10条原状回復と明渡し。施設設備供用の利用案内ページからリンクされている。制定日は本文に記載がない。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_dba93faa0485_ip_license', 'inst_catalog_dba93faa0485', 'JAXA知的財産ポリシー', 4, 'effective', '6節構成。第5節「知的財産の産業活用」で、産業振興の促進に向けて非独占的な利用を基本としつつ、日本版バイドールの考えも取り入れ事業者のビジネス環境に応じて独占的な利用も尊重し、対価の受領を含めライセンス方法を協議で決定すると規定。同ページ後半「JAXA知的財産の利用」に申請から契約締結、実施報告、利用料支払、更新手続までの流れを掲載し、実務基準は別PDF「JAXA知的財産利用のてびき（2024年9月）」（https://www.jaxa.jp/about/ip_policy/data/chizairiyou_tebiki_202409.pdf）の別記2徴収方式・別記3対価算定方式が定める。スタートアップ向け減免区分はない。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_dba93faa0485_side_job', 'inst_catalog_dba93faa0485', '就業規則', 4, 'effective', '全26ページ。JAXA全職員に適用される一般の就業規則であり、大学発スタートアップ専用の兼業規程ではない。第7条（兼業の制限）が「職員は、別に定めるところにより、兼業することができる」と定め、附則第2条（兼業許可等の承継）が国家公務員法第103条・第104条等に基づく従前の許可・承認を第7条に基づく「許可又は承認」とみなすと規定しており、兼業が許可制であることが確認できる。兼業の具体的手続を定める下位規程は公開されていない。附則第1条により平成15年10月1日施行。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_d161837b6c47_recognition', 'inst_catalog_d161837b6c47', 'JAMSTECベンチャー支援規程', 4, 'effective', '機構プレスリリース（2009年5月29日）本文に「JAMSTECベンチャー支援規程に基づき」と根拠規程名が明記され、脚注に対象（設立中又は設立後5年以内）、認定期間（原則5年）、優遇措置（知的財産の実施等許諾権の優遇、研究施設等の使用料減免）、発足日（平成18年4月25日）が記載されている。規程条文そのものは公開されていない。令和6年度業務実績等報告書は令和6年度に認定要件へ新株予約権付与を加える規程改正を行ったと記載。', 'migration:387'),
  ('reg_d161837b6c47_conflict_of_interest', 'inst_catalog_d161837b6c47', '利益相反マネジメントポリシー', 4, 'effective', '全文を公開。狭義の利益相反と責務相反を対象とし、利益相反マネジメント委員会の設置、外部有識者（弁護士・公認会計士等）の利益相反アドバイザー委嘱、定期自己申告と事象発生事前マネジメント、ヒアリング、是正・改善・中止の勧告、再審査申立と理事長の最終判定を定める。ページの更新日は2006年10月17日。規程番号付きの本体規程は非公開で、対象「役職員等」の範囲は各就業規程を引用して定義。', 'migration:387'),
  ('reg_d161837b6c47_side_job', 'inst_catalog_d161837b6c47', '定年制職員（研究系）就業規程', 4, 'effective', '情報公開ページで全文を公開。第13章「許可及び届出事項」第61条第1項第1号が「自己の業務を営み、又は業務を兼務し、若しくは他の業務に自己の名義を貸与するとき」を事前許可事項と定め、第2号は業務以外の目的での機構の敷地・建物・施設・物品の使用も許可制とする。第62条第2項は研究成果の取扱いを職務発明等活用規程（平19規程第107号）によるとする。大学発ベンチャー専用の兼業規程ではなく一般の就業規程。', 'migration:387'),
  ('reg_d161837b6c47_shared_equipment', 'inst_catalog_d161837b6c47', '受託等対価積算規則', 4, 'effective', '「特定共用施設の外部共用について」に、特定共用施設の使用料は機構が定める「受託等対価積算規則」に基づき徴収すると規程名が明記されている。同ページはJAMSTECベンチャー認定企業が事業実施を目的に使用する場合の使用料優遇（基本使用料の50%または無償、消耗品費等の実費は自己負担）を定める。規則本文は非公開で、確認できたのは規則名と適用される優遇内容まで。', 'migration:387'),
  ('reg_d86b5f801c06_recognition', 'inst_catalog_d86b5f801c06', '国立大学法人宮崎大学における大学発ベンチャーの取扱要領', 4, 'effective', '平成30年2月14日決定・同日実施、全13条。第2条で大学発ベンチャーの定義（知財由来、研究成果・習得技術由来、教職員等が設立者・深く関与し退職卒業から1年以内、大学の出資・出資斡旋、機構長認定）、第3条で支援内容（称号使用、施設利用、最大3年＋2年延長の登記住所、起業・経営相談、その他）、第4条で支援の条件、第6条で機構長の判定、第7条で研究・産学地域連携推進会議の決定、第9条で毎年6月末の活動報告、第11条で取消事由を規定。規程集PDFではなく機構 産学・地域連携部門のページに全文掲載。', 'migration:387'),
  ('reg_d86b5f801c06_conflict_of_interest', 'inst_catalog_d86b5f801c06', '国立大学法人宮崎大学利益相反マネジメント規程', 4, 'effective', '平成18年5月25日制定、直近改正 令和5年3月23日（令和5年4月1日施行）。第3条で企業への兼業・共同研究・受託研究、企業からの金銭や便益・株式等の経済的利益、企業からの物品購入、学生の従事を個人としての管理対象とし、組織としての利益相反も対象。第4条で学長の下に利益相反委員会を設置、第11条・第12条で委員長は副学長（産学・地域連携担当）、第16条で専門委員会、第18条で相談窓口。事務は機構事務部産学・地域連携課。国立大学法人宮崎大学規程集から取得。', 'migration:387'),
  ('reg_d86b5f801c06_side_job', 'inst_catalog_d86b5f801c06', '国立大学法人宮崎大学職員兼業規程', 4, 'effective', '平成16年4月1日制定、直近改正 令和6年3月28日（令和6年4月1日施行）。第4条で許可基準（本務に支障なく特別な利害関係が生じないこと、営利企業の事業に関与する職・職責が重大な職・常勤職は別に定める場合を除き原則不許可、週平均8時間以内、許可期間原則2年以内、自営は期間の定めなし）、第6条で部局長経由の学長への事前申請と許可、第7条で許可の取消し。大学発ベンチャー専用の兼業規程ではないが、大学発ベンチャー取扱要領第4条第5号がこの規程の手続・承認を支援の条件としている。', 'migration:387'),
  ('reg_d86b5f801c06_ip_license', 'inst_catalog_d86b5f801c06', '国立大学法人宮崎大学職務発明等規程', 4, 'effective', '平成16年4月1日制定、直近改正 令和4年9月30日（令和4年10月1日施行）。第18条（大学発ベンチャー）で、職務発明等の事業化を目的として起業された会社に対し、他に優先して当該職務発明等に係る知的財産権をライセンスし若しくはライセンス条件を優遇し又は権利譲渡をすることができると規定。第16条で退職後6か月以内の関連発明の届出、第17条で外国出願にも適用。事務は機構事務部産学・地域連携課。国立大学法人宮崎大学規程集から取得。', 'migration:387'),
  ('reg_d86b5f801c06_equity_stock_option', 'inst_catalog_d86b5f801c06', '国立大学法人宮崎大学におけるライセンス等の対価として取得する株式等取扱規程', 4, 'effective', '平成29年1月26日制定、改正 令和4年9月28日（令和4年10月1日施行）。第2条第4号で株式等を株式および新株予約権と定義し、第5号で大学発ベンチャー企業を職務発明等の事業化を目的として起業された会社と定義。第3条で取得条件と取得できない場合、第4条で学長が機構長に諮問して可否を決定、第5条で新株予約権は行使可能次第行使、第6条で議決権は原則不行使、第7条で利益相反の防止、第8条で換金可能になり次第売却、第9条で収入から必要経費を控除した額の50%を発明者等が請求可能。事務は財務部財務課。', 'migration:387'),
  ('reg_d86b5f801c06_joint_research', 'inst_catalog_d86b5f801c06', '宮崎大学共同研究取扱規程', 4, 'effective', '平成16年4月1日制定、直近改正 令和6年3月29日（令和6年4月1日施行）。企業等外部機関との共同研究の申込み・受入れ・経費（間接経費を含む）等を定める一般規程で、大学発ベンチャーを名指しした条項は無い。大学発ベンチャー取扱要領第3条第1項第2号が「本学教職員との共同研究若しくは本学教職員の技術指導等を受けて研究を実施する場合」を施設利用の前提としているため、認定ベンチャーとの共同研究にはこの規程が適用される。国立大学法人宮崎大学規程集から取得。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_d86b5f801c06_shared_equipment', 'inst_catalog_d86b5f801c06', '宮崎大学における研究設備の共同利用に関する規程', 4, 'effective', '令和2年11月26日制定、改正 令和4年9月30日（令和4年10月1日施行）。第3条で研究・企画担当副学長の下の共同利用設備管理委員会が管理し、機構研究基盤支援部門が実施を担当。第4条で利用料を設定のうえ宮崎大学設備情報データベースに登録・公開、第5条・第6条で受託試験・検査の依頼者や学内外の共同研究・プロジェクト研究の関係者に利用を認める、第7条で研究基盤支援部門長の許可、第11条で利用料の負担。大学発ベンチャーを名指しした条項は無い。附則で旧 宮崎大学産学・地域連携センター利用規程を廃止。', 'migration:387'),
  ('reg_d86b5f801c06_recognition_committee', 'inst_catalog_d86b5f801c06', '宮崎大学研究・産学地域連携推進会議規程', 4, 'effective', '令和4年9月22日制定、改正 令和5年6月19日（令和5年7月1日施行）。大学発ベンチャー取扱要領第7条が、支援の可否を審議・決定する機関としてこの研究・産学地域連携推進会議を指定している。第3条で機構長・副機構長・機構長補佐・部門長・専任教員・教育学部ほか5部局の教授又は准教授各1人等で組織、第4条で議長は機構長、第5条で委員の3分の2以上の出席により成立し出席委員の過半数で決する、第7条で専門委員会を置ける。認定審査専用の委員会内規ではなく、機構の管理運営全般を審議する会議体の規程。［検証エージェントは出典を開けず未照合］', 'migration:387'),
  ('reg_d86b5f801c06_support_rules', 'inst_catalog_d86b5f801c06', '宮崎大学研究・産学地域連携推進機構（研究・産学地域連携推進施設）利用規程', 4, 'effective', '令和4年9月22日制定（令和4年10月1日施行）。第2条第8号で「大学発ベンチャーの研究及びそのオフィス業務」を利用範囲に、第3条第5号で「大学発ベンチャーの役職員」を利用者資格に明記。第4条・第5条で機構長への利用申請と承認、第8条で承認の取消し、第9条で機器の搬入と経費の利用者負担、第11条で使用料の負担および1か月以上利用する者の光熱水費実費負担を規定。大学発ベンチャー取扱要領第3条第1項第2号の施設利用と第3号の学内本店登記の受け皿となる実施規程。', 'migration:387')
