  ('regver_d86b5f801c06_recognition_20260905', 'reg_d86b5f801c06_recognition', '現行規程', 'effective', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2018-02-14', true, 'migration:387'),
  ('regver_d86b5f801c06_conflict_of_interest_20260905', 'reg_d86b5f801c06_conflict_of_interest', '現行規程', 'effective', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/2-4-15.pdf', '2006-05-25', true, 'migration:387'),
  ('regver_d86b5f801c06_side_job_20260905', 'reg_d86b5f801c06_side_job', '現行規程', 'effective', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/2-3-33.pdf', '2004-04-01', true, 'migration:387'),
  ('regver_d86b5f801c06_ip_license_20260905', 'reg_d86b5f801c06_ip_license', '現行規程', 'effective', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/2-4-3.pdf', '2004-04-01', true, 'migration:387'),
  ('regver_d86b5f801c06_equity_stock_option_20260905', 'reg_d86b5f801c06_equity_stock_option', '現行規程', 'effective', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/2-5-52.pdf', '2017-01-26', true, 'migration:387'),
  ('regver_d86b5f801c06_joint_research_20260905', 'reg_d86b5f801c06_joint_research', '現行規程', 'effective', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/2-1-39.pdf', '2004-04-01', true, 'migration:387'),
  ('regver_d86b5f801c06_shared_equipment_20260905', 'reg_d86b5f801c06_shared_equipment', '現行規程', 'effective', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/2-5-53.pdf', '2020-11-26', true, 'migration:387'),
  ('regver_d86b5f801c06_recognition_committee_20260905', 'reg_d86b5f801c06_recognition_committee', '現行規程', 'effective', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/8-2-2.pdf', '2022-09-22', true, 'migration:387'),
  ('regver_d86b5f801c06_support_rules_20260905', 'reg_d86b5f801c06_support_rules', '現行規程', 'effective', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/8-2-6.pdf', '2022-09-22', true, 'migration:387')
insert into institution_policy_assessments (institution_id, policy_item_id, status, attribute_value, evidence_note, source_type, source_url, confirmed_at, evaluator) values
  ('inst_catalog_9ed928e1e75c', 'pol_cert_rule', 'not_started', '認定制度なし、大学名称等の使用許可で対応', '東北大学規程集（Reiki-Base、g-reiki.net）の五十音順目次を全項目取得して照合したが、大学発ベンチャー／スタートアップの認定・称号付与に関する規程・要項は存在しない。スタートアップ事業化センターの支援メニューも「ギャップファンド」「学生向けプログラム」「利益相反・法務相談」「文献・記事集」「外部アクセラ・助成金」「青葉山ガレージ」の限定列挙で、認定・称号は含まれない。学外者が本学の研究成果を活用した商品・役務に大学名を使う場合は、国立大学法人東北大学における大学名称等の使用に関する規程（令和3年規第37号）の使用許可による。', 'official', 'https://startup.tohoku.ac.jp/ssp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'attr_eligible_scope', 'established', '教職員・学生・卒業生（認定制度自体はなし）', 'スタートアップ事業化センター「コンセプト」ページに、起業活動に必要な仮説検証を人・資金・活動場所・情報の観点から「東北大学に関係する教員・学生・卒業生を幅広くサポート」すると明記。ギャップファンドプログラムは職員・学生が対象、学生向けプログラムは別枠。東北大学星陵スタートアップビレッジレンタルスペース使用内規第2条は使用範囲を「本学の教員等」および「本学の教員等が関係するスタートアップ企業等」と規定。認定制度が無いため、退職後・卒業後の年数要件や知財活用型／研究成果活用型といった認定区分は設けられていない。', 'official', 'https://startup.tohoku.ac.jp/concept/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'attr_recognition_decider', 'not_started', '認定制度がなく決裁・審査主体もなし', '認定制度が存在しないため、認定の決裁者・審査主体も存在しない。関連する決裁主体は次のとおり。大学名称等の使用は産学連携総括責任者へ申請し、産学連携総括責任者とコンプライアンス総括責任者が協議して許可を決定（大学名称等の使用に関する規程第3条・第4条）。株式等の取得は総長が審査・決定し、株式等の取得に関する諮問会議を置く（同規程第3条・第11条）。星陵スタートアップビレッジのレンタルスペース使用許可は医学系研究科長が行い、星陵スタートアップビレッジ運営委員会が使用目的等を審査（同内規第5条）。', 'official', 'https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00002785.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_cert_pre_registration', 'unknown', null, '［自動検証で否認: 「2、3ヶ月」の引用文が原文に無い、実際は2ヶ月前］元の主張(established): 登記前に利益相反審査と兼業許可を完了する運用。スタートアップ事業化センターが掲載する「スタートアップ設立に係る学内手続き」（2024年12月掲載）に、教員がスタートアップを設立する場合は「登記までのスケジュールに2、3ヶ月程度の余裕を持って、①利益相反マネジメント委員会の承認、②兼業申請の二つを行なってください」と明記。提出書類のうち定款は案で可、履歴事項全部証明書のみ登記後の追加提出とされ、設立登記前に学内手続きを完了させる建て付け。認定制度自体が無いため、認定予定通知や条件付認定という枠組みは存在しない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'attr_validity_years', 'not_started', '認定制度がなく有効期間の定めなし', '認定制度が存在しないため、認定の有効期間・更新の規定も存在しない。期間の定めがあるのは施設使用で、東北大学星陵スタートアップビレッジレンタルスペース使用内規第3条は「原則として1年を単位として使用させる」「使用の期間は、最長で5年間とする。ただし、医学系研究科長が特に適当と認めるときは、所定の審査を経て延長することがある」と規定。使用者は期間変更・取りやめの場合、60日前までに医学系研究科長へ申し出て承認を受ける（第10条）。', 'official', 'https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00003005.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_head_office_registration', 'established', '可、青葉山ガレージで本社登記可（料金は非公開）', 'スタートアップ事業化センター「青葉山ガレージ」ページに「東北大関連ベンチャーの方は本社登記を行いオフィスとしてのご利用も可能です」と明記。「スタートアップ支援プログラム」ページの各種サポート欄も「登記や活動場所として使用できる施設(青葉山ガレージ)の提供を行っています」と記載。「ガレージ」ページには「登記に関する内規」と題したボタンがあるが、リンク先がサイトトップに戻る設定になっており内規本文は公開されていない。登記利用の有償無償・要件も公開情報では確認できない。', 'official', 'https://startup.tohoku.ac.jp/aobayama_garage/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_facility_lease', 'established', '有償、星陵スタートアップビレッジ等を1年単位で貸与', '東北大学星陵スタートアップビレッジレンタルスペース使用内規（2025年11月12日制定、2026年3月1日施行）第2条が、本学の教員等および教員等が関係するスタートアップ企業等に、研究シーズ育成・事業化推進のためレンタルスペースを使用させると規定。原則1年単位・最長5年、審査を経た延長可（第3条）。使用料は建物等の基本料金と光熱水料等の実費弁償的な付帯料金で、本学教員等・関係スタートアップは学外一般より低い区分（第6条・別表）、医学系研究科長が認めれば減免（第8条）。ほかに青葉山・川内・星陵の各ガレージが常設スペース。', 'official', 'https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00003005.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_shared_equipment', 'established', '可、研究基盤利用ポータルで学外・一般企業も利用可', '産学連携機構「共用機器利用」ページが、学内共用機器の利用受付を東北大学研究基盤利用ポータル（コアファシリティ統括センター運営、設備統合管理システムSHARE）に集約すると案内。同ポータルのFAQ「学外の人も技術相談や設備利用はできますか。」（2024年12月5日更新）は、設備詳細ページの「利用区分」が「学外：〇」であれば利用可能と回答。FAQ「一般企業も施設利用可能なのでしょうか？」（2025年5月21日更新）は、一部学内利用限定の設備を除き基本的に一般企業も利用可能と回答。大学発ベンチャー専用の料金区分は公開情報では確認できない。', 'official', 'https://portal.cfc.tohoku.ac.jp/faq/epkb_post_type_1-9200/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_name_logo_use', 'unknown', null, '［自動検証で否認: 第5条は6基準、noteの「5基準」は誤り］元の主張(established): 許可制、産学連携総括責任者の許可と使用許諾契約が必要。国立大学法人東北大学における大学名称等の使用に関する規程（令和3年3月30日規第37号、令和8年5月12日規第102号改正）。第2条で「国立大学法人東北大学」「東北大学」「東北大」「TOHOKU UNIVERSITY」等とロゴマーク規程のロゴマークを対象とし、共同研究・受託研究・学術指導等の契約に基づく研究成果を活用した商品・役務への使用を規律。第3条で産学連携総括責任者へ申請、第4条で同責任者とコンプライアンス総括責任者が協議して許可、第6条で使用許諾契約を締結。第5条に本学成果に基づくこと等5基準。称号付与制度ではない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_ip_license', 'established', '一時金＋継続実施料、継続分は新株予約権に置換可', '産学連携機構「本学発スタートアップへの技術移転の基本的考え方」ページ。スタートアップへの技術移転の対価は、権利化・維持の実費相当の「一時金」と「継続実施料（ランニングロイヤリティ）」の二階建てが基本。一時金は現金回収が基本だが事業計画に応じて分割払い可、継続実施料はスタートアップの事業計画等に応じて新株予約権に置換可能で、マイルストーン設定とのハイブリッドも可。譲渡（専用実施権含む）と独占的通常実施権を選択でき、独占的通常実施権から将来の譲渡へ切り替えるオプションを契約に設定可能。対価の減免規定の記載はない。', 'official', 'https://www.rpip.tohoku.ac.jp/jp/property/gijutsuiten_to_su.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_equity_rule', 'established', '可、株式・新株予約権の取得規程あり（総長決定）', '国立大学法人東北大学における株式等の取得に関する規程（平成31年3月26日規第43号、令和6年7月9日最終改正）。第1条で株式および新株予約権を対象と定義。第2条は取得できる場合を限定列挙し、国立大学法人法第22条第1項第6～9号・第34条の2に基づく出資、寄附のほか、第7号で研究成果の技術移転先として設立された企業等が対価を現金で支払うことが困難な場合に当該企業発行の株式等を取得できると規定。第3条で総長が株主構成・財務状況等を考慮して審査、第11条に株式等の取得に関する諮問会議。別途100％出資VCの東北大学ベンチャーパートナーズが投資。［検証エージェントは出典を開けず未照合］', 'official', 'https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00002657.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_gap_fund', 'established', 'あり、BIP（2013年開始、Phase制の事業性検証資金）', 'スタートアップ事業化センターのギャップファンドプログラム＝ビジネスインキュベーションプログラム（BIP）。研究成果を活用した事業アイデアの検証を支援し、採択後はユーザーインタビュー・プロトタイプ開発・検証チーム組成を行う。Phase別に支援内容を設定し、経営人材または事業化体制が整った案件向けのPhase3（スタートアップ組成・大型資金獲得フェーズ）は事業性検証資金を提供するが2026年度は公募予定なし。過去100件以上採択、うち30件以上（2025年度時点）が起業に到達。東北・新潟の大学で共同運営する「みちのくギャップファンド」を2021年から実施。［検証エージェントは出典を開けず未照合］', 'official', 'https://startup.tohoku.ac.jp/gap_fund_program/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_accelerator', 'established', 'あり、スタートアップガレージの伴走とBIP法務・知財相談', 'スタートアップ事業化センター作成資料「東北大学のスタートアップ支援について」（2025年3月14日）に、東北大学スタートアップガレージ（起業家育成プロジェクト）が青葉山・川内・星陵の常設コミュニティスペースを拠点に、起業塾・ピッチイベントの開催、大学シーズと企業のマッチング、VC・金融機関と連携した資金調達支援、メンターによる起業相談と立ち上げ支援、OBOG・アドバイザーの支援を行うと記載。アントレプレナーシップ育成プログラムは令和5年度受講者2,328名。BIP採択者はAZX総合法律事務所への法務・知財相談が可能。［検証エージェントは出典を開けず未照合］', 'official', 'https://impact-consortium.fsa.go.jp/wp-content/uploads/2025/06/wg03_fw02_ref03.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_coi_sidejob', 'established', '兼業許可申請と利益相反委員会審査を兼業開始前に必須', '「スタートアップ設立に係る学内手続き」に、新たに法人を設立し出資して兼業する場合は兼業開始前に利益相反マネジメント委員会の審査を受ける必要があると明記。提出物は事象発生前自己申告書、事象発生前自己申告に係る照会、役員等兼業許可申請書の写し、定款（案可）等で、原則申請月の翌月に委員会。留意点として、代表権を有する場合は本学と雇用関係のない共同代表者を設置、本学との契約時は自身が代表として署名しない、代表権があっても経営に携わらない、呼称であってもCEOに就かない、の4点を遵守と通知。根拠規程は利益相反マネジメント規程と職員兼業規程（平成16年規第60号）。', 'official', 'https://startup.tohoku.ac.jp/cms/wp-content/uploads/2024/12/%E3%82%B9%E3%82%BF%E3%83%BC%E3%83%88%E3%82%A2%E3%83%83%E3%83%97%E8%A8%AD%E7%AB%8B%E3%81%AB%E4%BF%82%E3%82%8B%E5%AD%A6%E5%86%85%E6%89%8B%E7%B6%9A%E3%81%8D.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'attr_support_fee', 'established', '有償と無償の併存、施設使用料と知財対価は有償', '星陵スタートアップビレッジのレンタルスペースは基本料金と光熱水料等の付帯料金を納付する有償で、医学系研究科長が必要と認めた場合のみ一部または全部を徴収しない（同内規第6条・第8条）。知財の技術移転は一時金と継続実施料を支払う有償（本学発スタートアップへの技術移転の基本的考え方）。共用機器は研究基盤利用ポータル経由で設備ごとの利用区分・料金。一方、ギャップファンドは大学側からの資金提供、青葉山ガレージの入退室やBIP採択者向け法務・知財相談、研究基盤の技術相談には費用の記載がない。', 'official', 'https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00003005.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'attr_certified_count', 'established', '大学発SU283社超と公表、全社一覧は非公開', 'スタートアップ事業化センターのトップページに「東北大学ではこれまで教員主導・学生主導合わせて283社を超える」スタートアップが生まれているとの記載。認定制度が無いため「認定社数」という概念はなく、これは大学発スタートアップの累計社数。支援実績ページはベンチャーインタビュー（研究開発企業・学生企業）とギャップファンド支援実績・THVP投資実績を掲載するのみで、全社を網羅した一覧は公開されていない。ギャップファンドについてはBIP採択者リストがPDFで公開されている。', 'official', 'https://startup.tohoku.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_cert_rule', 'established', '森林総研発ベンチャー認定制度（ベンチャー支援規程）', '「国立研究開発法人森林研究・整備機構の研究開発分野におけるベンチャー支援規程」（令和7年3月11日6森林機構1078号、令和7年4月1日施行）第1条・第2条。森林総合研究所、林木育種センター、森林バイオ研究センター（森林総合研究所等）の所有する知的財産権を活用する成果活用事業者を「森林総研発ベンチャー」と認定する。認定書（様式2甲）の称号は「森林総研発ベンチャー企業」。産学官民連携ページにも同規程に基づき申込みを受け付ける旨を掲載。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'attr_eligible_scope', 'established', '知財活用型の成果活用事業者、設立から概ね10年以内', '第5条各号。一号=科学技術・イノベーション創出の活性化に関する法律第34条の4第1項の成果活用事業者であること、二号=研究成果の社会実装の実現が見込まれること、三号=森林総合研究所等の業務に支障を与えないこと、四号=公序良俗に反しないこと、五号=設立した日から概ね10年を経過していないこと。役職員・退職者・学生といった個人属性による区分はなく法人単位で判定する。産学官民連携ページも「知的財産権を活用する成果活用事業者（ただし、起業して10年以内）」と記載。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'attr_recognition_decider', 'established', '理事長（ベンチャー認定委員会の答申）', '第4条。申請者は様式1を理事長に提出し、理事長が委員会に諮問、委員会が審査と必要に応じた面接を行い理事長に答申、理事長が認定および支援内容の可否を決定して様式2で通知する。委員会（第3条）の委員長は理事（企画・総務・森林保険担当）、委員は理事3名、総括審議役、企画部長、研究リスク管理監、研究企画科長、研究管理科長、社会実装推進・知財戦略室長、総務部長ほか。外部有識者等の出席を求めることができる。主管部署は企画部研究管理科（第12条）。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_cert_pre_registration', 'not_started', '設立済み法人が前提、登記前申請・条件付認定なし', 'ベンチャー支援規程に設立登記前の申請や認定予定通知の定めはない。第5条第5号が「設立した日から概ね10年を経過していないこと」を要件とし、申請様式1の添付書類は会社定款、事業計画書、会社経歴書、決算報告書（直近2カ年分）、代表者の履歴書に限定列挙されている。理事長の通知様式も認定書（様式2甲）と不認定の結果通知書（様式2乙）の2種類のみで、条件付認定や認定予定通知の様式は置かれていない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'attr_validity_years', 'established', '5年・延長申請でさらに5年', '第5条本文「その有効期間は認定の日から5年間とする。ただし、延長申請を妨げないものとし、その有効期間はさらに5年間とする」。延長は第4条第1項の様式1により新規と同じ手続で申請する（様式1に「新規・延長」の選択欄）。認定期間は認定書（様式2甲）に記載。認定の取消しは第9条、認定を受けた側からの解除申出は第10条・様式5。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_head_office_registration', 'unknown', null, 'ベンチャー支援規程第6条第1項第1号は事務室または研究室として森林総合研究所等内に場所を確保し貸与することを定め、第2項で不動産等管理規程（13森林総研第84号）に基づく契約を締結するとするが、その場所を会社の本店所在地として商業登記できるかについては規程にも産学官民連携ページにも記載がない。施設案内ページに掲載されているのは図書館、樹木園、もりの展示ルーム、構内図のみで、インキュベーション施設の入居要項や利用規程は公開されていない。', 'unknown', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_facility_lease', 'established', '所内の事務室・研究室を貸与、有償（貸付料減免可）', '第6条第1項第1号「事務室又は研究室として森林総合研究所等内に場所を確保し、貸与すること」。第2項で不動産等管理規程（13森林総研第84号）に基づく契約を締結し、理事長が適当と認めるときは貸付料の減免等の措置をとることができる。貸与する場所・内容・期間は支援内容通知書（様式2甲の別紙）に個別記載される。専用のインキュベーション施設名は公開情報では確認できない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_shared_equipment', 'established', '研究設備等の利用許可、有償（貸付料減免可）', '第6条第1項第2号「研究設備等の利用を許可すること」。第3項で物品管理規程（13森林総研第83号）に基づく契約を締結し、理事長が適当と認めるときは貸付料の減免等の措置をとることができる。利用場所・内容・期間は支援内容通知書に記載。認定ベンチャー専用の料金表は非公開だが、共同研究向けには「共同研究に利用できる施設及び機械・機器」一覧（2026年7月更新）が公開され、実大材料試験機、電子顕微鏡、核磁気共鳴装置、DNAシーケンサー等が掲載されている。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_name_logo_use', 'established', '「森林総研発ベンチャー企業」称号と成果活用ロゴマーク使用許諾', '認定書（様式2甲）は「森林総研発ベンチャー企業」として認定する旨を記載する。第6条第1項第3号は支援として「森林総合研究所等が所有する知的財産権（森林総研成果活用ロゴマークを含む。）の実施権の許諾又は設定」を明記。産学官民連携ページは成果活用ロゴマーク（商標登録7023503）について、特許の実施許諾契約を締結した事業者はこのロゴも使用許諾できるとする。認定取消し後は認定を受けていた事実を利用した事業を禁止（第9条第2項）。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_ip_license', 'established', '実施料減免と一定期間の優先的実施、専用実施権も設定可', 'ベンチャー支援規程第6条第4項は知的財産権実施規程（13森林総研第72号）に基づき実施契約を締結し、理事長が適当と認めるときは一定期間の優先的な実施や実施料の減免等の措置をとることができると定める。同実施規程第3条は原則を通常実施権としつつ、申出があり必要と認めた場合は専用実施権を設定できるとする。知的財産ポリシー（令和4年4月）4(3)も、有効活用が促進され公益性・公平性に問題がない場合は範囲・期間を限定した独占的実施許諾や無償実施許諾を行うとする。株式対価の定めはない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_equity_rule', 'not_started', '出資・新株予約権の規程なし、対価は現金の実施料', 'ベンチャー支援規程第6条第1項の支援は一号（場所の貸与）、二号（研究設備等の利用許可）、三号（知的財産権の実施許諾・設定）、四号（理事長が必要と認めるその他の支援）の列挙で、株式・新株予約権の取得は含まれない。知的財産権実施規程第7条第2項は実施料を契約に定める期間内に銀行振込みで受けると定め、株式等による対価の規定はない。科学技術・イノベーション創出の活性化に関する法律第34条の4・第34条の5は研究開発法人による株式等の取得を認めるが、機構側の規程整備は公開情報では確認できない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_gap_fund', 'not_started', 'GAP・起業準備資金の制度なし', 'ベンチャー支援規程第6条第1項が定める支援は場所の貸与、研究設備等の利用許可、知的財産権の実施許諾の3類型と理事長が認めるその他の支援で、資金の供与は含まれない。産学官民連携ページの掲載メニューも実用化カタログ、展示会、外部ネットワーク連携、共同研究・受託研究、NDA、MTA、実施許諾契約、ベンチャー支援、知的財産ポリシーで、GAPファンドやPOC資金の記載はない。2025年・2026年のプレスリリース一覧にも該当する制度の発表はない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_accelerator', 'not_started', '伴走・アクセラ制度なし、窓口は社会実装推進・知財戦略室', 'ベンチャー支援規程第6条第1項の支援にメンタリングや伴走支援は含まれない。産学官民連携ページは産学官民・国際連携推進本部を設け、社会実装推進・知財戦略室が橋渡しの具体的案内と共同研究等のコーディネートの窓口となり、支所に産学官民連携推進調整監を置くとするが、いずれも産学官民連携一般の窓口でアクセラレーションプログラムの掲載はない。知的財産権実施規程第9条の技術指導・役職員派遣は費用を実施者が負担する。', 'official', 'https://www.ffpri.go.jp/sangakukan/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_coi_sidejob', 'established', '兼業取扱規程による兼業、知財許諾時に利益相反申告', 'ベンチャー支援規程第6条第5項「機構の役職員が森林総研発ベンチャーの活動を行う場合は、国立研究開発法人森林研究・整備機構職員の兼業取扱規程（17森林総研第1542号）に基づき兼業として行うものとする」。知的財産権実施規程の別紙様式（知的財産権実施申込書）の森林総合研究所記入欄には「利益相反の有無 □有 □無」の申告欄と対象者記載欄がある。ベンチャー認定委員会には法令遵守担当理事と研究リスク管理監が入る（第3条第3項）。利益相反マネジメント規程そのものの本文は公開されていない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'attr_support_fee', 'established', '有償が原則（貸付料・実施料）、理事長判断で減免', 'ベンチャー支援規程第6条第2項（場所の貸与は不動産等管理規程に基づく契約、貸付料の減免等が可能）、第3項（研究設備等の利用は物品管理規程に基づく契約、貸付料の減免等が可能）、第4項（知財は知的財産権実施規程に基づく実施契約、実施料の減免等が可能）。いずれも契約締結と対価の支払が前提で、理事長が適当と認めるときに限り減免される。産学官民連携ページも認定した場合に「各種支援のほか許諾・使用料の減免をすることができます」と記載。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'attr_certified_count', 'unknown', null, '産学官民連携・知的財産ページ、施設案内ページのいずれにも森林総研発ベンチャーの認定企業一覧や社数の掲載がない。機関自身のプレスリリース一覧（2025年・2026年）を確認したが認定に関する発表はなく、2025年9月10日の「産学官民連携・知的財産のホームページをリニューアル」の発表でも掲載内容としてベンチャー支援の項目名が挙がるのみで認定実績の記載はない。規程の施行は令和7年4月1日。', 'unknown', 'https://www.ffpri.go.jp/press/2025/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_cert_rule', 'established', 'AISolスタートアップ認定制度（旧・産総研技術移転ベンチャー称号は廃止）', '産総研の称号制度の根拠だったベンチャー支援規程（令02規程第8号）は「ベンチャー支援規程を廃止する等の規程」（令06規程第31号）で廃止された。研究施設等の利用及び貸付に関する規程の附則（令06規程第50号）第2条第3項が廃止の事実と経過措置を明記し、施行は2025年4月1日。現在は産総研全額出資の株式会社AIST Solutions（AISol）が「AISolスタートアップ」として認定し、産総研のスタートアップ推進ページもスタートアップ活動はAISolが中心と記載。', 'official', 'https://www.aist-solutions.co.jp/aisol_startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'attr_eligible_scope', 'established', '産総研の成果を活用し産総研とシナジーのある株式会社等', 'AISolのスタートアップ支援ページは、社会課題解決への貢献・技術的競争優位性・市場性・産総研とのシナジーの観点から産総研グループの経営戦略に照らして相応と判断される企業をAISolスタートアップと認定すると記載。産総研の出資対象は成果活用事業者出資業務規程第5条で、活性化法第34条の6第1項第1号の成果活用事業者かつ会社法上の株式会社・合同会社等と限定。旧称号にあった「設立5年以内」要件は規程廃止で根拠を失った。', 'official', 'https://www.aist-solutions.co.jp/aisol_startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'attr_recognition_decider', 'established', 'AISolが認定、産総研の出資は理事長決定', 'AISolスタートアップの認定はAISolが産総研グループの経営戦略に照らして判断（AISolスタートアップ支援ページ）。産総研の出資は成果活用等支援法人出資業務規程第6条で「委員会の審議の結果を踏まえ、理事長が決定する」と定め、第3条から第5条で外部有識者中心の出資委員会を設置。成果活用事業者出資業務規程は第3条で成果活用事業者出資委員会、第7条で研究所が審査し出資先を決定と規定。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/seikakatsuyou_shusshi.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_cert_pre_registration', 'unknown', null, 'AISolスタートアップ認定にも産総研の出資にも、設立登記前の申請受付や認定予定通知・条件付認定の記載を公開情報で確認できなかった。成果活用事業者出資業務規程第5条第2号は出資先を会社法上の株式会社・合同会社等に限定しており、条文上は設立済み法人を前提とした書き方。産総研グループが参画する1stRoundの募集要項は本調査では未取得。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'attr_validity_years', 'unknown', null, 'AISolスタートアップ認定の有効期間・更新の記載は公開ページに見当たらない。旧・産総研技術移転ベンチャー称号は、産総研スタートアップ推進・技術移転部「産総研のスタートアップ創出の取組」2022年8月版が「5年間（延長により最大10年間）」と記載していたが、根拠のベンチャー支援規程は2025年4月1日に廃止済みで、現行制度の期間としては使えない。', 'unknown', 'https://www.aist.go.jp/Portals/0/images/business/alliance/startups/aist_startup20220801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_head_office_registration', 'unknown', null, '産総研の敷地・建物の住所を会社の本店所在地として商業登記できるかについて、研究施設等の利用及び貸付に関する規程（令05規程第49号）にも公開ページにも記載を確認できなかった。同規程第3条は占有を伴う「貸付」を認めるが、登記の可否には触れていない。産総研に隣接するインキュベーション施設は別法人の運営で、産総研自身の制度ではない。', 'unknown', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/shisetsuriyoukashitsuke.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_facility_lease', 'established', '研究施設等の貸付あり、AISol経由の転貸も可', '研究施設等の利用及び貸付に関する規程（令05規程第49号、2024年4月1日施行）第3条第1項第4号が貸付の受入要件を列挙し、同号ヘで経済産業省関係産業競争力強化法施行規則第14条の25の研究施設等を「新たな事業活動を行う者」が利用する場合を明記。第12条はAISolが転借人へ転貸するための一時利用・貸付の特例。第3条第4項で賃貸借契約等を締結し、第6条で利用料等を徴収。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/shisetsuriyoukashitsuke.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_shared_equipment', 'established', '一時利用で研究設備・装置を利用可、利用料は徴収', '研究施設等の利用及び貸付に関する規程（令05規程第49号）第2条第4項が占有を伴わない「一時利用」を定義し、第3条で受入要件、第5条で研究施設等の操作・運転の役務提供、技術指導、技術代行を規定。第6条で利用料等を利用者から徴収でき、算出方法は別に定めるとする。AISolのスタートアップ支援ページも技術サービスとして産総研の先端装置活用と研究施設・装置利用支援を掲載。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/shisetsuriyoukashitsuke.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_name_logo_use', 'unknown', null, '認定企業が称号やロゴ・マークを使用できるかの条件を公開情報で確認できなかった。旧制度では「産総研の成果を使った事業を行う『産総研技術移転ベンチャー』として産総研が特別に認めた企業が使用できるマーク」が資料に示されていたが（2022年8月版資料）、根拠のベンチャー支援規程は廃止済み。AISolの公開ページには認定企業側の称号・ロゴ使用条件の記載がない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_ip_license', 'established', '独占・一部独占の実施許諾可、無償許諾と知財現物出資も可', '知的財産権の実施許諾及び譲渡に関する規程（13規程第15号）第2条第2項が有償・無償いずれの実施許諾も認め、第3条が独占的・一部独占的実施許諾を規定。第4条は、当該知財の創造に寄与した役職員等が転出する場合にその転出先へ独占的実施を許諾する際、一般への公示と異議申立ての手続を要しない特例を置く。成果活用事業者出資業務規程第2条・第13条は知的財産権を現物出資して株式等を取得する扱いを定める。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/chizai.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_equity_rule', 'established', '出資規程2本、株式・新株予約権・持分を取得可', '成果活用事業者出資業務規程（令01規程第15号、2019年10月3日制定）第2条が株式等を株式・新株予約権・持分と定義し、第4条で金銭と金銭以外の財産（有形固定資産・知的財産権）の出資を認め、議決権は原則3分の1未満に制限。第3条で成果活用事業者出資委員会、第9条の2で一号出資管理者、第12条で株式等の処分を規定。成果活用等支援法人出資業務規程（令04規程第23号、2022年10月12日制定）はAISol等への出資を定める。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/syuxtushi.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_gap_fund', 'established', '1stRoundに産総研グループとして参画、非稀釈型の資金支援', 'AISolの2025年10月6日お知らせで、産総研とAISolが創業成長支援プログラム1stRound（東京大学協創プラットフォーム開発と22大学5研究機関の共催、ディープテック分野のスタートアップ創出・成長支援）に参画したと公表。東京大学IPCのリリースは同プログラムを株式取得を伴わないNon-Equity型の資金支援とハンズオン支援と説明。産総研独自のGAPファンド・POC資金の制度は公開情報で確認できなかった。', 'official', 'https://www.aist-solutions.co.jp/news/page000387/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_accelerator', 'unknown', null, '［自動検証で否認: 窓口「プロデュース事業本部スタートアップ部」が原文に無い］元の主張(established): AISolの成長支援5サービスと1stRoundのハンズオン支援。AISolのスタートアップ支援ページが技術・マーケティング・知財・グローバル展開・資金関連の5サービスを掲げ、VCやインキュベーターと協力した育成プログラムの実施、人材育成・各種セミナー・アドバイザー紹介、国内外VCの紹介とマッチング機会の提供を明記。窓口はプロデュース事業本部スタートアップ部。加えて2025年10月に産総研グループとして1stRoundに参画し、ハンズオン支援の枠組みに入った。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_coi_sidejob', 'established', '役員兼業は理事長許可・原則2年、エクイティ報酬も規程化', '兼業等規程（17規程第13号）第3条が兼業等審査委員会を置き、第5条で理事長が同委員会の認定を経て役員兼業を許可し許可期間は原則2年以内、第7条で役員兼業休職、第10条で勤務時間内役員兼業、第5章（第29条・第30条）で兼業先から受ける株式等による報酬（エクイティ報酬）の届出を規定。利益相反マネジメント実施規程（令01規程第29号）第2条は兼業・株式等保有・知財保有を個人的利益と定義し出資も対象に含め、第13条・第14条で定期および事前の自己申告を課す。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/kengyo.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'attr_support_fee', 'established', '原則有償（施設利用料等）、知財許諾は有償・無償の双方可', '研究施設等の利用及び貸付に関する規程（令05規程第49号）第6条が「利用に係る利用料等を利用者から徴収することができる」と定め、算出方法は別に定めるとする。知的財産権の実施許諾及び譲渡に関する規程第2条第2項は有償・無償いずれの実施許諾も可。旧制度にあった契約一時金・管理費用の減免や施設利用にかかる費用の減免は、ベンチャー支援規程の廃止で根拠を失っており、現行の減免制度は公開情報で確認できなかった。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/shisetsuriyoukashitsuke.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'attr_certified_count', 'established', 'AISolスタートアップ8社を一覧公開（うちIPO1社）', 'AISolのスタートアップ支援ページが支援中7社（Veneno Technologies、iFactory、Stockmark、TriOrb、OptQC、N.B.Medical、プロテオブリッジ）とIPO済み1社（ZenmuTech）を、所在地・認定年月・分野付きで掲載。旧・産総研技術移転ベンチャーは2022年8月時点で称号付与累計153社と産総研資料が記載していたが、産総研側の実績ページと一覧ページは現在いずれも404。', 'official', 'https://www.aist-solutions.co.jp/aisol_startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_cert_rule', 'unknown', null, '「大学発ベンチャー」公式ページ、起業・事業化推進室RIMIXの起業支援ページ、立命館スタートアップマップ、グラスルーツ・イノベーションセンター(GIC)公式サイトを開いて確認したが、大学発ベンチャーの認定制度・称号付与制度およびその根拠規程の記載は見当たらない。支援は認定を前提としないプログラム型で構成されている。', 'unknown', 'https://www.ritsumei.ac.jp/research/activities/activity/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'attr_eligible_scope', 'established', '支援対象は学園の学生・生徒・児童・教職員・卒業生', 'RIMIXの起業支援ページに、支援対象として立命館学園の学生・生徒・児童・研究者に加え卒業生・教職員が明記されている。立命館ソーシャルインパクトファンドの投資対象も「社会課題をビジネスで解決しようとし起業している(もしくは起業予定の)立命館学園の教職員、学生、卒業生」とされる。認定制度に基づく「認定対象」の定義は確認できず、あくまで支援対象の範囲。', 'official', 'https://r-rimix.com/startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'attr_recognition_decider', 'unknown', null, '認定制度自体が確認できないため、認定の決裁者・審査主体を定めた文書も不見当。なお教職員が研究成果を活用した企業の役員等に就任する場合の承認主体は、学校法人立命館教職員兼業規程第4条第3項により立命館大学利益相反委員会と定められている(起業そのものの認定手続とは別の枠組み)。', 'unknown', 'https://www.ritsumei.ac.jp/research/common/file/execution/kengyoukitei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_cert_pre_registration', 'unknown', null, '認定制度が確認できないため、設立登記前の申請・認定予定通知・条件付認定の取扱いを定めた文書も見当たらない。RIMIXの起業支援ページおよびGIC公式サイトのいずれにも、登記前の申請受付に関する記載はない。', 'unknown', 'https://r-rimix.com/startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'attr_validity_years', 'unknown', null, '認定制度が確認できず、有効期間・更新の定めも不見当。参考として兼業承認の期間は学校法人立命館教職員兼業規程第7条で「申請年度内」(年度を超えることが明らかな場合は超えられる)と定められ、同条第2項で承認の更新を妨げないとされている。', 'unknown', 'https://www.ritsumei.ac.jp/research/common/file/execution/kengyoukitei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_head_office_registration', 'established', 'GICのStartup Loungeで会社登記が可能', 'びわこ・くさつキャンパスのグラスルーツ・イノベーションセンター(GIC)公式サイトの施設紹介で、Startup Loungeを「登記可能なラウンジです」と明記している。同施設はシード期からアーリー期向けのインキュベーション施設GIC Labと併設。利用できる対象者の範囲、利用料の有償無償、審査手続の詳細は同サイトに記載がなく未確認。', 'official', 'https://gic.ritsumei.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_facility_lease', 'unknown', null, '［自動検証で否認: BKCインキュベータの記載がurlに無い、別urlの情報を混入］元の主張(established): GIC Labと立命館大学BKCインキュベータ(有償)。GIC公式サイトは「シード期～アーリー期のスタートアップ向けのインキュベーション施設」としてGIC Labを掲げる。加えて同キャンパス内に中小企業基盤整備機構が運営する立命館大学BKCインキュベータがあり、入居案内に賃料と敷金の定めおよび滋賀県・草津市・大津市の賃料補助制度が示され有償。入居期間の上限は公開ページに記載がない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_shared_equipment', 'established', 'GICに共用ラボとファブラボ、料金区分は非公開', 'GIC公式サイトに、分析・評価・試作装置を設置する共用のCommunal Labと、「あらゆる人が気軽に試作できる開かれた大規模ファブラボ」GIC Fabが掲げられている。内閣府提出の構想調書でも試作品製作から先端的技術の分析・評価まで可能な共用オープンラボ・ウェットラボの整備を記す。ベンチャー向けの利用区分や料金表は公開ページに見当たらない。', 'official', 'https://gic.ritsumei.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_name_logo_use', 'unknown', null, '大学名・校章・ロゴの使用条件を定めた規程や、称号の使用可否に関する記載は、確認した公式ページ(大学発ベンチャー、RIMIX起業支援、RIMIXプログラム一覧、GIC)に見当たらない。認定制度自体が不見当のため、称号使用の枠組みも確認できない。', 'unknown', 'https://www.ritsumei.ac.jp/research/activities/activity/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_ip_license', 'unknown', null, '立命館大学発明規程(1992年3月27日 規程第253号)の全条を本文で確認したが、条名は特許を受ける権利の帰属、発明の届け出、発明委員会、発明の審査、譲渡書の提出、譲渡の制限、特許等の出願、補償金、共同発明等で構成され、大学発ベンチャーへの実施許諾の優遇(独占許諾・対価減免・株式対価)を定めた条文はない。立命館大学知的財産ポリシーのPDFは画像のみでテキストが抽出できず、ライセンス方針は未確認。', 'unknown', 'https://www.ritsumei.ac.jp/file.jsp?id=407726&f=.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_equity_rule', 'established', '立命館ソーシャルインパクトファンドが株式等を取得', 'RIMIXのFUNDページに、学校法人立命館の100％出資による「立命館ソーシャルインパクトファンド投資事業有限責任組合」(2020年4月設置、運用期間10年、運営はプラスソーシャルインベストメント株式会社)が示され、投資方法として株式・新株予約権・社債等の取得が想定されている。内閣府提出の構想調書には外部投資家を入れた2号ファンド組成の検討も記載。大学が直接出資・新株予約権を取得する規程は不見当で、100％出資ファンド経由の枠組み。', 'official', 'https://r-rimix.com/fund/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_gap_fund', 'established', '京阪神連携のJST-GAPプログラムに採択', '学校法人立命館が内閣府へ提出した令和5年度地域中核大学イノベーション創出環境強化事業 構想調書に、大阪・京都・ひょうご神戸コンソーシアム参画のもと「JST・START 大学・エコシステム推進型・スタートアップ・エコシステム形成支援のGAPプログラムに採択された」と記載。同調書はGIC内の社会実装支援システムとして入居料・人件費・知財取得経費等の資金支援も掲げる。学内独自のGAPファンド規程は不見当。', 'official', 'https://www8.cao.go.jp/cstp/daigaku/chosyo/chiiki_r5_ritsumeikan.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_accelerator', 'established', '起業・事業化推進室RIMIXが相談窓口と育成を常設', 'RIMIXの起業支援ページに、会社設立からバックオフィス体制までの相談窓口、メンタリングを担うRIMIXサポーターズクラブ、立命館スタートアップマップが掲げられている。プログラム一覧には学生ベンチャーコンテスト、EDGE+R、OIC CONNÉCT、GRIP、APU起業部が並ぶ。BKCインキュベータではインキュベーションマネージャーが事業計画書に基づき伴走支援を行うと案内されている。', 'official', 'https://r-rimix.com/programs/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_coi_sidejob', 'established', '役員兼業は利益相反委員会が承認、週8時間が上限', '学校法人立命館教職員兼業規程(2020年9月9日 規程第1192号)第4条第3項で、営利企業の取締役・監査役・顧問就任、研究成果または専門的知見を活用した企業の役員・技術アドバイザー等の就任は立命館大学利益相反委員会の承認による。第5条第6号は当該就任を研究成果を事業化するものに限り、第6条で一週あたり8時間を上限とする。立命館大学利益相反規程(2004年3月24日 規程第593号)第3条が同委員会を常任理事会のもとに設置し、第12条で株式配当を含む一定額以上の金銭的利益の年1回の開示を義務づける。', 'official', 'https://www.ritsumei.ac.jp/research/common/file/execution/kengyoukitei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'attr_support_fee', 'established', '施設利用は賃料有償、育成プログラムは参加費無料', '中小企業基盤整備機構が運営する立命館大学BKCインキュベータの入居案内は賃料と敷金の定めを置き、滋賀県・草津市・大津市による賃料補助制度も案内しており有償。一方、RIMIXのプログラム一覧ではOIC CONNÉCTの参加費を無料と明示している。学内支援全体の有償無償を一括で定めた要項や、GIC各施設の料金区分は公開ページに見当たらない。', 'official', 'https://www.smrj.go.jp/incubation/rits-bkci/room/info/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'attr_certified_count', 'unknown', null, '認定制度が確認できず、機関自身が公開する認定ベンチャー一覧も見当たらない。立命館スタートアップマップは起業プロセスを可視化する情報ページで、掲載社数も掲載・認定の基準も記載がない。大学発ベンチャー数として流通する数値は経済産業省調査に基づくもので機関自身の認定実績ではないため採らない。', 'unknown', 'https://r-rimix.com/startup/startupmap/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_cert_rule', 'established', '「筑波大学発ベンチャー」称号を授与する認定制度', '国立大学法人筑波大学における大学発ベンチャーの支援に関する規程（令和3年6月24日法人規程第35号）第3条第1項「法人は、第6条第1項の規定により支援を決定した大学発ベンチャーに対し、『筑波大学発ベンチャー』の称号を授与する」。実施細則は大学発ベンチャーの支援に関する要項（令和3年6月24日国際産学連携本部長決定、令和5年12月26日改正）。要項第8項で称号記を授与し本部ウェブサイトで企業名等を公表と規定。PDF全文を取得して確認。', 'official', 'https://www.tsukuba.ac.jp/about/disclosure-ho-kisoku/s-05/pdf/2021hkt35.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'attr_eligible_scope', 'established', '研究成果・共同研究・技術移転・出資・学生・職員等・関連の7区分', '支援規程第2条および要項第2項が有限責任形態の企業を7区分で定義。(1)研究成果ベンチャー（本学の研究成果に基づく特許・技術・ノウハウの事業化目的で新設）(2)共同研究ベンチャー（設立後5年以内に本学と共同研究等）(3)技術移転ベンチャー（設立後5年以内に法人から技術移転等）(4)出資ベンチャー（法人から出資）(5)学生ベンチャー(6)職員等ベンチャー（職員・元職員・卒業生・修了生の起業）(7)関連ベンチャー（本部長が深い関連を認めたもの）。退職・卒業後の経過年数の上限は規定なし。', 'official', 'https://www.tsukuba.ac.jp/about/disclosure-ho-kisoku/s-05/pdf/2021hkt35.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'attr_recognition_decider', 'established', '国際産学連携本部長が単独で決定（合議体なし）', '支援規程第6条第1項「本部長は、前条の申請があったときは、第4条に規定する要件を踏まえ、支援の可否を決定する」、同条第2項で文書により通知。第2条も「国際産学連携本部の本部長が認めたもの」と規定。規程・要項の全文を通読したが、認定委員会その他の合議体に関する条文は存在しない。事務は第9条により産学連携部産学連携企画課が担当。認定ロゴ使用・法人施設登記の申請先も本部長。', 'official', 'https://www.tsukuba.ac.jp/about/disclosure-ho-kisoku/s-05/pdf/2021hkt35.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_cert_pre_registration', 'established', '起業予定段階で申請可、定款案・事業計画案で受付', '別記様式第1号（筑波大学発ベンチャー称号授与申請書）の添付書類欄が【起業済みの場合】と【起業予定の場合】に分かれ、後者は定款（案）・収支計画書（案）・事業計画書（案）を添付し「起業後に、定款（写）と履歴事項全部証明書（写）を提出すること」と明記。別記様式第2号（法人施設登記申請書）も申請できる主体を「企業又は者」とし、要項第6項(2)で称号授与を申請中の者（同時申請を含む）を対象に含める。条件付認定という文言はなく、設立後の書類提出を条件とする運用。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.sanrenhonbu.tsukuba.ac.jp/wp/wp-content/uploads/2024/01/venture-form-1-shougou.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'attr_validity_years', 'established', '有効期間の定めなし、取消事由該当時に取消し', '支援規程および要項の全文を通読したが、認定の有効期間・更新・再認定に関する条文は存在しない。代わりに第8条（支援の決定の取消し）が、要件不充足、社会的信用の失墜行為、企業活動の実態消滅、本部長が継続不適当と認めた場合に取消しができると定め、第2項で企業側からの解除申出があれば取り消すとする。第7条で申請事項の変更、解散・破産・再生・更生手続開始等の報告義務、求めに応じた事業報告書・収支決算書の提出義務を課す。', 'official', 'https://www.tsukuba.ac.jp/about/disclosure-ho-kisoku/s-05/pdf/2021hkt35.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_head_office_registration', 'established', '可。貸与・使用許可された学内研究室の住所で登記可', '要項第3項(2)が支援内容として「前号により貸与した研究室等（スペースチャージを支払って使用している研究室等）又は使用を許可した研究室等（個人研究室、実験室等）の住所を大学発ベンチャーの登記の住所とすることを認めること」と規定。別記様式第2号「大学発ベンチャーの法人施設登記申請書」で申請し、登記先は①産学リエゾン共同研究棟（ILC棟）②共同研究棟A③その他から選択。①②は本部公募事業の採択が前提、③は施設の管理責任者の了解を示す資料が必要。承認後に施設の財産貸付契約書（写）を提出。', 'official', 'https://www.sanrenhonbu.tsukuba.ac.jp/wp/wp-content/uploads/2024/01/venture-youkou.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_facility_lease', 'established', '事業化促進プロジェクトでILC棟等を貸与、起業後は有償', '要項第3項(1)が「本部が実施する公募事業における研究費の支援及び研究室等の研究場所の貸与」を支援内容とする。事業化促進プロジェクト募集要項（2026年6月）によれば、産学リエゾン共同研究棟（ILC棟、39〜56平方メートル計3室）と共同研究棟A（19〜60平方メートル計3室）を貸与。産学共同研究コースとベンチャー創業準備コースは施設使用料・光熱水料を免除、起業済ベンチャー成長コースは施設マネジメント課と賃貸契約を締結し有償。貸与期間は1〜3年、継続申請可で通算最大6年。3コース合計で年3〜5件程度。', 'official', 'https://www.sanrenhonbu.tsukuba.ac.jp/wp/wp-content/uploads/2026/06/proproject1705.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_shared_equipment', 'established', 'オープンファシリティー登録により機器を有償利用可', '別記様式第2号の第5項が、承認後に提出すべき書類として「【登記を希望する法人の施設の設備を使用して事業活動を行う場合】設備についてのオープンファシリティー登録を証明する資料（オープンファシリティー推進室の承認後に提出）」を求める。オープンファシリティー推進機構規程（令和4年法人規程第39号）第2条が研究設備の学内外への共用を目的と定め、第5条第1項(2)で利用料金の体系を推進委員会の審議事項とする。学外利用者は年度ごとに利用者登録と機器利用申請を行い、機器ごとに設定された利用単価・委託単価に基づく利用負担金を請求書払いする。', 'official', 'https://www.sanrenhonbu.tsukuba.ac.jp/wp/wp-content/uploads/2024/01/venture-form-2-touki.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_name_logo_use', 'established', '称号の名乗り可、認定ロゴは申請制で用途限定', '支援規程第3条第4項が「大学発ベンチャーが『筑波大学発ベンチャー』と称したこと」による損害への免責を定め、称号の使用を前提とする。要項第3項(5)が「『筑波大学発ベンチャー』認定ロゴを使用する権利の付与」を支援内容とし、第7項で申請できるのは称号を授与された企業に限り申請した用途のみ使用可と規定。別記様式第3号で申請。認定ロゴの用途は企業紹介のウェブサイト、パンフレット、名刺、封筒などコーポレートブランディング目的に限られ、製品・商品・サービスおよびその広報・広告宣伝・販売促進の目的には使用できない。', 'official', 'https://www.sanrenhonbu.tsukuba.ac.jp/spin_offs/v-logo/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_ip_license', 'established', '対価の株式等払いのみ、独占・減免の明文規定なし', '国立大学法人筑波大学が大学発ベンチャーからライセンス等、研究経費等又は財産貸付の対価として取得する株式等の取扱いに関する規程（平成30年1月25日法人規程第8号）第3条が、大学発ベンチャーが対価の全部又は一部を現金で支払うことが困難な場合に限り株式等で取得できると規定。ライセンス等は知的財産権の譲渡・提供・実施権の設定・実施許諾・利用許諾を指す（第2条(2)）。一方、知的財産規則の本文を検索したが、大学発ベンチャーへの独占的実施許諾や実施料の減免を定めた条項は見当たらない。', 'official', 'https://www.tsukuba.ac.jp/images/pdf/2018hkt08.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_equity_rule', 'established', '対価としての株式・新株予約権取得の規程あり', '上記の平成30年法人規程第8号が「株式等」を株式及び新株予約権と定義（第2条(5)）し、ライセンス等・学術指導に要する経費・財産貸付の対価として取得する場合の手続を定める。第4条で学長が国際産学連携本部に審査を付託し、本部が財務状況その他の妥当性を審査して本部長が学長へ報告、第5条で学長が取得の可否を決定し契約書を取り交わす。第6条でライセンス対価として取得した株式等を売却して収入を得た場合の発明者補償金は知的財産規則第6条を準用。現金出資（キャッシュ）を行う根拠規程は公開情報では確認できなかった。', 'official', 'https://www.tsukuba.ac.jp/images/pdf/2018hkt08.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_gap_fund', 'established', 'つばさplusで1チーム300〜800万円、年6件程度', '筑波大学ベンチャー起業支援事業「つばさplus」は年間6チーム程度を採択し、1チームあたり300〜800万円の資金を支援。試作品の製作、実証実験、特許調査などに使用でき、メンター2名と知財メンター1名によるハンズオン・メンタリング、ワークショップ、Demo Dayでの事業化促進機関とのマッチングを伴う。2020年9月にJSTの社会還元加速プログラム（SCORE）大学推進型に採択されて開始、2022年4月に大学発新産業創出プログラム（START）大学・エコシステム推進型へ移行、2025年3月の委託事業終了後、2025年4月から学内事業「つばさplus」として継続。', 'official', 'https://tsubasa.sanrenhonbu.tsukuba.ac.jp/outline/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_accelerator', 'established', 'ベンチャー起業相談室とつばさplusのメンタリング', '要項第3項(3)が「経営、財務、人材、販路、知財等の相談に係る対応」、(4)が講習会・起業家向け教育講座等の案内を支援内容として規定。実施主体はベンチャー起業相談室（産学連携部産学連携企画課内）で、教職員・学生を対象にビジネスプラン構築等をワンストップで受け付け、国際産学連携本部の准教授・産官学共創プロデューサー・企画担当が対応する。事業化促進プロジェクト募集要項は本学提供の起業支援プログラムとして起業力BU講座、BizDev講座、つばさ事業、研究シーズ社会還元WS、経営チーム支援（EIR）、経営スキルアップ講座、GAPファンド獲得支援講座、Research Studioの8つを列挙。', 'official', 'https://www.sanrenhonbu.tsukuba.ac.jp/spin_offs-venture_consultation/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_coi_sidejob', 'established', '学長承認制、兼業審査委員会が審議、承認通知が申請要件', '国立大学法人筑波大学職員兼業規程（平成19年法人規程第21号）は学長の承認制で、第8条により兼業審査委員会が(1)研究成果活用企業の役員（会計参与・監査役を除く）・顧問・評議員（発起人を含む）への従事、(2)技術移転事業者の役員等への従事、(3)株式会社等の社外取締役・監査役への従事を審議する。委員長は人事担当副学長。第9条で研究成果活用企業等兼業休業を規定。支援規程第4条(4)は職員が起業した場合に兼業規程等の所要の手続・承認が適正になされていることを支援要件とし、別記様式第1号・第2号は「研究成果活用兼業承認通知（写）」の添付を求める。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.tsukuba.ac.jp/images/pdf/2007hkt21.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'attr_support_fee', 'established', '有償。支援内容に応じた対価を要求可', '支援規程第3条第3項「法人は、当該大学発ベンチャーに対し、前項の支援の内容に応じた対価を要求することができるものとする」。実際の運用では、要項第3項(2)の登記に用いる研究室はスペースチャージの支払いまたは財産貸付契約を前提とし、事業化促進プロジェクトの起業済ベンチャー成長コースは財産管理規則および財産貸付料の算定に関する細則に基づく施設使用料・光熱水料を支払う。共用機器はオープンファシリティーの利用負担金。一方、称号の授与、認定ロゴの使用権付与、相談対応、講習会の案内については対価に関する記載がない。', 'official', 'https://www.tsukuba.ac.jp/about/disclosure-ho-kisoku/s-05/pdf/2021hkt35.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'attr_certified_count', 'established', '設立累計304社（2026年9月1日現在）を年度別に公開', '国際産学連携本部の「筑波大学発ベンチャーリスト」に「設立累計数：304社（2026年9月1日現在）」と明記され、平成9年度から令和8年度までの設立年度別に企業名を掲載している。要項第8項が「本部長は、支援を決定したときは、通知のほか、『筑波大学発ベンチャー』の称号記を授与するとともに、本部のウェブサイトにおいて当該大学発ベンチャーの企業名等を公表する」と定めており、公表は制度上の義務。数値は機関自身の公開ページから取得。', 'official', 'https://www.sanrenhonbu.tsukuba.ac.jp/spin_offs/year/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_cert_rule', 'established', '「茨城大学発ベンチャー」称号の授与内規', '「国立大学法人茨城大学の研究成果等を活用したベンチャー企業への称号の授与に関する内規」(平成18年4月20日制定、令和4年3月28日改正・令和4年4月1日施行)。第1条で研究成果又は人的資源等を活用して起業されたベンチャー企業への称号授与を定め、第2条で称号を「茨城大学発ベンチャー」とする。第6条第1項で称号記(様式2)を授与。同条第3項は「大学は、前2項の称号を授与したことにより、法的責任を負うものではない」と明記し、称号は支援義務を伴わない。研究・産学官連携機構の「大学発ベンチャー」ページも根拠規則として本内規と株式等取扱規程の2件のみを掲示。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000162.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'attr_eligible_scope', 'established', '教職員・学生の知財／研究成果活用型、学生は離籍1年以内可', '内規第3条。対象は「新たな技術又はビジネス手法を基に起業した法人」のうち、(1)大学職員又は学生が所有する特許権等の知的所有権を活用した場合、(2)大学で達成された研究成果又は習得した技術等を活用した場合、(3)大学の学生(学生の身分を失ったときから起業まで他の職に就かなかった者、及び身分を失ったときから1年以内に起業した者を含む)が設立(設立者の一人である場合を含む)又は設立に深く関与した場合、(4)その他学長が認めた場合。教職員の退職後年数や卒業生一般を対象とする規定は置かれていない。第7条で大学職員が資格該当者を学長へ申し出る情報提供の仕組みを持つ。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000162.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'attr_recognition_decider', 'established', '学長（研究・産学官連携推進委員会の審議）', '内規第4条で「茨城大学発ベンチャー称号申請書」(様式1)により学長へ申請し、第5条で学長が茨城大学研究・産学官連携推進委員会の審議を経て可否を決定・通知する。第8条の取消しも同委員会の審議を経て学長が行う。同委員会は全学委員会の一つで、「茨城大学研究・産学官連携推進委員会細則」(平成29年12月19日細則第33号、令和8年6月25日改正・令和8年7月1日施行)第6条で委員長は学術を担当する理事、第4条で各学野の研究担当副学野長、研究・産学官連携機構長・副機構長等で構成、第11条で庶務は研究推進部が処理する。ベンチャー認定専用の委員会は置かれていない。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110001126.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_cert_pre_registration', 'established', '住所使用許可は設立前申請可、称号は起業後のみ', '称号内規第3条は対象を「起業した法人」に限定し、設立登記前の申請・認定予定通知・条件付認定の規定を置かない。一方「国立大学法人茨城大学の住所を他の法人が法人登記上の住所として使用する場合の手続に関する要項」(令和5年2月16日要項第1号)は第1条で対象に「当該法人を設立予定の個人又は団体を含む」と明記し、第4条第1項で原則として登記申請予定日の1か月前までの申請を求め、同条第2項ただし書で「法人設立前で、かつ、学長が認める場合は、一部を省略又は案とすることができる」とする。設立前の入口は本店登記の住所使用許可側にある。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110001355.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'attr_validity_years', 'established', '5年間・更新規定なし、再申請可', '内規第6条第2項「称号の有効期間は、授与した日から5年間とする。ただし、再申請を妨げない。」更新手続を定めた条文はなく、期間満了後は改めて第4条の申請と第5条の推進委員会審議を経る運用になる。第8条で、社会的信用を失墜する行為その他称号を保持するのに適当でない場合は、推進委員会の審議を経て学長が授与を取り消し、称号記を返付させる。株式等取扱規程第2条第4号も対象を「称号が有効期間中である企業」に限定しており、有効期間が他の支援の前提条件になっている。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000162.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_head_office_registration', 'established', '水戸・日立・阿見3キャンパスで登記可、施設使用が前提', '「国立大学法人茨城大学の住所を他の法人が法人登記上の住所として使用する場合の手続に関する要項」(令和5年2月16日要項第1号)。第6条で水戸キャンパス(水戸市文京2-1-1)、日立キャンパス(日立市中成沢町4-12-1)、阿見キャンパス(稲敷郡阿見町中央3-21-1)を登記可能住所に指定。第3条の申請資格は、教職員又は学生(身分喪失後1年以内を含む)が設立又は経営等に深く関与し、かつ固定資産使用許可その他契約等により本学施設を現に使用又は使用予定であること、加えて知的所有権活用又は研究成果・技術活用に該当すること。第5条で学長が全学財務・施設委員会の審議を経て許可、第7条で毎年度の事業内容・収支決算の報告義務。住所使用自体の使用料規定はなく、前提となる固定資産使用許可が有償。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110001355.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_facility_lease', 'established', '固定資産使用許可で創業準備段階も可、有償・最長5年', '「国立大学法人茨城大学固定資産使用許可取扱要項」(平成16年7月7日要項第11号、平成30年3月28日改正)第3条第8号ウが、使用許可できる範囲として「本学の研究成果を活用した事業(当該事業に係る創業の準備を含む。)を行う中小企業又は個人」を明記。第6条第2項でこの類型の許可は使用許可日から起算して5年が限度(1事業年度ごとに更新)。第5条で長期使用は2か月前までに申請。別に農学部フードイノベーション棟インキュベーション施設(平成31年内規第7号)が外部機関の入居を受け付け(登記簿謄本・定款・直近3期の申告書と決算書の提出、第6条の6項目の審査基準あり)、日立キャンパスにはDeeptech系スタートアップ向けSAKURA BLOOM PARKが2027年2月竣工予定。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000133.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_shared_equipment', 'established', '研究設備共用センターを学外者料金で利用可', '「茨城大学研究設備共用センター規程」(平成27年3月31日規程第127号、令和8年6月25日改正)第2条・第3条が全学の研究設備・機器の共用とコアファシリティ化を推進。同センターの「2025(令和7)年4月1日以降機器利用料金表(学外者用)」は水戸・日立の分析機器(蛍光X線、単結晶・粉末X線回折、NMR、電子顕微鏡、質量分析計等)について基本料金 年20,000円、利用料金 10,000円/時間(いずれも税込)を定め、依頼測定料金表も併載。注1)の学外者受入対象は「大学が認めた教育研究事業に携わる者、レンタルラボ利用者、機器の相互利用を実施している機関の者、教員と共同で教育研究活動に携わる者、教員が責任を持って推薦できる者」。認定ベンチャー専用の区分や減免はない。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.ofc.ibaraki.ac.jp/wp-content/uploads/2025/03/%E5%AD%A6%E5%A4%96%E6%96%99%E9%87%91%E8%A1%A82025.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_name_logo_use', 'established', '称号記の授与のみ、ロゴ・校章の使用規程なし', '内規第2条で「茨城大学発ベンチャー」の称号を授与し、第6条第1項で称号記(様式2)を交付するため、称号の名乗り自体は制度として認められる。第8条で不適当な場合は取消し・称号記の返付。一方、ロゴ・校章・シンボルマーク・商標の使用条件を定めた規則は規程集(2026年7月1日内容現在、全752件)に存在しない。名義使用は「国立大学法人茨城大学名義使用に関する取扱要項」(平成28年7月4日要項第119号)が共催・協賛・後援の事業名義に限定し、第6条第3号で「政治活動、宗教活動又は営利を目的として行われるものではないこと」を許可要件とするため、ベンチャーの営利事業には適用されない。［検証エージェントは出典を開けず未照合］', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110001009.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_ip_license', 'established', '発明者設立ベンチャーへ優先的に実施許諾・譲渡', '「国立大学法人茨城大学知的財産ポリシー」(平成17年3月17日学長裁定、令和2年3月6日改正)第6の2「大学発ベンチャー企業の支援」に「本学帰属の発明等を創出した教職員等がベンチャー企業を設立する場合、本学は当該企業に対し、優先的に知的財産の実施許諾又は譲渡を行うものとする」と明記。独占的実施許諾や実施料の減免を定めた条項はない。株式等取扱規程第2条第6号は「知的財産権の譲渡・実施許諾・使用許諾」を株式等取得の対価対象事業に含めており、株式・新株予約権を対価とするライセンスは制度上可能。第6の5で知的財産の管理・活用は研究・産学官連携機構が一元的に行う。［検証エージェントは出典を開けず未照合］', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000588.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_equity_rule', 'established', '株式・新株予約権を対価取得可、学長承認', '「国立大学法人茨城大学におけるベンチャー企業を対象とした収益を伴う事業の対価として取得する株式等の取扱いに関する規程」(令和5年2月22日規程第5号、令和8年6月25日改正・令和8年7月1日施行)。第2条第3号で「株式等」を株式及び新株予約権と定義、同条第4号で対象を称号の有効期間中の茨城大学発ベンチャー企業に限定。同条第6号の「収益を伴う事業」は知的財産権の譲渡・実施許諾・使用許諾、学術指導の提供、研究成果有体物の提供、固定資産使用許可、学長が必要と認める事業。第4条でベンチャー側代表者が申請し推進委員会が審査、第6条で学長が承認・不承認を決定、第8条で株式等管理規程に基づき管理責任者が管理する。［検証エージェントは出典を開けず未照合］', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110001356.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_gap_fund', 'established', '学生向け村上基金の無利子貸与（150万円以内）', '「茨城大学学生起業支援基金(村上基金)貸与要項」(平成28年3月9日要項第50号、令和8年6月25日改正・令和8年7月1日施行)。第1条で村上幸一氏及びダイドードリンコ株式会社からの寄附金を原資に基金を設置、第2条で学生のベンチャー起業に係る経済的負担の支援を目的とする。第3条で対象を本学の学生(大学院を含む)に限定し、十分な事業計画を有すること等を要件とする。第4条で貸与額は1件150万円以内、貸与の実施は3年以内(一括・分割)、第13条で無利子、第7条で選考委員会の審査を経て学長が決定、第9条で毎年1回の業務状況報告。教職員向けのGAPファンド・POC資金・起業準備資金の規程は規程集に存在しない。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000283.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_accelerator', 'not_started', '制度なし、技術相談窓口と学生アントレ教育のみ', '研究・産学官連携機構の「企業・地域の方へ」の支援メニューは、技術相談・共同研究・受託研究・受託研究員制度・学術指導・寄附金・秘密保持契約・研究者情報総覧・公開特許・教員への兼業依頼・研究設備機器の利用と依頼分析・大学発ベンチャーの限定列挙で、アクセラレーションプログラム、メンタリング、起業相談窓口の項目はない。「大学発ベンチャー」ページも称号の説明と根拠2規程へのリンクのみで、申請手続や支援メニューの記載がない。規程集(2026年7月1日内容現在)にも伴走支援の規則はない。大学ニュース(2025年9月12日)は学生向けアントレプレナーシップ教育プログラムとGTIE連携のアイデアソン開催を伝えるが、認定ベンチャー向けに制度化された伴走支援ではない。', 'official', 'https://www.iric.ibaraki.ac.jp/for-companies/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_coi_sidejob', 'established', '研究成果活用企業役員等兼業審査会の審査で兼業可', '「国立大学法人茨城大学兼業実施基準」(平成16年4月1日制定、令和7年5月22日改正)第2条で「研究成果活用企業」を定義し、第4条で兼業規程第4条に基づく研究成果活用企業役員等兼業審査会に諮り、(1)兼業する教職員が当該企業の事業で活用される研究成果を自ら創出していること、(2)役員等の職務内容が研究成果活用事業に関係すること、(3)大学での職と当該企業の間に物品購入等の契約関係その他の特別な利害関係又はその発生のおそれがないこと、(4)申請前2年以内に利害関係のある職を占めた期間がないこと、を確認した場合に役員等兼業を認める。技術移転事業者役員等・監査役の類型も別条で規定。「国立大学法人茨城大学利益相反マネジメント規程」(平成22年6月23日制定、令和8年6月25日改正)第2条は未公開株式その他の対価を狭義の利益相反、兼業による職務遂行責任の衝突を責務相反と定義し接続する。［検証エージェントは出典を開けず未照合］', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'attr_support_fee', 'established', '有償が原則、認定ベンチャー向けの減免規定なし', '固定資産使用許可取扱要項第7条で固定資産等使用料と光熱水使用料を「固定資産使用許可使用料算定基準」により算定して徴収し、第9条の無償使用の列挙(国・地方公共団体、同窓会、災害応急、技術移転機関、PFI事業、共催協賛の名義使用等)に第3条第8号ウの研究成果活用事業は含まれない。研究設備共用センターの学外者料金は基本料金 年20,000円と利用料金 10,000円/時間。「茨城大学学術指導取扱規程」(令和3年1月28日規程第7号、令和8年3月26日改正)第7条は指導料・施設利用料・謝金・人件費等の直接経費に間接経費20%標準を加えた学術指導料を相談者負担とする。研究・産学官連携機構の施設等利用要項第12条も経費を利用者負担とし、機構長が特に必要と認めた場合のみ減免。［検証エージェントは出典を開けず未照合］', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110001246.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'attr_certified_count', 'established', '10社（廃業含む）、社名一覧の公開なし', '大学公式ニュース「躍進する茨大発ベンチャーとスタートアップ 新たな拠点をつくり、事業創出を加速」(2025年9月12日)に「計10社(既に廃業している企業も含む)」と記載。個別紹介として株式会社Dinow(2020年創業)、株式会社エンドファイト(2023年創業)が挙がる。研究・産学官連携機構の「大学発ベンチャー」ページには社名一覧の掲載がなく、称号制度の説明と根拠2規程へのリンクのみ。認定企業の一覧を公開する専用ページは確認できなかった。', 'official', 'https://www.ibaraki.ac.jp/news/n/2025/09/12014325.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_cert_rule', 'established', '「長崎大学発ベンチャー」称号授与制度（令和4年度運用開始）', '根拠は「長崎大学における長崎大学発ベンチャーの称号授与に関する規程」（令和4年3月28日規程第34号、令和8年3月31日規程第33号改正・令和8年4月1日施行）。第1条が「長崎大学発ベンチャーの称号」を規定。研究開発推進機構の公式ページも令和4年4月1日からの運用開始と記載。呼称は「認定」ではなく「称号授与」。申請様式は別記様式第1号「長崎大学発ベンチャー称号授与申請書」。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'attr_eligible_scope', 'established', '知財・研究成果・習得技術の活用で設立した企業、元教職員・元学生も可', '規程第2条が4号を列挙。第1号＝本学・教職員・学生が所有する知的財産権を活用して設立、第2号＝本学で達成された研究成果を活用、第3号＝教職員・学生等（在職又は在学していたものを含む）が本学で習得した技術・知識等を活用、第4号＝学長が特に必要と認めた企業。退職・卒業後の年数制限は規定なし。申請様式の代表者区分は教職員／学生／在職または在学していたもの／第三者、種別は研究成果・共同研究・技術移転・学生・関連ベンチャーの5区分。教職員起業は兼業規程等の手続完了が要件（第2条ただし書）。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'attr_recognition_decider', 'established', '学長決定（研究開発推進機構運営委員会の議を経る）', '規程第3条第2項「学長は…長崎大学研究開発推進機構運営委員会の議を経て、称号の授与の決定を行う」。運営委員会は長崎大学研究開発推進機構規則（平成30年6月26日規則第31号）第4章（第15条―第20条）に組織・運営が定められ、事務は同規則第28条により研究推進部研究推進課が処理する。称号授与専用の認定委員会は置かれていない。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_cert_pre_registration', 'not_started', '登記前申請は不可、登記簿謄本の添付が必須', '申請様式（別記様式第1号）の添付資料が「登記簿謄本(3か月以内のもの)」「定款の写し」を必須列挙し、記入欄も「設立日」「事業開始日（開業届出日）」を求める。規程第2条は各号すべて「設立した企業」と規定。設立登記前の申請、認定予定通知、条件付認定の定めは規程本文にも申請様式にも存在しない。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.ciugc.nagasaki-u.ac.jp/wp-content/uploads/2024/03/venture-shinseisyo.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'attr_validity_years', 'established', '3年間、更新可', '規程第4条「称号の有効期間は、称号授与の日から3年間とする」「更新することができる」。申請様式にも「□新規 □更新」の区分があり、更新申請ではこれまでの活動状況の説明を求める。第8条第1項は資格要件の喪失、解散・破産・再生手続、社会的信用失墜行為等を取消事由として規定。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_head_office_registration', 'unknown', null, '称号授与規程、研究開発推進機構研究室等利用規程、不動産貸付要領のいずれにも、大学の住所を会社の本店所在地として商業登記に用いることを認める（または禁じる）定めが見当たらない。不動産貸付要領第12条は転貸・担保提供を禁じるのみ。起業環境の整備を扱うFFGアントレプレナーシップセンターのKIEPS施設ページはサイト全体がHTTP 401で閲覧できず、入居要項を確認できなかった。', 'unknown', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000189.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_facility_lease', 'established', '機構の研究室・実験室を有償利用、ベンチャー専用枠なし', '長崎大学研究開発推進機構研究室等利用規程（平成23年規程第31号、令和元年5月1日施行）第2条・第3条が研究室・実験室・研修室・機器の利用対象業務と利用者資格（本学職員及び学生、学外機関の共同研究員、機構主催事業の参加者、機構長が特に適当と認めた者）を規定。第6条で利用期間は事業年度内、機構長が認めれば3年を限度に更新可。第12条で利用経費は代表者負担。別途、不動産貸付要領（平成16年学長裁定、令和8年4月1日施行）第6条が貸付期間1年・更新可（地上権設定時30年以内）、第8条で貸付料は別に定めるとし、第9条の無償貸付は職員組合等に限定列挙。大学発ベンチャー専用の入居枠は公開情報で確認できない。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000633.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_shared_equipment', 'established', '共用機器システムで時間単価課金、学外者も登録可', '研究開発推進機構規則第7条が設備共同利用部門を置き、先端分析機器の共同利用・技術指導を業務と規定。長崎大学共用機器管理・予約・課金オンラインシステム（nushare）の「設備の利用について」は「長崎大学所属ですか（所属です／所属ではありません）」の分岐で学外者のアカウント登録経路を案内し、大学連携研究設備ネットワーク経由で予約する。機器詳細ページは利用料金を時間単価で表示し（示差走査熱量測定装置で160円/時）、利用資格は「すべての利用者が利用可能」。大学発ベンチャー専用の料金区分は確認できない。', 'official', 'https://nushare.ura.nagasaki-u.ac.jp/equipment/equipmentdetail.php?eq_no=27', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_name_logo_use', 'established', '称号は使用可、商標・ロゴは別途学長許可で原則有償', '申請様式（別記様式第1号）の注意事項に「長崎大学発ベンチャーの称号授与によって、長崎大学の商標、ロゴ等の使用許諾するものではありません」と明記。ロゴ・大学名称の使用は長崎大学商標取扱規程（令和元年8月2日規程第11号、令和8年4月1日施行）が規律し、第9条が収益目的の商標等使用を学長許可制とし同条第3項で「原則として有償」、第10条が収益目的の大学名称使用に第9条を準用。様式が案内するロゴマークガイドラインのURLは現在404。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000859.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_ip_license', 'unknown', null, '［自動検証で否認: 根拠URLは株式等取扱規程で実施許諾規程でない］元の主張(established): 独占的実施許諾可、対価を株式・新株予約権で受領可。長崎大学知的財産権の実施許諾及び譲渡に関する規程（平成16年規程第74号、平成30年7月1日施行）第2条が非独占・独占・一部独占の実施許諾と有償又は無償の許諾を認め、第3条は独占的許諾に一般への公示と異議申立ての機会を要求。大学発ベンチャー向けの実施料減免を定めた条文はない。一方、大学発ベンチャー企業への支援の対価として取得する株式等取扱規程（令和6年規程第6号）第3条第1号・第4条が、現金非保有や資金繰り逼迫等の条件下でライセンス供与等の対価を株式等で受領できると規定し、これが実質的な優遇にあたる。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_equity_rule', 'established', '株式・新株予約権の取得規程あり（令和6年制定）', '長崎大学における大学発ベンチャー企業への支援の対価として取得する株式等取扱規程（令和6年3月5日規程第6号、同日施行）。第2条第3号で株式等＝株式及び新株予約権、第4号で大学発ベンチャー企業を科学技術・イノベーション創出活性化法第34条の4第1項の成果活用事業者等と定義。第3条でライセンス供与等および収益を伴う事業の対価を株式等で取得可、第5条は株式等取扱委員会の議と役員会の議を経て学長が決定、第6条は新株予約権の速やかな行使、第7条は財務担当理事を管理責任者、第8条は経営参加権の原則不行使、第9条は原則として有価証券処分信託等による売却を規定。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000955.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_gap_fund', 'established', 'JST・PARKSのGAPファンドに参画、学内独自基金は未確認', '大学公式ニュース（2025年3月19日「2024年度 スタートアップ・エコシステム共創プログラム GAPファンドプログラムの採択者を公開しました」）に、JST「大学発新産業創出基金スタートアップ・エコシステム共創プログラム」の採択プログラムPARKS（オール九州スタートアップエコシステムプラットフォーム）のGAPファンドプログラムへ、長崎大学から教職員3名のシーズが採択されたと記載。同記事はGAPファンドやインキュベーションプログラム等を提供すると明記。長崎大学単独のGAPファンド規程は規則集の体系目次に見当たらない。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.nagasaki-u.ac.jp/ja/news/news4587.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_accelerator', 'established', '機構にアントレプレナーシップセンター、ベンチャー支援室設置', '長崎大学研究開発推進機構規則（平成30年規則第31号）第3条が機構にアントレプレナーシップセンターを置き、第8条第1項で同センターにベンチャー支援室及び人材育成室を設置、第2項でアントレプレナーシップ教育、アントレプレナー人材の育成に係る支援、ベンチャー支援を業務と規定。センター長は株式等取扱委員会の委員でもある（株式等取扱委員会規程第3条第1項第5号）。センターの通称はFFGアントレプレナーシップセンター。個別の伴走メニューはセンター独自サイトがHTTP 401で閲覧できず未確認。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000815.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_coi_sidejob', 'established', '役員兼業は学長許可制、利益相反は別委員会で審議', '長崎大学営利企業役員等兼業規程（平成16年規程第37号、令和8年3月31日改正）は技術移転兼業・研究成果活用兼業・監査役兼業を対象とし、第3条で部局長経由の申請と、営利企業役員等兼業審査専門部会（第5条）の審査結果を参考にした学長決定を規定、第4条で定款・組織図・営業報告書等の提出を求める。利益相反は長崎大学利益相反委員会規則（平成16年規則第58号）が担い、研究開発推進機構規則第6条第8号も研究インテグリティ部門の業務に利益相反を挙げる。称号授与申請様式は兼業手続完了の表明と、教職員の場合の兼業許可の写しの添付を要求。教職員の株式保有を直接規律する条文は兼業規程に見当たらない。［検証エージェントは出典を開けず未照合］', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000092.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'attr_support_fee', 'established', '有償が基本、施設・機器・商標使用は料金負担', '称号授与規程第5条は「本学の管理運営及び教育研究に支障のない範囲において、支援を行うことができる」とし「支援に関し必要な事項は、別に定める」と委任するのみで、支援メニューと対価は規程本文にない。個別規程では、研究開発推進機構研究室等利用規程第12条が利用経費の代表者負担、第8条第3項が機器搬入出経費の利用者負担、不動産貸付要領第8条が貸付料を別に定めるとし第9条の無償貸付を限定列挙、商標取扱規程第9条第3項が収益目的の商標等使用を原則有償と規定。共用機器も時間単価課金。称号授与自体の手数料の定めはない。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'attr_certified_count', 'established', '第7号まで個別公表（2024年3月）、一覧ページ非公開', '大学公式ニュース（2024年3月14日）が株式会社SCMバイオメディカへの称号授与を「第7号」と明記。研究開発推進機構の称号授与ページ（page_id=12487）には認定企業一覧の掲載がなく、一覧を掲げると見られるFFGアントレプレナーシップセンターのサイトはドメイン全体がHTTP 401で閲覧できないため、2026年9月時点の累計社数は未確認。文科省・経産省の機関別調査値は使用していない。', 'official', 'https://www.nagasaki-u.ac.jp/ja/news/news4252.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_cert_rule', 'established', '「静岡大学発ベンチャー」称号授与制度あり', '根拠は「静岡大学における静岡大学発ベンチャーの称号授与に関する規則」（平成23年4月13日規則第2号、令和3年1月25日規則第39号改正）。第6条で「学長は、静岡大学発ベンチャーの称号授与を承認した場合は、称号記により、『静岡大学発ベンチャー』の称号を授与するものとする」と定める。第7条で称号授与は本学に法的責任を生じさせるものではないと明記。第8条で代表者に事業報告書・財務諸表の提出義務。規則本文を全条確認した。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000279.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'attr_eligible_scope', 'established', '教職員・学生（退職卒業後5年以内含む）、知財活用・技術移転・共同研究型', '称号授与規則第2条各号。(1)教職員・学生が設立又は設立に深く関与して起業した企業。教職員の退職・学生の卒業等から設立まで5年以内なら同様に扱う。(2)本学又は本学教員が所有する知的財産・研究成果・ノウハウ等を基に起業した企業。(3)本学から技術移転を受けた企業。(4)本学との共同研究を基に新事業を興した企業。(5)大学の技術等の事業化で大学独自の資金・人材供給システムを活用した企業。第3条で公序良俗・名誉毀損なきこと、教職員起業時は兼業規程等の手続・許可が適正になされていることを要件に追加。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000279.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'attr_recognition_decider', 'established', '学長決裁、機構産学連携推進部門の審査委員会が審査', '称号授与規則第5条で申請者は申請書（別紙様式1）を機構長経由で学長に申請、学長が審査委員会に審査を付議し、審査結果を踏まえ学長が授与を決定する。第4条で審査委員会をイノベーション社会連携推進機構の産学連携推進部門に置き、委員は機構長、機構産学連携推進部門長、機構社会連携機構会議の委員のうち機構長が指名した者若干人、その他機構長が指名する者若干人で構成し、委員長は機構長。第10条の取消しも学長が行う。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000279.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_cert_pre_registration', 'not_started', '設立登記前の申請・条件付認定の規定なし', '称号授与規則の全条文を確認したうえでの判断。第2条は各号とも「起業したベンチャー企業」「技術移転を受けたベンチャー企業」と設立済みの法人を定義し、第5条の申請・審査・授与手続は限定列挙で、設立登記前の申請受付、認定予定通知、条件付認定に相当する規定を置いていない。第8条は代表者に事業報告書及び財務諸表の提出を義務づけており既存法人を前提とする。なおインキュベーション施設の入居は起業検討段階の教職員・学生が対象で、称号の有無を問わない別制度。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000279.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'attr_validity_years', 'established', '有効期間・更新の定めなし、返付と取消規定のみ', '称号授与規則には有効期間や更新の条項がない。代わりに第9条で代表者からの申し出による称号の返付（学長は申し出を認めるものとする）、第10条で学長による取消し（第2条の定義から著しく逸脱した場合、社会的信用を失墜する行為を行った場合、その他本学の不名誉となるおそれがあり保持させることが適当でないと学長が認める場合）を定める。取消時は速やかに称号記を返付し、以後称号を受けていた事実を事業に使用できない。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000279.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_head_office_registration', 'unknown', null, 'インキュベーション施設の入居者募集ページ、機構の大学発ベンチャー支援ページ、イノベーション社会連携推進機構管理施設利用規則、称号授与規則のいずれにも、大学の敷地・建物の住所を会社の本店所在地として商業登記できるかの記載がない。公開情報では可否を確認できなかったため unknown とする。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_facility_lease', 'established', 'インキュベーション施設14室、使用料無料・最長3年', '浜松キャンパスのイノベーション社会連携推進機構内にインキュベーションルームを設置。「実験室タイプ」40平米が9室、「オフィスタイプ」21平米が5室。機構ページに「施設使用料は『無料』となりますが、各室の水道光熱費・通信費については実費をご負担いただきます」「利用期間は1年間です（毎年度の入居審査結果によって最長3年間の継続利用が可能）」と明記。入居資格は研究シーズを活用して自ら起業を検討する学内の教職員・学生、および地域の中小企業と共同で新事業を検討する教職員・学生。', 'official', 'https://www.oisc.shizuoka.ac.jp/inside/venture-support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_shared_equipment', 'established', '機構管理施設・共同利用機器を利用可、経費は別途負担', '株式等取得に関する規則第2条は、称号授与企業から株式等を取得する対価の一つに「大学施設・設備の使用許可」を挙げ、認定ベンチャーへの設備使用許可を制度上想定している。イノベーション社会連携推進機構管理施設利用規則第3条は利用資格者に「民間機関等の共同研究員」「その他機構長が適当と認めた者」を含め、第7条で「利用者は、施設の利用に係る経費を別に定めるところにより、負担しなければならない」（機構長が必要と認めれば一部又は全部を免除可）と定める。共同利用機器は静岡共同利用機器センターと浜松共同利用機器センターが担うが、大学発ベンチャー向けの料金区分は公開情報で確認できなかった。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000410.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_name_logo_use', 'established', '称号使用可、大学商標は学外者へ原則有償許諾', '称号授与規則第10条第2項が「当該取消しを受けた日以後、静岡大学発ベンチャーの称号の授与を受けていた事実を事業に使用してはならない」と定めており、称号保持中の事業使用が前提。大学のロゴ・標章は別制度で、静岡大学商標取扱規則（平成18年10月18日規則第18号）第8条第2項でイノベーション社会連携推進機構が使用許諾契約を締結し、同条第3項で「学外者への使用許諾又は譲渡契約は、原則として有償とする」と定める。大学発ベンチャーへの減免規定は同規則にない。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000076.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_ip_license', 'unknown', null, '［自動検証で否認: URLは株式等取得規則のみ、職務発明規則は不在］元の主張(established): 株式等を対価としたライセンス可、発明者へ優先独占許諾。株式等取得に関する規則第1条は対象を「称号を授与された大学発ベンチャー企業」に限定し、第2条で株式等取得の対価に「知的財産権のライセンス」を明記。現金対価に代えて株式・新株予約権でライセンスを受けられる。静岡大学職務発明規則（平成16年3月17日規則第387号、令和2年3月18日規則第224号改正）第8条でイノベーション社会連携推進機構が機関帰属知的財産権の実施・譲渡等の技術移転を行い、第16条第1項で発明者等に対し優先的に独占的な通常実施権又は専用実施権を許諾すると定める。実施料自体の減免規定は確認できなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_equity_rule', 'established', '称号授与企業から株式・新株予約権を取得可（審査会）', '「国立大学法人静岡大学における大学発ベンチャー企業支援を目的とした株式等取得に関する規則」（令和元年11月27日規則第22号、令和元年12月1日施行）。第1条で対象を称号授与規則により称号を授与された大学発ベンチャー企業とする。第2条で対価は知的財産権のライセンス、大学施設・設備の使用許可、技術相談業務・技術顧問業務・経営指導その他コンサルティング業務の3種。第3条でベンチャー企業株式等審査会を設置し、議長は学長が指名する理事、委員は副学長・財務施設部長・学術情報部長・外部有識者等。第5条で学術情報部長が管理、第8条で売却は審査会審査と学長承認。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000670.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_gap_fund', 'established', 'Tongali GAPファンド対象機関、学内独自基金は未確認', '名古屋大学を中心とする東海地区プラットフォーム Tongali の令和8（2026）年度GAPファンドプログラム『ステップ1』公募ページで、対象大学・研究機関（2026年8月時点）16機関に静岡大学が明記されている。研究代表者として応募できるのは所属する教職員および修士・博士課程の学生（学部生は対象外）。支援額は医療系（創薬）最大1,000万円、他分野最大500万円で、研究開発費の配賦に加え起業ノウハウ学習、ビジネスモデルブラッシュアップ、顧客訪問サポート、CxO人材マッチングを含む。原資は大学発新産業創出基金事業スタートアップ・エコシステム共創プログラム。静岡大学独自の学内GAPファンドは公開情報で確認できなかった。', 'official', 'https://tongali.net/x/gapfund2026-step1/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_accelerator', 'established', '機構コーディネータ伴走と起業家育成プログラム', 'イノベーション社会連携推進機構の大学発ベンチャー支援ページが、支援内容としてインキュベーション施設の利用、起業計画のブラッシュアップ支援、補助金・資金融資サポート、販路開拓サポートを掲げ、機構のコーディネータが支援機関や地域金融機関と連携して起業計画立案を支援すると記載。スタートアップ・エコシステム形成支援ページには大学生向け起業家人材育成プログラム（2021〜2026年度）、中高生向けプログラム（2023〜2026年度）、しずはま起業部（2022〜2026年度）、Tongaliイベントが掲載されている。', 'official', 'https://www.oisc.shizuoka.ac.jp/startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_coi_sidejob', 'unknown', null, '［自動検証で否認: 利益相反マネジメント規則はPDF全文に不在］元の主張(established): 学長許可の役員兼業制度と利益相反マネジメント規則。国立大学法人静岡大学教職員兼業規程（令和5年10月5日規程第16号改正）第3条で学長の事前許可制・許可期間は原則4年以内、第5条第1号ロで「教職員の研究成果が活用される企業の役員になる場合」を許可対象に明記、同号イでTLO役員も対象、第6条で営利企業役員兼業の適否を審査する審査委員会を設置。産学連携ページは営利企業の役員兼業は開始4か月前までの依頼が必要と案内。利益相反マネジメント規則（平成17年5月18日規則第10号、平成31年4月17日規則第12号改正）第3条が兼業・共同研究等と株式等の経済的利益を対象とし、第11条で利益相反自己申告書の提出、第6条で利益相反委員会を規定。称号授与規則第3条第4号が兼業規程等の手続・許可の適正履行を称号授与要件としており両者が接続する。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'attr_support_fee', 'established', '施設は無料（光熱費実費）、商標許諾と株式対価は有償', 'インキュベーション施設は「施設使用料は『無料』」で水道光熱費・通信費のみ実費負担（機構の大学発ベンチャー支援ページ）。機構管理施設利用規則第7条は利用経費の負担を原則としつつ機構長が必要と認めたときは一部又は全部を免除できると定める。商標取扱規則第8条第3項は学外者への商標使用許諾を原則有償とする。株式等取得に関する規則第2条は知的財産権のライセンス、大学施設・設備の使用許可、コンサルティング業務の対価として株式・新株予約権を取得する枠組みを定めており、現金以外の対価形態も制度化されている。', 'official', 'https://www.oisc.shizuoka.ac.jp/inside/venture-support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'attr_certified_count', 'established', '65社、企業名一覧を公式サイトで公開', 'イノベーション社会連携推進機構「静岡大学発ベンチャー企業の紹介」ページ冒頭に「静岡大学発ベンチャー 65社」と表示され、65社すべての企業名、説明文、公式HPリンク、会社紹介PDFが掲載されている。各社の認定年度は掲載されていない。2026-09-10時点で確認。文部科学省・経済産業省の調査値は使用していない。', 'official', 'https://www.oisc.shizuoka.ac.jp/company/venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_cert_rule', 'established', '「金沢大学認定ベンチャー」称号授与制度', '国立大学法人金沢大学認定ベンチャー称号授与規程（令和3年3月19日規程第3511号、令和3年4月1日施行、令和6年4月1日・令和8年3月6日改正）第1条が、研究成果の社会実装のため「金沢大学認定ベンチャー」の称号を授与すると定める。支援内容は同規程第6条第2項に基づく国立大学法人金沢大学認定ベンチャー支援にかかる取扱要領（令和3年4月1日研究・社会共創担当理事裁定）が定める。所管は社会共創推進部社会共創企画課（第10条）。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000794.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'attr_eligible_scope', 'established', '役職員・学生（元職・卒業生含む）設立、知財活用、会社法人の3要件', '称号授与規程第2条第1項。(1)本学の役職員又は学生（在職又は在学していた者を含む）が本学で習得した技術・知識等を活用して設立した法人、(2)本学から知的財産権の実施許諾を受けている又は本学から譲渡された知的財産権を活用している法人、(3)会社法により設立された法人、の3号すべてに該当することが要件。第2項で学長が特に必要と認めた法人も申請できる。退職後・卒業後の年数制限は置かれていない。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000794.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'attr_recognition_decider', 'established', '学長（研究企画会議の議を経て決定）', '称号授与規程第3条で、称号申請書により研究担当理事を経て学長へ申請。第4条で学長が研究企画会議の議を経て授与の可否を決定し、申請者へ通知する。第8条の称号授与の取消しも研究企画会議の議を経て学長が行う。第10条で称号の授与に関する事務は社会共創推進部社会共創企画課が処理すると定める。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000794.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_cert_pre_registration', 'established', '登記前申請可（1年以内に要件充足予定で申請）', '称号授与規程第1条が対象に「スタートアップとして起業準備中の者を含む」と明記。第2条第1項ただし書が「スタートアップとして起業準備中の者については，申請の日から1年以内に，次の各号すべてに該当する予定があることをもって申請することができる」と定める。条件付認定や認定予定通知という別枠の手続は規定されていない。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000794.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'attr_validity_years', 'established', '3年・以後2年ごとに更新可', '称号授与規程第5条第2項「称号の有効期間は，授与した日から3年間とし，以後，2年ごとに更新することができる」。第3項で更新は学長へ申請し、申請と選考は第3条・第4条（研究担当理事経由の申請、研究企画会議の議）を準用する。第7条で毎年度、事業報告書と財務諸表の提出義務があり、第8条第10号は事業報告等から活動の存続が危惧される場合を取消事由とする。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000794.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_head_office_registration', 'unknown', null, 'VBL細則、ベンチャー企業等に対する使用に係る取扱要領、VBLのQ&A（2022年8月8日付）を通読したが、会社の本店所在地としての商業登記の可否に関する記載は無い。Q&Aは食品取扱営業の「届出」をVBLの住所で行う可否について、施設としてではなく企業としての登録であれば問題ないと回答しているが、商業登記とは別の手続であり、本店登記の可否の根拠にはならない。', 'unknown', 'https://o-fsi.w3.kanazawa-u.ac.jp/about/vbl2/vbl/update/QandA-240206.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_facility_lease', 'established', 'VBLの個室・工房を有償貸与、原則3年最大5年', '金沢大学先端科学・社会共創推進機構ベンチャー・ビジネス・ラボラトリー細則（平成31年1月30日規程第3013号）第8条第2項が、設立後5年以内の未上場法人や研究資金を確保して1年以内の起業を予定する者を学外使用者の承認対象とする。ベンチャー企業等に対する使用に係る取扱要領第2条で研究室等の個室又はVBL工房の使用を申請、第4条で使用期間は原則3年以内・最大5年以内、VBL長が認めれば6年目以降も使用できる。', 'official', 'https://o-fsi.w3.kanazawa-u.ac.jp/about/vbl/vbl/update/vbl-youryou-r3.06_vc.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_shared_equipment', 'established', '設備共同利用推進総合システムで学外にも有償開放', '機構の「大学設備の利用」ページが、共同利用可能な研究機器・設備を設備共同利用推進総合システムに掲載し「ぜひ大学発ベンチャーの起業、運営にご活用ください」と案内。オンラインで空き状況把握・予約・利用料精算を行う。研究基盤統括本部の学外受託サービス利用約款第2条が学外依頼者の要件（反社会的勢力と無関係、安全保障輸出管理上の懸念なし、利用料金の支払能力等）を定め、第7条で受託業務料金を徴収する有償区分とする。［検証エージェントは出典を開けず未照合］', 'official', 'https://o-fsi.w3.kanazawa-u.ac.jp/venture/skrs.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_name_logo_use', 'established', '称号使用可、ロゴマーク等を無償使用許諾', '認定ベンチャー支援にかかる取扱要領第2条第1号「『金沢大学認定ベンチャー』のロゴマーク等の無償使用許諾」。同条第2号で本学ホームページでの認定事実の公開、第3号で本学広報誌等での情報発信を支援メニューに規定。称号授与規程第8条第2項は、取消しを受けた法人は速やかに称号記を返付し、以後、称号を授与されていた事実を事業に使用してはならないと定める。', 'official', 'https://o-fsi.w3.kanazawa-u.ac.jp/update/venture_youryou.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_ip_license', 'established', '年限を区切った知財の独占実施の許可', '認定ベンチャー支援にかかる取扱要領第2条第4号「一定の年限を区切って当該知的財産権の独占実施の許可」。機構のベンチャー認定制度ページは同項目を「所定の会議での承認を受けて」と補記する。金沢大学職務発明等取扱規程（平成16年4月1日規程第6号）第17条は通常実施権の許諾・専用実施権の設定・権利の譲渡を定めるが、認定ベンチャー向けの対価減免の特則は置いていない。', 'official', 'https://o-fsi.w3.kanazawa-u.ac.jp/update/venture_youryou.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_equity_rule', 'established', '事業対価として株式・新株予約権を取得可', '国立大学法人金沢大学におけるベンチャー企業を対象とした収益を伴う事業の対価として取得する株式等取扱規程（令和4年1月21日規程第3677号）第2条第4号が株式等を株式及び新株予約権と定義。第3条で知財の実施許諾等の対価を現金に代えて株式等で取得できる。第4条で研究企画会議が審査、第5条で学長が決定し契約を取り交わす。第7条で経営参加権は原則不行使。管理・売却は株式等管理規程（規程第3678号）が定める。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000873.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_gap_fund', 'established', 'TeSH GAPファンド主幹機関、ステップ1最大500万円', '本学ニュース「令和7年度TeSH GAPファンドプログラムに本学から8名の研究者が採択されました」が、金沢大学は北陸先端科学技術大学院大学とともにTech Startup HOKURIKU（TeSH）の主幹機関であり、ステップ1採択者に1年間の研究開発費として最大500万円を支援すると記載。応用研究のステップ1と、概念実証からスタートアップ組成までのステップ2で構成。VBLのQ&Aは起業プロジェクトにVBL利用料の7割を上限に1年間の財政支援を行うと記載。', 'official', 'https://www.kanazawa-u.ac.jp/en/news/165084', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_accelerator', 'established', '経営指導・支援とVBLコーディネーターの助言', '認定ベンチャー支援にかかる取扱要領第2条第7号「本学が協定を締結する機関とタイアップした経営指導・支援」、第6号で協定機関への斡旋・紹介を支援メニューに規定。VBLコーディネーターに関する取扱要領（令和6年3月14日VBL長裁定、令和6年4月1日施行）第2条で、VBLの事業実施に係る活動と、本学の戦略に基づく起業支援活動全般に係る助言を担当する。機構はワンストップサービス窓口を設置している。', 'official', 'https://o-fsi.w3.kanazawa-u.ac.jp/about/vbl2/vbl/update/vbl-coordinator.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_coi_sidejob', 'unknown', null, '［自動検証で否認: 同URLは利益相反規程のみ、職員兼業規程は不掲載］元の主張(established): 研究成果活用企業の役員兼業を承認制、利益相反規程で管理。国立大学法人金沢大学職員兼業規程（平成16年4月1日規程第94号）第4条は営利企業の役員兼業を原則不承認とし、技術移転事業者・研究成果活用企業の役員等、監査役、社外取締役、無報酬の場合、学生の起業支援は勤務時間外に限り学長の承認で可とし、総務企画会議の審査を経る。第5条の2は本学が出資した事業者の役員兼業を承認制とする。金沢大学利益相反マネジメント規程（令和6年5月17日規程第4186号）第3条は株式保有等の経済的利益や施設・設備の利用提供を管理対象とし、第16条で申告・審査・回避要請を定める。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'attr_support_fee', 'established', '認定支援は無償、VBL入居と機器利用は有償', '認定ベンチャー支援にかかる取扱要領第2条の支援10項目は、ロゴの無償使用許諾、情報発信、独占実施の許可、斡旋・紹介、経営指導、補助金情報提供、表彰推薦で、費用徴収の規定を置いていない。一方、VBLベンチャー企業等使用取扱要領第12条は個室の使用料単価を当初3年間は1平方メートル当たり月額300円、4年目以降は月額1,000円、VBL工房は1席月額2,000円とし、光熱水料を別途負担させる。第13条でVBL長が認めれば一部又は全部を免除できる。', 'official', 'https://o-fsi.w3.kanazawa-u.ac.jp/about/vbl/vbl/update/vbl-youryou-r3.06_vc.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'attr_certified_count', 'established', '4社（2021年9月27日時点、社名を公開）', '機構のベンチャー認定制度ページが、2021年9月27日に本学初となる「金沢大学認定ベンチャー」称号授与式を行い4社を認定したと記載し、株式会社キュービクス、株式会社バイオセラピー開発研究センター、Ostics株式会社、株式会社Kanazawa Diamondの社名・創業年・事業内容を掲載している。同ページに以後の追加認定の掲載は無く、これより新しい累計社数を示す機関自身の公開情報は確認できなかった。', 'official', 'https://o-fsi.w3.kanazawa-u.ac.jp/venture/certificate.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_cert_rule', 'established', '大学発ベンチャー等の支援に関する規則に基づく3区分認定制度', '国立大学法人熊本大学大学発ベンチャー等の支援に関する規則（平成30年3月22日規則第81号、平成30年4月1日施行、全12条）が根拠。第2条で「大学発ベンチャー」「熊本大学認定ベンチャー」「熊本大学認定法人」の3区分を定義し、第3条第1項各号アで各区分に対応する称号を授与し使用させる。ベンチャー推進部門の大学発ベンチャー支援制度ページと「支援に関する概略」図でも同じ3区分を掲示。', 'official', 'https://venture.kuma-u.jp/wp/wp-content/uploads/kumadai_venture_kisoku.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'attr_eligible_scope', 'established', '教職員・学生の起業、退職卒業後3年以内、準備中も対象', '支援規則第2条第1号。ア＝教職員等及び学生等が本学で行った発明等に係る知的財産権の技術を基に起業し又は起業の準備を行っている企業等、イ＝本学で得られた研究成果又は成果有体物等を基にしたもの、ウ＝教職員等及び学生等であった者が退職・卒業・修了後原則3年以内に本学の知的財産権又は研究成果等を基に設立し又は設立に深く関与したもの、エ＝学生等が在学中に設立し学長が特に認めるもの。第2号の認定ベンチャーは大学発ベンチャーのうち実施権許諾を受けたもの、第3号の認定法人は共同研究を行いかつ実施権許諾を受けた企業等。第8号で企業等は株式会社・合同会社・有限責任事業組合等とする。', 'official', 'https://venture.kuma-u.jp/wp/wp-content/uploads/kumadai_venture_kisoku.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'attr_recognition_decider', 'established', '学長が研究開発戦略本部知的財産審査委員会の議を経て決定', '支援規則第5条第1項で企業等の代表者が別記様式第1号又は第2号により学長へ申請、第2項で学長は「熊本創生推進機構知的財産審査委員会の議を経て、支援の可否を決定する」、第3項で支援決定通知書（別記様式第3号）により通知。同委員会は組織改編で承継され、熊本大学研究開発戦略本部知的財産審査委員会細則（令和7年3月28日細則第19号）第3条第4号が審議事項に「大学発ベンチャー企業の認定に関すること」を明記。旧熊本創生推進機構知的財産審査委員会細則は同細則附則2で廃止。', 'official', 'https://venture.kuma-u.jp/wp/wp-content/uploads/kumadai_venture_kisoku.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_cert_pre_registration', 'established', '起業準備中も申請可、支援決定後6か月以内に登記見込み要', '支援規則第2条第1号ア・イが「起業の準備を行っている企業等」を対象に含む。第4条第1号後段で「起業準備の段階にある企業等にあっては、支援決定後6月以内に法人登記が完了する見込みであること」を支援条件とする。第4条第6号後段は、教職員を役員に就任させる場合の兼業手続について、準備段階の企業等では法人登記までに完了する見込みでよいとする。熊本大学認定ベンチャー・熊本大学認定法人は「支援に関する概略」で法人登記済が条件と明示。', 'official', 'https://venture.kuma-u.jp/wp/wp-content/uploads/kumadai_venture_kisoku.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'attr_validity_years', 'established', '大学発は5年以内、認定はライセンス契約期間', '支援規則第3条第2項。大学発ベンチャーへの支援期間は5年を超えない範囲で学長が必要と認める期間、熊本大学認定ベンチャー及び熊本大学認定法人への支援期間は本学が有する知的財産権又は研究成果等の実施権の許諾に関する契約期間。ただし書で大学発ベンチャーの称号の使用は支援期間の終了後も引き続き使用させることができる。更新に関する条文は置かれていない。第7条で毎年度の事業報告書・収支決算書を翌年6月末日までに提出、第8条で定義非該当・法令違反・事業実態の消失・事業報告未提出等の場合に学長が支援決定を取り消せる。', 'official', 'https://venture.kuma-u.jp/wp/wp-content/uploads/kumadai_venture_kisoku.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_head_office_registration', 'established', '貸与施設の住所で登記可、賃貸契約に基づく有償貸付', '支援規則第3条第1項第1号ウ（大学発ベンチャー）と第2号ウ（熊本大学認定ベンチャー、移転登記）で、本学の施設を使用する場合に当該施設の住所を登記に使用できる。第10条第1項で、施設・設備の貸付及び登記における本学住所地の使用は国立大学法人熊本大学固定資産管理規則（平成27年3月31日制定）その他基準により行うと定め、有償の賃貸を前提とする。「支援に関する概略」も「貸与地にて登記可」「貸与地にて移転登記可」「大学との賃貸契約が必要」と記載。熊本大学認定法人には登記に関する支援の記載がない。', 'official', 'https://venture.kuma-u.jp/wp/wp-content/uploads/kumadai_venture_kisoku.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_facility_lease', 'established', '地共ラボ・インキュベーションラボ・VBL等を賃貸契約で貸与', '支援規則第3条第1項第1号イで、大学発ベンチャーは地域共同ラボラトリー、インキュベーションラボラトリー又はベンチャービジネスラボラトリーを事業の範囲内で使用できる。第2号イ・第3号イで熊本大学認定ベンチャー及び熊本大学認定法人は「本学の施設及び設備」を使用できる。「支援に関する概略」は地共ラボ、インキュベーションラボ、VBL、産業イノベーションラボを挙げ「大学との賃貸契約が必要」と明記。貸付は第10条第1項により固定資産管理規則等の基準による。使用料の料金表は公開されていない。', 'official', 'https://venture.kuma-u.jp/wp/wp-content/uploads/kumadai_venture_kisoku.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_shared_equipment', 'established', '認定ベンチャー・認定法人は施設に加え設備も使用可', '支援規則第3条第1項第2号イ「本学の施設及び設備の熊本大学認定ベンチャーの事業の範囲内での使用」、第3号イ「本学の施設及び設備を熊本大学認定法人の事業の範囲内での使用」。第1号イの大学発ベンチャーは特定3施設の使用のみで設備の記載がなく、区分により差がある。第10条第1項で設備の貸付も固定資産管理規則等の基準により行い、第3項で故意過失による滅失・損傷時の原状回復又は損害賠償義務を課す。共用機器の料金区分を示す公開資料は確認できなかった。', 'official', 'https://venture.kuma-u.jp/wp/wp-content/uploads/kumadai_venture_kisoku.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_name_logo_use', 'established', '3区分の称号使用可、認定ベンチャーはマークも使用', '支援規則第3条第1項各号アで「熊本大学発ベンチャー」「熊本大学認定ベンチャー」「熊本大学認定法人」の称号の授与及び使用を支援内容とする。「支援に関する概略」では熊本大学認定ベンチャー企業のみ「称号およびマーク使用」と記載され、他の2区分は「称号使用」。第3条第2項ただし書で大学発ベンチャーの称号は支援期間終了後も使用可。第8条第3項で支援決定取消の通知日以降、授与された称号及び支援を受けていた事実を事業に使用してはならない。ロゴ・校章の個別使用条件を定める公開文書は確認できなかった。', 'official', 'https://venture.kuma-u.jp/wp/wp-content/uploads/kumadai_venture_kisoku.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_ip_license', 'established', '認定ベンチャーへ実施権許諾の優遇措置、株式対価も可', '支援規則第3条第1項第2号エ「本学が所有する知的財産権又は研究成果等の実施権の許諾に関する優遇措置」。「支援に関する概略」も熊本大学発ベンチャー企業及び熊本大学認定ベンチャー企業への支援として「知財使用の優遇措置」を掲げる。優遇の具体的内容（独占許諾の可否、実施料率の減免幅）を定めた公開文書は確認できなかった。株式等取扱規則第3条第2号は、ベンチャー企業の資力等を勘案し支援を無償とし又は対価を時価より低く定める必要がある場合に支援の対価を株式等で取得できるとし、対価減免と株式対価の経路がある。', 'official', 'https://venture.kuma-u.jp/wp/wp-content/uploads/kumadai_venture_kisoku.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_equity_rule', 'established', '支援対価として株式・新株予約権を取得する規則あり', '国立大学法人熊本大学におけるベンチャー企業への支援の対価として取得する株式等取扱規則（平成28年3月24日規則第49号、最終改正 令和7年3月27日規則第133号）。第2条第3号で株式等＝株式及び新株予約権。第3条で支援の対価の全部又は一部を株式等で取得できる要件を定め、第4条で熊本大学研究開発戦略本部知的財産審査委員会が外部専門家の意見も聴いて審査、第5条で学長が取得の可否を決定し契約書を取り交わす。第6条で売却等責任者を総務・財務・施設担当の理事とし、第7条で新株予約権の行使、第8条で株式の売却、第9条で経営参加権の原則不行使を定める。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110000930.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_gap_fund', 'unknown', null, 'ベンチャー推進部門の大学発ベンチャー支援制度ページ、支援に関する概略、アントレプレナーシップ教育ページ、支援規則本文、熊本大学規則集の現行規則一覧を確認したが、学内GAPファンド・起業準備資金・POC資金の制度を定めた公開文書は確認できなかった。支援規則第3条の支援メニューは称号、施設設備の使用、登記住所の使用、知財実施権許諾の優遇、イベント等での紹介で構成され資金供与の項目はないが、同項に「その他学長が必要と認める支援」があり限定列挙とは断定できないため not_started とはしない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_accelerator', 'established', 'ベンチャー推進部門が相談窓口、コンソーシアムで支援', '支援規則第3条第1項第2号オ・第3号ウで、熊本創生推進機構（現・研究開発戦略本部）所管のイベント、ウェブサイト等による事業内容の紹介を支援内容とする。「支援に関する概略」は「大学所管イベント等で紹介」「ベンチャーコンソーシアムで支援」を掲げる。研究開発戦略本部ベンチャー推進部門がベンチャービジネスラボラトリー1階にベンチャー支援室を置き、大学発ベンチャー支援制度ページで教職員・学生等の起業相談を受け付けると明記。部門概要ページは構想段階からの伴走支援を掲げる。学生向けにはコーチング付きのアントレプレナーシップ実践プログラムと学生ベンチャー夢プロジェクトを実施。名称付きのアクセラレーションプログラム公募要項は確認できなかった。', 'official', 'https://venture.kuma-u.jp/program/academic_startups/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_coi_sidejob', 'established', '兼業規則の許可を認定条件化、利益相反は自己申告で管理', '支援規則第4条第6号は、本学の教職員を役員に就任させる場合、国立大学法人熊本大学職員兼業規則（平成16年4月1日制定）及び国立大学法人熊本大学営利企業役員等兼業及び勤務時間内非役員兼業規則（同日制定）その他関係規則に定める手続・許可が適正になされていることを支援条件とする。後者は第2条で研究成果活用兼業・技術移転兼業・監査役兼業を定義し、第4条で営利企業役員等兼業審査委員会が審査、第14条で兼業終了後2年間の利害関係業務を制限。国立大学法人熊本大学利益相反管理に関する規則（平成16年9月30日規則第274号）第3条はベンチャー企業経営等の兼業と株式等の取得・保有を管理対象とし、第14条で年度末の自己申告書提出を義務づける。', 'official', 'https://venture.kuma-u.jp/wp/wp-content/uploads/kumadai_venture_kisoku.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'attr_support_fee', 'established', '称号は無償、施設貸与と登記住所使用は賃貸契約で有償', '支援規則第10条第1項で、施設・設備の貸付及び登記における本学住所地の使用は国立大学法人熊本大学固定資産管理規則（平成27年3月31日制定）その他基準により行うと定める。「支援に関する概略」は施設貸与に「大学との賃貸契約が必要」と明記。知的財産の実施権許諾は別途ライセンス契約に基づき、株式等取扱規則第3条第2号により資力等を勘案して無償化又は時価より低い対価とし対価を株式等で取得できる。称号の授与・使用、イベント等での紹介について対価の定めはなく無償と読める。使用料・実施料の金額表は公開されていない。', 'official', 'https://venture.kuma-u.jp/wp/wp-content/uploads/kumadai_venture_kisoku.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'attr_certified_count', 'established', '大学発ベンチャー一覧を公開、2018〜2025年度で20社', 'ベンチャー推進部門の「熊本大学発ベンチャー一覧」ページに認定年度・設立日・会社名の一覧表があり、2026年9月10日時点で認定年度2018年から2025年までの20社を新しい順に掲載。3区分（大学発ベンチャー／認定ベンチャー／認定法人）別の内訳は同ページに記載がない。熊本創生推進機構の2025年5月14日付お知らせは、令和7年2月18日開催の学内会議の議を経て3社へ「熊本大学発ベンチャー企業」の称号を付与したと記載し、うち2社が一覧に反映されている。', 'official', 'https://venture.kuma-u.jp/program/academic_startups/univ_venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_cert_rule', 'unknown', null, '［自動検証で否認: 登録制度・称号は確認。旧制度からの改組との記述はPDF原文になし］元の主張(established): 登録制度あり、称号「芝浦工業大学登録ベンチャー」。2026年4月開始の「芝浦工業大学発ベンチャー登録制度」。BOiCEページに掲載の公式資料「芝浦工業大学発ベンチャー登録制度のご案内」（2026年4月版）に制度概要・対象・恩典・支援期間を明記。目的は研究成果や学生・教職員のアイデアの社会還元と大学発ベンチャーの支援・育成。称号は「芝浦工業大学登録ベンチャー」。2023年4月開始の旧「芝浦工業大学発ベンチャー」認定制度を改組したもの。根拠規程そのものは非公開で、公開文書は案内資料と登録申請書のみ。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'attr_eligible_scope', 'established', '在籍・退職5年以内の教職員、在学生・卒業生が籍を置く企業', 'ご案内PDF「対象企業」欄。①本学に在籍している教職員又は本学退職後5年以内の教職員、②本学に在籍している学生又は本学卒業生、のいずれかが籍を有する大学発ベンチャー企業。同PDF2ページ目で大学発ベンチャー企業を6類型（①研究成果②共同研究③技術移転④学生⑤教職員等⑥関連）に定義。②③は設立5年以内の共同研究・技術移転を要件とし、④～⑥は新規性・挑戦性を要して既存事業の起業や個人事務所の開業を除く。', 'official', 'https://www.shibaura-it.ac.jp/assets/venture_inf_ver2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'attr_recognition_decider', 'established', '複合領域産学官民連携推進本部長宛の申請', '「芝浦工業大学ベンチャー登録申請書」の宛名が「芝浦工業大学 複合領域産学官民連携推進本部長 殿」。同本部は大学の産学官民連携の拠点組織として産学官民連携ポリシーに位置づけられている。申請の受付窓口は研究推進部オープンイノベーション推進課（ご案内PDF問い合わせ欄）。審査を行う会議体・委員会の名称、議決手続、審査基準を定めた文書は公開情報では確認できない。', 'official', 'https://www.shibaura-it.ac.jp/assets/venture_form.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_cert_pre_registration', 'not_started', '不可、履歴事項全部証明書の添付が必須', 'ご案内PDF「申請書類」欄は①大学発ベンチャー登録申請書②法人概要③誓約書④履歴事項全部証明書の4点を限定列挙。登録申請書の添付書類欄も「履歴事項全部証明書（最新のものであり、かつ申請日前3か月以内に発行されたもの）」と明記し、写しの場合は原本相違なき旨の記載と押印を求める。設立登記済みであることが申請の前提で、設立登記前の申請、認定予定通知、条件付認定を受け付ける規定は公開資料にない。', 'official', 'https://www.shibaura-it.ac.jp/assets/venture_inf_ver2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'attr_validity_years', 'established', '最長3年、更新2回まで', 'ご案内PDF「支援期間（登録期間）」欄。1度での支援期間は最長3年間。継続して支援を希望する場合は改めて申請書類を提出する。更新回数は2回までと明記されており、通算では最長9年間となる。', 'official', 'https://www.shibaura-it.ac.jp/assets/venture_inf_ver2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_head_office_registration', 'established', '可、事前許可制で有償（郵便BOX利用と合算）', '「SITインキュベーションスクエア シェアオフィス利用規約」（令和4年12月23日版、令和6年3月28日改定）第6条14項「利用者が本施設の住所を用いて商業登記等登記を希望する場合は、利用者は所定の手続きにより事前に管理責任者に申し出て許可を得てください」。別表2備考(ウ)で、登記した場合は登記日翌月分より郵便BOXの利用と合わせて追加の月額利用料を負担すると規定。所在地は豊洲キャンパス本部棟10階。', 'official', 'https://www.shibaura-it.ac.jp/assets/SharedOffice_Rules.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_facility_lease', 'established', 'SITインキュベーションスクエアのシェアオフィス、有償', 'BOiCE（豊洲キャンパス本部棟10階）内のSITインキュベーションスクエア。シェアオフィスは固定席と自由席の2区分で月額有償、利用可能時間は定休日を除く9:00〜22:00。利用規約第2条2項で申込期間は1か月以上・当該年度末まで、前月20日までの申込。別表1にコワーキングスペース、会議室2室、個室ブースを規定。ほかに産学官民連携ラボ（ドライ系11室・ウェット系5室）を設置。2023年の旧認定制度のニュースにあった研究室貸与は、2026年の登録制度の恩典欄には含まれない。', 'official', 'https://www.shibaura-it.ac.jp/research/industry/boice.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_shared_equipment', 'established', '学外者利用約款で可、大学等と民間企業の2料金区分', '共通機器・ものづくりセンター（テクノプラザ、豊洲・大宮）の学外利用。大学公式「共通機器・ものづくりセンター外部利用」ページに、2026年4月15日付で「共用研究装置・設備 学外者利用約款」を制定し2026年5月1日から運用と明記。申請書提出→書類審査（必要に応じヒアリング）→SIT総合研究所長名の承諾書という流れ。料金は年間利用登録料（定額制）＋装置利用料（1時間単価×予約時間）で、単価は大学・公的機関と民間企業等で別設定。消耗品は実費負担。登録ベンチャー向けの優遇区分の記載はない。', 'official', 'https://www.shibaura-it.ac.jp/research/internal/techno_external_use/riyou.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_name_logo_use', 'established', '称号付与とロゴ使用が恩典、申請時に選択', 'ご案内PDF「支援内容(恩典)」に「『芝浦工業大学登録ベンチャー』の称号付与」と「芝浦工業大学登録ベンチャーのロゴ使用」を明記。登録申請書の「希望の恩典にチェックしてください」欄でも「登録ベンチャー称号」「ロゴ使用」を個別に選択する形式。恩典として示されるのは登録ベンチャー用のロゴであり、大学校章そのものの使用条件を定めた文書は公開情報では確認できない。', 'official', 'https://www.shibaura-it.ac.jp/assets/venture_inf_ver2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_ip_license', 'unknown', null, '2026年4月開始の登録制度のご案内PDFの恩典欄（称号付与／ロゴ使用／大学公式ホームページや広報誌等への掲載／経営相談・支援／情報提供）と、登録申請書の恩典選択欄（同じ5項目）に、知財の実施許諾は含まれない。他方、2023年4月開始の旧認定制度を伝える大学公式ニュース（nid00003197）には「大学が保有する特許の実施権を付与」と記載がある。現行制度で実施許諾の優遇が継続しているかを示す規程・要項は公開情報で確認できない。独占許諾、対価減免、株式対価の定めも同様。', 'unknown', 'https://www.shibaura-it.ac.jp/assets/venture_inf_ver2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_equity_rule', 'unknown', null, '大学がベンチャーの株式・新株予約権を取得する規程は、産学連携・知的財産、BOiCE、複合領域産学官民連携推進本部、利益相反マネジメントの各公式ページおよび登録制度のご案内PDF・登録申請書のいずれにも記載がない。ご案内PDF2ページ目の大学発ベンチャー定義⑥「大学からの出資がある等その他、大学と深い関連のあるベンチャー」は、対象企業を分類するための一般的な類型定義であり、大学が出資・新株予約権取得を行う制度の根拠ではない。', 'unknown', 'https://www.shibaura-it.ac.jp/assets/venture_inf_ver2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_gap_fund', 'unknown', null, '学内GAPファンド、起業準備資金、POC資金の制度は公開情報で確認できない。学生向け「SIT GRIT² Program」は、レベル別の無料個別相談、アントレプレナーシップ講座、起業情報の提供が内容で、資金提供の記載はない（名称のGrant Programは相談・育成プログラムを指す）。2024年1月に東京都「大学発スタートアップ創出支援事業」に選定され、東京都から伴走支援と経費支援を受けて研究テーマ5件のシーズ育成に取り組むが、これは大学の取組に対する支援であり、ベンチャーへの資金供与制度としては公開されていない。', 'unknown', 'https://www.shibaura-it.ac.jp/assets/Grit_Program.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_accelerator', 'established', '経営相談・支援が恩典、学生向けGRIT²と相談窓口', '登録制度の恩典に「経営相談・支援、情報提供」を明記。学生向けは「SIT GRIT² Program」で、初心者向けのなんでも相談から、ビジネスプラン・知財・会社設立・資金調達といった詳細相談まで無料の個別相談を提供し、必要に応じ専門家相談を実施。アントレプレナー連続実践講座等のセミナー、起業家等との交流イベントも実施。芝浦ビジネスモデルコンペティション（SBMC）と連動した個別相談もある。窓口は研究推進部オープンイノベーション推進課。', 'official', 'https://www.shibaura-it.ac.jp/assets/Grit_Program.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_coi_sidejob', 'established', '利益相反マネジメント規程あり、教職員は申告制', '大学公式「利益相反マネジメント」ページに、利益相反の発生およびその事実を適切に管理し、産学官連携活動等の推進と社会的信用の保持を両立するため「利益相反マネジメント規程」を定めると明記。これに基づき教職員へ自身の活動等の申告を求め、毎年の状況調査期間外に発生したものも随時受け付ける。マネジメント体制図と関連書類は学内限定の共有サイトに置かれ非公開。産学官民連携ポリシー第5項も利益相反の適切な処理を掲げる。役員兼業・株式保有の許可手続を定めた兼業規程は公開情報では確認できない。', 'official', 'https://www.shibaura-it.ac.jp/research/ethics/coi.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'attr_support_fee', 'established', '施設利用と機器利用は有償、登録自体は費用記載なし', '登録制度のご案内PDFと登録申請書に、登録料や支援料の記載はない。恩典として示される称号付与、ロゴ使用、大学ホームページ・広報誌等への掲載、経営相談・支援、情報提供にも費用の定めはない。一方、施設側は有償で、シェアオフィスは固定席・自由席とも月額利用料が定められ、本施設住所での商業登記を行う場合は郵便BOX利用と合わせた追加負担が生じる。共通機器の学外利用も年間利用登録料と装置利用料の有償で、消耗品は実費負担。', 'official', 'https://www.shibaura-it.ac.jp/assets/SharedOffice_Rules.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'attr_certified_count', 'established', '公表は旧制度第1号の1社のみ、一覧ページなし', '大学公式ニュース（2023年6月）で、2023年4月開始の旧認定制度の第1号として1社を実名で公表。2024年7月の大学公式ニュースでも同社を「芝浦工大発の第1号認定ベンチャー」として紹介している。認定・登録企業の一覧ページは、大学公式サイトマップに収録された全6,432件のURLを検索しても存在せず、社数の総数を示す機関自身の公開情報は確認できない。2026年4月開始の登録制度は恩典として大学公式ホームページや広報誌等への掲載を掲げているが、掲載先ページは未整備とみられる。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.shibaura-it.ac.jp/headline/detail/nid00003197.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_cert_rule', 'established', '大阪公立大学発ベンチャー企業取扱規程に基づく認定と称号付与', '令和6年10月29日規程第223号、令和6年11月1日施行、全14条。第3条第1項で学長が企業代表者の申請に基づき「大阪公立大学発ベンチャー企業」の認定及び称号を付与。第13条で事務はスタートアップ創出・支援センターが所管。附則第2項で旧大阪府立大学発ベンチャー・大阪市立大学発ベンチャー等のうち令和6年10月31日までに所定手続を行ったものは本規程で認定されたものとみなす。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'attr_eligible_scope', 'established', '特許移転・研究成果活用・人材移転・その他関係の4類型', '規程第2条（定義要件）。(1)特許による技術移転型＝大学で承継した特許をもとに起業、(2)特許以外による技術移転型・研究成果活用型＝本学で達成された研究成果又は習得した技術等に基づく起業、(3)人材移転型＝本学の教職員・学生等が設立者又は設立に深く関与（教職員の退職や学生の卒業後1年以上経過した者は原則対象外）、(4)その他関係型＝本学が支援をした起業。個人事業所を含む。申請者は企業の代表者（第3条第2項）。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'attr_recognition_decider', 'established', '学長（スタートアップ創出・支援センターの議）', '規程第3条第3項「学長は、前項の申請があったときは、前条に規定する要件をもとにスタートアップ創出・支援センターの議を経て、認定及び称号付与の可否を決定する」。称号付与にあたり必要に応じて企業の代表者へヒアリングを実施。第3条第4項で様式第2号（認定審査結果・称号付与通知書）により申請者へ通知。第12条の取消し時の意見聴取も同センターを通じて実施。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_cert_pre_registration', 'not_started', '登記簿謄本の写しが必須で設立登記前の申請は不可', '様式第1号「大学発ベンチャー企業申請書」（規程第3条第2項関係）の提出書類欄に「商業・法人登記簿謄本等の写し及び会社概要は、提出が必須」と明記。個人事業所の場合も税務署受付印のある開業届の写しの提出を求める。申請書には事業開始日・設立日の記入欄がある。規程本文にも設立登記前の申請、認定予定通知、条件付認定の定めはない。', 'official', 'https://www.omu.ac.jp/assets/venturerelatedforms_v2.doc', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'attr_validity_years', 'established', '期限なし・更新規定なし、毎年9月末に事業報告', '規程に有効期間と更新の条項はない。第9条第1項で代表者は毎年9月末までに様式第5号により事業報告を提出（様式第5号の提出書類欄で直近の事業年度の決算書の写しが必須）。第10条で称号使用の終了は様式第6号による事前申出と学長の許可。第11条で企業活動の実態消失、社会的信用の失墜、事業報告の拒否、解散・破産手続開始決定等により認定及び称号付与を取り消す。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_head_office_registration', 'established', 'インキュベータ入居期間中のみ登記面住所を施設内に可', '規程第8条第1項第1号（便宜措置）「本学の管理するインキュベータ等施設に入居している場合、入居期間中のみ、登記面住所を該当施設内とすること」。第8条第3項で代表者が様式第3号により申請し、第4項で学長が様式第4号により通知。様式第1号の注記で、登記面住所と実質本社の所在地が相違する場合は申請書の所在地欄に実質本社の所在地を記載するとされる。登記に対する個別の対価の定めはない。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_facility_lease', 'established', '大阪公立大学インキュベータ、2年以内・月額有償', '大阪公立大学インキュベータ規程（令和4年4月1日規程第91号）第3条でインキュベータオフィス、共同研究室、会議室、談話コーナー等を設置。第4条で本学の研究成果等を活用して技術革新や社会還元を目指す個人及び法人が入居可。第5条で活用予定の研究を行う教員等の承諾と学長の承認が必要。第6条で入居期間は2年以内、利用細則第3条で延長は1年以内・2回を限度（発ベンチャー取扱要項に基づき学長が特に認める場合は例外）。杉本キャンパス内の鉄筋コンクリート造2階建、オフィスは4区分12室。', 'official', 'https://www.omu.ac.jp/assets/incubatorrules.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_shared_equipment', 'established', '共用研究機器センターOShaREで学外区分により利用可', '共用研究機器センター（OShaRE）のページで機器利用に「学内利用」と「学外利用」の2区分があると明記され、学外機関が共用機器を利用できる。手続は問合せ・事前相談、見積り・契約、利用と利用報告書の提出、支払いの4段階。認定ベンチャー専用の料金優遇は公開情報では確認できない。認定事前チェックシート(4-2)でも大学等の施設・設備を利用する場合は各施設・設備管理部局の規則等に則った手続の完了を求めている。', 'official', 'https://www.omu.ac.jp/oshare/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_name_logo_use', 'established', '称号使用可、品質保証目的での使用は禁止', '規程第3条で学長が「大阪公立大学発ベンチャー企業」の称号を付与。第6条（称号使用の制限）「本学発ベンチャー企業は、自社の製品、サービス等の内容及び品質を保証するために、称号を使用してはならない」。第7条（免責）で本学は製品・サービスの内容及び品質並びに経営状況を保証せず法的責任も負わないと定める。第10条で称号使用の終了は様式第6号による事前申出。大学ロゴ・校章の使用条件は本規程に定めがない。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_ip_license', 'established', 'ライセンス対価の新株予約権化、特許移転型に限定', '規程第8条第1項第3号で便宜措置として「知的財産権のライセンス等の対価の全部又は一部を新株予約権とすること」を定める。第8条第2項で第2条第1号（特許による技術移転型）による認定かつ本学が保有する知的財産権又は研究成果等について実施許諾を受けているものに限定。公立大学法人大阪知的財産権取扱規程（令和4年3月31日規程第87号）には独占的実施許諾や対価減免の優遇規定はない。認定事前チェックシートは使用許諾の契約窓口を技術移転推進オフィスとする。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_equity_rule', 'established', '知財対価として株式・新株予約権を取得する規程あり', '公立大学法人大阪における知的財産権の運用又は処分の対価として取得する株式等の取扱規程（令和6年9月2日規程第208号、令和6年9月4日施行）。第2条第1項で大学発認定ベンチャー企業を対象に、企業が現金を保有していない場合、現金支払いにより資金繰りに窮すると認められる場合、経営に著しい影響を及ぼすと認められる場合に理事長が株式及び新株予約権の取得を決定できる。第2条第2項で社会的信用に問題がある場合や共益権行使が必要な場合等は取得禁止。第3条で産学官民共創推進本部の審査を経る。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200788.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_gap_fund', 'established', 'GAPファンド（IV・PSF・OD・BCB・PMF）を毎年度公募', 'スタートアップ創出・支援センターの事業化関連プログラム一覧に2024年度第2回から2026年度第4回までのGAPファンド公募が掲載。STEP1は研究者単独申請・支援期間1年で、Idea Verification（顧客ニーズの存在検証）、Problem Solution Fit（ソリューション有効性の検証）、Overseas Deployment（起業当初からの海外展開）、Back-Casted Business（将来の社会課題起点の技術選択検証）の4プログラム。STEP2は研究者とVC等事業化推進機関の共同申請・支援期間2年のProduct Market Fitプログラム。実施主体はKSAC（関西スタートアップアカデミア・コアリション）とSUCSUC。', 'official', 'https://www.omu.ac.jp/startup/info/grant/entry-119863.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_accelerator', 'established', 'スタートアップ創出・支援センターSUCSUCが常設支援', '2024年4月1日に産学官民共創推進本部へスタートアップ創出・支援センター（SUCSUC）を設置し、学生・教員の起業と起業後の成長を支援。ページに起業相談窓口、事業化関連プログラム（GAPファンド、競争的資金獲得セミナー）、アクセラレーションプログラム（SUCSUC-TCAP、SUCSUC-CONNECT Summit）、ビジネスプラン・コンテスト（SUCSUC DETECT2026）を掲載。発ベンチャー規程第3条・第13条で認定の審議と事務も同センターが担う。インキュベータ概要ページでは本学教員・OBによる経営技術支援、URA等による事業計画作成支援、市場開拓・販路拡大・補助金申請支援を挙げる。', 'official', 'https://www.omu.ac.jp/startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_coi_sidejob', 'established', '兼業規程と利益相反マネジメント規程の手続完了が認定条件', '発ベンチャー規程第4条第4号で、教職員が起業したものは「公立大学法人大阪教職員兼業規程」「大阪公立大学及び大阪公立大学工業高等専門学校教職員等の利益相反マネジメント規程」その他関係規則に定める所要の手続・許可が適正になされていることを申請条件とする。認定事前チェックシート(4-1)は、ベンチャー企業の役員・発起人・株主となる場合の兼業申請と利益相反自己申告書の提出完了を確認。利益相反規程第3条第1項第3号は株式・出資金・新株予約権等の個人的経済的利益を管理対象とし、第4条で利益相反マネジメント委員会を設置、第7条で自己申告義務を課す。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'attr_support_fee', 'established', '認定・便宜措置は無償、施設利用料は有償で認定企業は減免', '発ベンチャー規程には認定料・称号使用料の定めがなく、第8条の便宜措置（インキュベータ入居中の登記面住所、イベント・ホームページでの事業紹介、ライセンス対価の新株予約権化）にも対価の定めはない。一方インキュベータ規程第8条で入居者は利用料を納付し、利用細則第6条が部屋区分別の月額利用料と延滞損害金を定める。利用細則第7条は大阪公立大学発ベンチャーに認定された企業を利用料減免の対象とし、適用月から12か月間の減免を定める。共用研究機器センターは学外利用区分の料金が発生する。', 'official', 'https://www.omu.ac.jp/assets/incubatoruse.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'attr_certified_count', 'unknown', null, '［自動検証で否認: 実際51社(生HTML機械集計)、主張の44社と不一致］元の主張(established): 44社、大学公式ページで企業一覧を公開。産学官連携の成果等「大学発ベンチャー」ページに大学発ベンチャー企業一覧が掲載され、掲載企業は合計44社（2026年9月10日確認）。同ページに大阪公立大学発ベンチャー企業取扱規程のPDF、大学発ベンチャー企業認定事前チェックシート、申請様式一式が掲示されている。機関自身の公開情報のみを根拠とし、外部統計は用いていない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_cert_rule', 'established', '「電気通信大学発ベンチャー認定規程」に基づく称号認定', '令和8年6月10日規程第9号「電気通信大学発ベンチャー認定規程」。第1条で本学の研究成果・人的資源等を活用する企業に本学由来を示す称号を認定し育成・自立を支援すると規定。第6条で学長が称号記により「電気通信大学発ベンチャー」の称号を付与。附則3で従前の「電気通信大学発ベンチャー認定に関する申合せ」（平成24年3月27日役員会決定）を廃止。所管は産学官連携センターベンチャー支援部門。なお大学公式ページの関連規程リンクは廃止済み申合せPDFのままで404となる。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'attr_eligible_scope', 'established', '知財活用型・研究成果活用型・在籍者/退職1年以内・兼業型', '認定規程第2条第1項(1)〜(6)。①本学又は役職員が保有する知的財産権に係る技術に基づく起業②本学で達成された研究成果・習得した技術等に基づく起業③役職員又は学生が設立者となるか設立に実質的に関与した起業④退職・学籍喪失後に常勤の職に就かずに起業、又は退職等から1年以内に設立⑤役職員が役員・顧問等として兼業し企業と共同で事業化⑥産学官連携センター長が認めたもの。特定非営利活動法人も対象に含む。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'attr_recognition_decider', 'established', '学長（大学発ベンチャー認定審査委員会の審議を経て決定）', '認定規程第5条。申請者は学長に申請し、学長が大学発ベンチャー認定審査委員会に附議、委員会の審議結果の報告を踏まえ学長が認定の可否を決定し文書で通知。審査委員会は産学官連携センターに置き（第4条）、産学官連携センター長（委員長）、輸出管理マネージャー、ベンチャー支援部門長、知的財産部門長、学術国際部長ほかで構成。認定の取消し（第11条）も同じ手続を準用。事務は学術国際部研究推進課（第14条）。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_cert_pre_registration', 'established', '未設立でも認定対象（プレインキュベーション使用者に限る）', '認定規程第2条第2項。インキュベーション施設のプレインキュベーションルームを使用している役職員又は学生が企業の設立を予定し、当該企業のベンチャー育成支援ルームへの入居を希望する場合は、当該企業が未設立であっても認定の対象とすることができる。インキュベーション施設管理運営細則第6条第1項も使用資格区分Bに「準備段階の企業を含む」と明記。条件付認定や認定予定通知という別枠の手続は定められていない。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'attr_validity_years', 'established', '5年間・更新可（再申請により通算最長10年）', '認定規程第6条第2項。称号は第5条第4項の認定決定日から5年間使用可、再申請を妨げず通算最長10年まで使用可。更新希望者は期間終了の3か月前までに認定更新申請書を学長へ提出し、審査手続は第5条第2項〜第4項を準用（第6条第3項）。附則2の経過措置で、施行日（令和8年6月10日）に現に認定されている企業の使用期間は施行日から3年間又は従前の認定日起算の期間のいずれか遅い日まで。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_head_office_registration', 'established', '可（貸与したインキュベーション施設の住所で商業登記）', '認定規程第13条第2号が、第1号により貸与したインキュベーション施設等について当該大学発ベンチャーの所在地としての商業登記を認めると明記。大学公式「インキュベーション施設」ページも、使用者は届出により「〒182-8585 東京都調布市調布ケ丘一丁目5番地1 国立大学法人電気通信大学内」を登記に使用できると記載。登記自体に別途の対価を課す定めは無く、施設の使用料負担が前提となる。', 'official', 'https://www.uec.ac.jp/research/venture/incubation.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_facility_lease', 'established', 'インキュベーション施設を有償貸与（認定企業は最長6年）', '西11号館（イノベーティブ研究棟）内のインキュベーション施設。電気通信大学インキュベーション施設管理運営細則第4条でベンチャー育成支援ルーム、プレインキュベーションルーム、コワーキングルーム、サーバールーム、会議室を設置。使用資格は区分A（教職員等で起業を目指す者）と区分B（認定を受けた電通大発ベンチャー）。ベンチャー育成支援ルームは1年以内、区分Bは審査により原則最長6年まで更新可（第7条）。使用可否は産学官連携センター運営委員会の議を経て管理責任者が決定（第9条）。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2010C028.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_shared_equipment', 'established', '研究設備センターの依頼測定・機器使用を有償利用（一般区分）', '「電気通信大学研究設備センターにおける外部からの依頼測定等の実施に関する規程」（平成24年12月18日、令和2年12月25日最終改正）。民間機関等は依頼測定（本学担当者が実施）と機器使用（本学担当者の指導・立会いの下で実施）を申込み可（第2条・第5条）。料金は別表第2・第3で機器ごとに定め前納が原則（第4条・第8条）。認定ベンチャー専用の料金区分や減免は無く民間機関等と同一扱い。認定規程第13条の支援列挙にも設備利用は含まれない。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2012B115.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_name_logo_use', 'established', '称号は認定期間中使用可・校章は学長許可制', '認定規程第6条で学長が称号記により「電気通信大学発ベンチャー」の称号を付与し、認定期間中の使用を認める。第11条第3項は取消時に称号記を返還し、以後は認定を受けていた事実を事業活動で使用してはならないと定める。校章は「国立大学法人電気通信大学校章使用細則」（平成22年11月24日、平成31年3月28日改正）が使用者を本学・学長指定団体・学長許可団体に限定（第2条）、営利目的の使用は別記様式で事前申請し学長が審査（第4条第2項・第5条）。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2010C024.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_ip_license', 'established', 'ライセンス対価の現金支払を株式等取得で免除・軽減可', '「国立大学法人電気通信大学におけるライセンス等の対価として取得する株式等取扱要項」（令和6年6月21日要項第3号）第3条。相手方が電通大発ベンチャーであり、審査を経て現金の支払を免除又は軽減することが経営の加速のために特に必要と学長が認めた場合に限り、対価を株式・新株予約権で取得できる。産学官連携センター長が財務状況等を審査し学長へ報告（第4条）。独占的実施許諾や実施料率の優遇規定は職務発明等に関する規程を含め確認できない。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2024D003.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_equity_rule', 'established', '株式・新株予約権の取得と管理を定める規程あり', '「国立大学法人電気通信大学株式等管理規程」（令和6年6月21日規程第11号、令和7年2月21日改正）。寄附又はライセンス等の対価として取得した株式・新株予約権を財務責任者が管理責任者として管理（第1条・第2条）。上場後は可能な限り速やかに売却が原則（第3条）、新株予約権は売却可能となり次第行使（第6条）、発行会社に対する経営参加権等の共益権は原則不行使（第8条）。取得の入口はライセンス等の対価として取得する株式等取扱要項が定める。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2024B011.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_gap_fund', 'established', 'GTIEのスタートアップ創出共同機関としてGAPファンド参画', '首都圏プラットフォームGTIE（Greater Tokyo Innovation Ecosystem、共同主幹機関は東京大学・東京科学大学・早稲田大学）の公式サイトで、電気通信大学が「スタートアップ創出共同機関」として参画機関に掲載されている。GTIEはGTIE GAPファンドプログラムを運営。一方、学内独自のGAPファンド・起業準備資金・POC資金については、大学規程集および産学官連携センター・ベンチャー支援の各公式ページで根拠規程を確認できなかった。［検証エージェントは出典を開けず未照合］', 'official', 'https://gtie.jp/about/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_accelerator', 'unknown', null, '［自動検証で否認: 第13条は相談紹介広報のみ規定、起業科目とPoCの記載無し］元の主張(established): 起業相談・企業紹介・広報を規程化、起業科目とPoCコンテスト。認定規程第13条第3〜5号が、役職員による起業及び起業後の経営等に関する相談業務への対応、他企業への紹介・仲介、本学主催イベントや広報誌・ホームページでの広報を支援として明記。窓口は産学官連携センターベンチャー支援部門（産学官連携センター規程第3条第3号・第7条）。大学公式ページによればインキュベーション施設にインキュベーションマネジメント担当教員を配置し、授業科目「ベンチャービジネス概論」「ベンチャービジネス特論」とU☆PoC（UECアイディア実証コンテスト）を実施。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_coi_sidejob', 'established', '職員兼業規程と利益相反マネジメントの手続履行が認定要件', '認定規程第3条第5号が、本学役職員について国立大学法人電気通信大学職員兼業規程（平成16年規程第30号）及び国立大学法人電気通信大学産学連携利益相反マネジメントポリシー（平成17年2月9日）等に基づく手続・許可の適正な履行を認定要件とする。兼業規程第4条第2項・第9条は研究成果活用企業の役員等兼業を学長許可制とし、期限付き許可と終了後2年間の利害関係業務からの排除を定める。利益相反マネジメント委員会規程第2条が自己申告とモニタリングの審査を所掌。株式保有自体の許可規定は兼業規程に無い。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'attr_support_fee', 'established', '施設利用は有償（段階制月額）、相談・紹介・広報は対価の定め無し', '「電気通信大学インキュベーション施設使用料等徴収要項」（平成23年1月18日制定、令和6年7月1日最終改正）。ベンチャー育成支援ルームは使用資格区分と入居時からの経過年数に応じた面積あたり月額単価で、経過年数が進むほど単価が上がる段階制（第2条・別表）。プレインキュベーションルーム、コワーキングルーム、サーバールームも月額有償、会議室は無料（第3〜6条）。光熱水料・通信費等は実費相当額を別途負担（第7条）。認定規程第13条の相談・紹介・広報には対価の定めが無い。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2010D020.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'attr_certified_count', 'unknown', null, '［自動検証で否認: list.htmlは45社のみ掲載、年度別61社の記載は同ページに無い］元の主張(established): 一覧45社を公開（令和8年7月現在）、年度別累計は61社。大学公式「電気通信大学発ベンチャー一覧」が令和8（2026）年7月現在45社を企業名・認定年度付きで公開。「電気通信大学発ベンチャー認定」ページは平成19（2007）年度から令和8（2026）年度までの年度別認定数を掲載し、合計は61社（平成25年度と令和3年度は認定なし）。認定・辞退・取消しがあったときは本学ホームページへの掲載等により公表する（認定規程第12条）。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_cert_rule', 'established', '大学発ベンチャーの認定に関する規程／称号「豊橋技術科学大学発ベンチャー」', '国立大学法人豊橋技術科学大学における大学発ベンチャーの認定に関する規程（令和元（2019）年6月19日規程第7号）。第1条で大学発ベンチャーの円滑かつ適正な支援を目的とし、第6条第1項で学長が称号記（別記様式2）により「豊橋技術科学大学発ベンチャー」の称号を授与する。第7条で認定及び称号授与は大学に法的責任を生じさせないと明記。大学規程集第8章「学術・研究」に全文掲載。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'attr_eligible_scope', 'established', '知財活用・研究成果活用型と職員・学生（退職卒業から1年以内）の起業', '認定規程第2条。大学の研究成果の事業化を主目的とし、(1)本法人に帰属する知的財産権をもとに起業、(2)それ以外で本法人において達成された研究成果又は習得した技術に基づく起業、(3)本法人の職員又は学生（過去に職員又は学生であった者を含む）が設立者となる又は設立に深く関与、(4)その他学長が特に必要と認めたもの、のいずれかに該当すること。(3)の退職・卒業者は設立まで他の職に就かないか、退職・卒業から起業までが1年以内に限られる。第3条で公序良俗、名誉毀損のおそれがないこと、兼業・利益相反手続の履行も要件とする。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'attr_recognition_decider', 'established', '学長（大学発ベンチャー認定委員会及び戦略企画会議の議を経る）', '認定規程第5条。申請者は大学発ベンチャー認定申請書（別記様式1）に必要書類を添えて学長に提出し、第2項で学長が大学発ベンチャー認定委員会及び戦略企画会議の議を経て認定を決定、第3項で文書により通知する。第4条で認定委員会を設置。大学発ベンチャー認定委員会細則（令和元（2019）年6月19日細則第3号）第2条で認定・取消・支援事業・事業報告書の確認を審議し学長へ答申、第3条で研究推進アドミニストレーションセンター長を委員長とする。事務は同センターの協力を得て研究推進課が行う（第12条）。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/561.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_cert_pre_registration', 'unknown', null, '認定規程第2条は大学発ベンチャーを各号とも「起業したもの」と定義し、第5条の認定手続にも設立登記前の申請、認定予定通知、条件付認定に関する条文はない。禁止する条文もないため、公開規程からは可否を判断できない。第2条第4号に「その他学長が特に必要と認めたもの」の受け皿がある。なおイノベーション施設規程第7条第5号は「1年以内に創業を行おうとする個人で、その準備活動を行う者」を使用資格に含めるが、これは施設使用であって認定ではない。', 'unknown', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'attr_validity_years', 'established', '3年・再申請可', '認定規程第6条第2項。「豊橋技術科学大学発ベンチャー」の称号は3年間使用することができ、ただし再申請することを妨げないと定める。第8条で年度毎に自社の決算日から3か月以内に事業報告書及び収支決算書を学長へ提出する義務、第9条で代表者の申出による認定解除と称号の返付、第10条で学長が認定委員会の議を経て認定及び称号授与を取り消せること（社会的信用の失墜、事業報告書等の未提出等）を規定。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_head_office_registration', 'established', 'イノベーション施設を本店所在地とする商業登記の許可', '認定規程第11条第1項第2号に「貸与した国立大学法人豊橋技術科学大学イノベーション施設等について、大学発ベンチャーの所在地とする商業登記を認めること」と明記。同項第1号の施設貸与とセットで、貸与を受けた区画が対象となる。支援は認定委員会が本法人の管理運営及び教育研究に支障がないと認める範囲で行い、認定通知書（別記様式5）により通知される。施設自体はイノベーション施設使用細則第5条により有償。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_facility_lease', 'established', 'イノベーション施設を学内料金で貸与、原則3年（2年延長可）', '認定規程第11条第1項第1号で事務室又は研究室として「国立大学法人豊橋技術科学大学イノベーション施設等を学内料金で貸与すること」。施設側はイノベーション施設規程（令和2（2020）年3月19日規程第43号）第2条でインキュベーションスペースとオープンラボスペースを置き、第7条で創業後5年以内の個人・中小企業者、1年以内に創業しようとする個人等を使用資格とする。第11条で使用期間は原則3年以内、施設長が特に必要と認めた場合は1年を単位に2年を限度として延長可。使用可否は第10条の審査会が審議。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/690.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_shared_equipment', 'established', '本学所有の研究設備等を学内料金で使用可', '認定規程第11条第1項第3号「本法人の所有する研究設備等を学内料金で使用させること」。学外者一般の機器利用は別に「国立大学法人豊橋技術科学大学における学内共同利用機器に係る学外者の研究設備・機器共同利用等に関する取扱要領」（平成18年3月22日制定）があり、第2条で学長へ共同利用等申込書を提出、第4条で財産使用責任者と協議のうえ許可書を交付、第6条で料金は別に定めるとし学長が必要と認めた場合は収納しないことができる。認定大学発ベンチャーには学内料金区分が適用される。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/309.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_name_logo_use', 'established', '称号は3年間使用可、コミュニケーションマークは学長許可制', '称号は認定規程第6条で称号記により授与され、第2項で3年間使用可。第10条第3項により取消しを受けた者は速やかに称号記を返付し、以後は認定を受けていた事実を事業において使用してはならない。ロゴはコミュニケーションマーク取扱要領（平成21年9月15日学長裁定）が定め、第3条で使用範囲を本学業務の名刺・印刷物・行事・関連団体の物品等に限定列挙、第4条で事前に学長へ申請し許可を得ることを要する（役員・教職員が第3条第1号から第5号の範囲で使う場合は不要）。認定ベンチャーへの許諾は同条第6号の学長判断による。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/574.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_ip_license', 'established', 'ライセンス等の対価の全部又は一部を新株予約権化可', '認定規程第11条第1項第7号「知的財産権のライセンス等の対価の全部又は一部を新株予約権とすること」。ベンチャー企業支援を目的とした新株予約権の取得等に関する規程（令和4（2022）年5月11日規程第2号）第3条も同旨。知的財産ポリシー（令和7（2025）年7月16日戦略企画会議）6項(3)で知的財産権に基づく大学発ベンチャーの育成推進と事業化支援を掲げる。認定ベンチャーに独占的実施許諾や実施料の減免を与える条文は公開規程に見当たらない。共同研究相手方への優先的実施は共同研究取扱規程第15条に別途規定。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/776.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_equity_rule', 'established', '新株予約権の取得等・管理の2規程あり', 'ベンチャー企業支援を目的とした新株予約権の取得等に関する規程（令和4（2022）年5月11日規程第2号）第3条で、知的財産権のライセンス等及びその他の支援業務の対価として新株予約権を取得できる。第4条で新株予約権取得等審査会を設置、第5条で学長が諮問し事業計画・財務内容・経営体制・資金計画・利益相反等と発行価額が無償であること等の経済条件を審議、第6条で学長が取得を決定し契約を締結。取得後は「取得した新株予約権の管理に関する規程」（同日規程第3号）が管理責任者を財務担当理事とし、第7条で議決権は原則不行使と定める。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/776.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_gap_fund', 'established', '東海地区TongaliのGAPファンド対象機関', '東海地区の起業家育成・起業支援プログラムTongaliのGAPファンドプログラム募集ページで、豊橋技術科学大学が対象16機関の一つとして明記されている。対象は参画機関の教職員及び修士・博士学生（学生は指導教員との共同申請）で、創薬・医療とものづくり／ディープテックの区分がある。実施の中心は名古屋大学。学内単独のGAPファンドや起業準備資金の規程は大学規程集では確認できず、認定規程第11条の支援メニュー8項目にも資金の供与は含まれていない。', 'official', 'https://tongali.net/x/gapfund2026-step1/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_accelerator', 'established', '起業・経営相談と他企業紹介を規程で制度化', '認定規程第11条第1項で、第4号「本法人に所属する職員又は学生が大学発ベンチャーの起業及び起業後の経営等に関する相談業務に対応すること」、第5号「本法人に所属する職員又は学生による他企業への紹介又は仲介」、第6号「本法人が主催又は参加するイベント、本法人の広報誌又はホームページ等における広報」を支援メニューとして規定。支援は認定委員会が管理運営及び教育研究に支障がないと認める範囲で行い認定通知書で通知。事務は研究推進アドミニストレーションセンターの協力を得て研究推進課が担当（第12条）。東海地区のTongaliにも参画。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_coi_sidejob', 'unknown', null, '［自動検証で否認: 301条第7条は組織規定。審査勧告は第11条の誤citation］元の主張(established): 役員兼業は学長許可制、利益相反審査会と認定要件で接続。役職員の兼業に関する規程（平成16年度規程第39号）第4条は営利企業の役員等兼業を原則不許可としつつ、技術移転事業者と研究成果活用企業の役員等は第5条・第11条により事前の学長許可で可能とし、第7条・第13条に許可基準、第8条に年1回の報告義務、第10条に終了後2年間の業務制限を置く。認定規程第3条第4号は、申請者が本法人職員の場合に同規程及び利益相反マネジメント規程（平成16年度規程第123号）等に定める手続・許可が適正になされていることを認定要件とする。利益相反マネジメント規程第3条は兼業と株式等の経済的利益を管理対象とし、第7条の利益相反審査会が審査・勧告する。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'attr_support_fee', 'established', '学内料金による有償（施設使用料・設備使用料）', '認定規程第11条第1項は施設貸与も研究設備使用もいずれも「学内料金で」と定め、無償とはしていない。イノベーション施設使用細則（令和2（2020）年3月19日細則第13号）第5条で施設使用料及び光熱水料等を1平方メートル当たりの基準額に研究室・実験室の面積を乗じて算定し、基準額は別表1にインキュベーションスペース／オープンラボスペースと教育職員／それ以外の区分で定める。同細則により施設使用料には光熱水料とネットワーク料を含む。知的財産権のライセンス等の対価は認定規程第11条第1項第7号により新株予約権とすることができる。相談業務・紹介仲介・広報の対価に関する定めはない。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/691.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'attr_certified_count', 'established', '6社・大学公式ページで一覧公開', '大学公式サイト「豊橋技術科学大学認定大学発ベンチャー」ページ（研究・産学官・社会連携＞産学官連携・共同研究）に、PLANT DATA株式会社、株式会社パワーウェーブ、株式会社豊橋バイオマスソリューションズ、株式会社OptTech、合同会社サイナルジ、PLANT CASE株式会社の6社を掲載。ページの表示は初版作成2022年7月14日、最終改訂2024年7月19日。各社の認定日、称号の有効期限、認定制度の説明はこのページには記載がない。', 'official', 'https://www.tut.ac.jp/develop/collaboration/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_cert_rule', 'established', '横浜国立大学発ベンチャー称号授与規則に基づく称号制度', '「国立大学法人横浜国立大学発ベンチャー称号授与規則」（令和3年3月17日規則第26号、令和5年3月22日規則第38号改正、令和3年4月1日施行）が根拠。第1条で研究成果又は人的資源を活用して起業されたベンチャー企業への称号授与を定める。第3条で称号は「横浜国立大学発ベンチャー」、第2条第1項第3号のみ該当時は「横浜国立大学発学生ベンチャー」の2種。第8条で授与・取消しをホームページ等で公表。第11条で事務は研究・学術情報部産学・地域連携課。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'attr_eligible_scope', 'established', '知財活用型・教職員／卒業生（3年以内）・在学生の3類型', '称号授与規則第2条第1項。前提は「新たな技術又はビジネス手法を基に起業した企業」。第1号＝職務発明規則第2条第3項の知的財産権又は研究成果有体物取扱規則第2条第1項の研究成果有体物で大学が承継・帰属するものを活用。第2号＝本学の役員若しくは教職員（過去に役員・教職員であった者を含む）又は過去に本学の学生であった者が発起人又は起業時の中心的役割で、退職又は卒業・修了後3年以内。第3号＝本学の学生。同条第2項で学長が特に認めた企業も申請可。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'attr_recognition_decider', 'established', '学長（研究推進機構運営会議の審議を経て決定）', '称号授与規則第4条。第1項で申請者は様式第1号（学生ベンチャーは様式第2号）により学長へ申請。第2項で学長は国立大学法人横浜国立大学研究推進機構運営会議に付議。第3項で同運営会議が申請内容を審議し結果を学長へ報告。第4項で学長が報告を踏まえ認定又は不認定を決定し、文書により申請者へ通知。第5条4項により更新申請の審査も第4条第2項から第4項を準用する。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_cert_pre_registration', 'not_started', '設立済み企業のみ申請可、登記前の条件付認定なし', '称号授与規則第2条第1項は申請資格を「起業した企業」に限定列挙し、設立登記前の申請・認定予定通知・条件付認定の定めは規則本文に無い。第5条第1項の称号授与も称号記の交付をもって行うとされ、設立前の予定通知の規定は無い。附則第2項は本学施設を借用する企業に本学所在地の商業登記を認める経過措置だが、認定ベンチャーでない場合は6か月以内に第4条第1項の申請を行うとされ、既存法人を前提とする。なお産学官連携研究施設使用規則第3条第6号は起業を予定する教職員の施設使用を認めるが、称号認定とは別制度。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'attr_validity_years', 'established', '授与日から5年後の年度末まで、更新可（学生は在学期間）', '称号授与規則第5条。第2項で横浜国立大学発ベンチャーの称号授与期間は授与した日から5年後の年度末までとし更新可能、更新時は第2条第1項第2号ただし書き（退職・卒業後3年以内）を適用しない。第3項で学生ベンチャーは発起人又は中心的役割を担う学生の在学期間とし、在学期間を延長した場合はその範囲で更新可。第4項で更新は期間終了の1か月前までに様式第5号により学長へ申請。第7条に取消し事由、第6条に毎年度決算日から3月以内の事業報告書等提出義務。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_head_office_registration', 'established', '大学施設を所在地とする商業登記可、施設使用料は有償', '称号授与規則第10条第3号「本学の施設において、当該認定ベンチャーの所在地とする商業登記を認めること」。同号で本学施設退去時に登記場所を変更したことを示す書面の提出を義務づける。附則第2項は当分の間、第10条第3号にかかわらず本学施設を借用する企業に本学を所在地とする商業登記を認め、認定ベンチャーでない場合は6か月以内に称号申請を行うことを求める。商業登記自体の対価規定は無いが、前提となる施設使用は産学官連携研究施設使用規則第9条により有償。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_facility_lease', 'established', '共同研究推進センター棟・総合研究棟E棟を有償貸与、起業後5年以内', '産学官連携研究施設使用規則（平成24年12月20日規則第134号、令和7年3月28日規則第44号改正）。第3条第6号で本学シーズを生かしたベンチャー企業の起業を予定している教職員、第7号で本学シーズを基に設立した起業後5年以内のベンチャー企業の起業者に申請資格。対象は共同研究推進センター棟実験室、総合研究棟E棟プロジェクト室（研究室・実験室・事務室・ワーキングスペース）。第4条で使用期間は1年以内かつ年度末まで、更新は2回まで（機構長が特別の事由を認めた場合4回まで）。第6条・第7条で産学官連携研究施設使用審査委員会の議を経て機構長が承認。第9条により有償（専有面積あたり月額単価、使用年数で区分）。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2025/04/産学官連携研究施設使用規則R7.3.27（様式あり）.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_shared_equipment', 'unknown', null, '［自動検証で否認: 第15条に料金3区分の規定なし、note内の捏造］元の主張(established): 機器分析評価センターを学外企業区分で利用可、専用料金なし。称号授与規則第10条第2号で「本学の産学官連携研究施設又は本学の研究用機器等の貸付に配慮すること」を支援に明記。実際の利用は研究推進機構機器分析評価センター利用細則（平成19年6月29日規則第106号、令和6年3月1日規則第17号改正）第4条により、本学と共同研究・受託研究等の契約を締結している学外の者、又は機器利用の約款に同意若しくは個別に契約した学外の者が利用可。第6条で利用責任者が申請書をセンター長へ提出し承認を得る。第15条で費用負担を規定。料金区分は学内（原則無料）、学外・大学等研究機関向け、学外・企業その他向けの3区分で、認定ベンチャー専用区分は公開ページに無い。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_name_logo_use', 'established', '称号使用可、認定ベンチャーロゴマーク（シンボルマーク）提供', '称号授与規則第3条で「横浜国立大学発ベンチャー」又は「横浜国立大学発学生ベンチャー」の称号を授与し、第5条第1項で称号記（様式第3号・第4号）の交付をもって授与する。第10条第1号で支援として「認定ベンチャーロゴマークの使用を認めること」を明記。研究推進機構の公式ページも支援メニューとして「ベンチャーシンボルマーク提供」を挙げる。第7条第2項で取消しを受けた企業は速やかに称号記を返付し、取消日以後は称号を使用してはならない。第9条で大学は認定ベンチャーの製品・サービスの内容及び品質を保証しない旨の免責を規定。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_ip_license', 'established', '知財・研究成果の専用実施等に配慮、対価の株式等代替可', '称号授与規則第10条第4号「本学が所有する知的財産権又は研究成果等の使用に配慮すること」。研究推進機構の公式ページは支援内容を「大学所有の知的財産・研究成果物等の専用実施等への支援」と記載し、専用実施権の設定を含む。加えて認定ベンチャー株式等取扱規則第2条第3号で知的財産権の譲渡・実施権設定・実施許諾・使用許諾、研究成果有体物の提供・使用許諾を「収益を伴う事業」と定義し、第3条で認定ベンチャーが現金を保有しない場合等にその対価を株式等で収納できるとする。実施料の減免率など料率の公開規定は確認できない。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_equity_rule', 'established', '株式等取扱規則で認定ベンチャーの株式・新株予約権を取得可', '「国立大学法人横浜国立大学における認定ベンチャーを対象とした収益を伴う事業の対価として取得する株式等取扱規則」（令和3年3月17日規則第27号、令和3年4月1日施行）。第2条第4号で株式等＝株式及び新株予約権。第3条で対価相当の現金を保有しない、資金繰りに窮する、経営に重要な影響を及ぼす等の場合に対価を株式等で収納可。第4条で申請者が別記様式第1号により学長へ申請、研究推進機構運営会議が経理責任者の承認を得て審議し学長が決定。第6条で新株予約権の行使は同運営会議の審議を経る。第7条第2項で議決権等の経営参加権は原則不行使。第8条で公開株は取得後速やかに、未公開株は公開後速やかに売却。第9条でインサイダー取引管理責任者を置く。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学における認定ベンチャーを対象とした収益を伴う事業の対価として取得する株式等取扱規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_gap_fund', 'established', '成長戦略教育研究センターのフェーズⅠ・Ⅱ活動経費支援', '成長戦略教育研究センターの「大学発ベンチャー育成・支援」制度。2005年開始のポスドクアントレプレナー支援制度を基盤に、2013年から起業へ向けた2段階の支援へ移行。フェーズⅠは学部学生から博士課程後期学生・ポストドクターを対象に、事業化に必要な要素技術の明確化と実現可能な事業計画の策定を支援し活動経費を給付。フェーズⅡは法人設立を計画中の大学院生・ポストドクター・本学教員を対象に、事業計画の実行フォロー、外部とのアライアンス探索、法人設立計画を支援し活動経費を給付。ビジネスプランは公募・審査による選定。', 'official', 'https://www.cseg.ynu.ac.jp/vb/support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_accelerator', 'established', 'フェーズⅠ・Ⅱの伴走指導と産学官連携ワンストップ相談窓口', '成長戦略教育研究センターがビジネスプランを公募・審査のうえ、対象者に当該ビジネスプラン開発を指導する段階的支援（フェーズⅠ・Ⅱ）を実施。同センターはJST／SCORE「よこはまプラットフォーム」関連講座、YOXOアントレプレナー育成プログラム（神奈川大学・関東学院大学・横浜市立大学との連携）、YOXOカレッジ等の起業教育を運営し、ベンチャービジネス支援窓口で学生の相談に対応。研究推進機構は産学官連携ワンストップサービスを掲げ、産学官連携コーディネーターが技術相談をはじめ各種相談に応じる。', 'official', 'https://www.cseg.ynu.ac.jp/category/vb/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_coi_sidejob', 'established', '研究成果活用企業の役員・発起人兼業を学長承認、COI自己申告', '教職員兼業規則（平成16年4月1日規則第106号、令和8年3月26日規則第28号改正）。第8条・第9条で営利企業の役員等兼業は原則不可としつつ、技術移転事業者役員、研究成果活用企業役員、監査役・社外取締役等を例外とする。第15条から第22条で研究成果活用企業の役員兼業を学長承認制とし、第21条・第22条で発起人兼業も認める。第19条で兼業終了後2年間の関連業務制限。第33条で職務外兼業は週20時間まで。利益相反マネジメント規則（平成23年1月20日規則第2号、令和5年3月30日規則第49号改正）第2条第3号は兼業報酬・特許収入・未公開株式の保有を利益相反として例示し、第4号で企業等に大学発ベンチャー企業を含むと明記。第11条で自己申告義務、第18条で利益相反アドバイザーを置く。', 'official', 'https://somu-somu.ynu.ac.jp/gakugai/kisoku/act/frame/frame110000076.htm', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'attr_support_fee', 'established', '称号・ロゴは無償、施設使用料と機器利用料は有償', '称号授与規則第10条の支援のうち、ロゴマーク使用（第1号）、商業登記の受入れ（第3号）、知的財産権・研究成果等の使用への配慮（第4号）には対価規定が無い。一方、産学官連携研究施設使用規則第9条第1項は使用が承認された研究代表者等に使用料の支払いを義務づけ、同条第2項で光熱水料及び実験室等にかかる経費も負担させる。徴収方法は産学官連携研究施設使用料等徴収方法等及び使用上の義務等に関する要項（平成27年9月30日研究推進機構長裁定）第2条・第3条で定め、起業予定教職員・起業後5年以内のベンチャーは分納願の提出により分納可。機器分析評価センターは学外者有償。知的財産の実施許諾等は対価が発生し、株式等取扱規則により株式等での収納が可能。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2025/04/産学官連携研究施設使用規則R7.3.27（様式あり）.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'attr_certified_count', 'established', '2026年7月1日現在19社、企業名と授与期間を一覧公開', '研究推進機構「横浜国立大学発ベンチャー／学生ベンチャー称号授与企業一覧」ページに、2026年7月1日現在で19社（YNU大学発ベンチャー18社、YNU大学発学生ベンチャー1社）と記載。一覧は各社の名称、所在地、称号授与期間を掲載する。称号授与規則第8条で学長は称号の授与又は取消しを行ったときは本学ホームページへの掲載等により公表するものと定めており、この一覧が同条に基づく公表にあたる。同ページには申請様式（様式第1号から第6号）と規則PDFも掲載。', 'official', 'https://www.ripo.ynu.ac.jp/company/sangakukan/ynuventure/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_cert_rule', 'established', '横浜市立大学発認定ベンチャー（研究成果活用型・人材活用型）', '研究ポータル「大学発スタートアップ創出支援」に、称号付与（研究成果活用型／人材活用型の2区分）、本学の商標使用、施設および研究設備の使用、法人登記上の住所使用、知的財産権等の使用に関する優遇措置、ナビゲーションセミナー、GAPファンド申請支援を支援内容として明記。根拠規程名は「公立大学法人横浜市立大学発ベンチャーの支援に関する規程」で、利益相反マネジメント規程第3条第4号が同規程第2条（対象企業等）・第4条（本学の支援）を引用している。規程本文は学内専用サイト掲載で外部からは閲覧不可（403）。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'attr_eligible_scope', 'established', '教職員・学生等、退職卒業修了後3年以内の者', '同ページ「※称号」欄。研究成果活用型は、本学で達成された研究成果（知的財産権含む）又は習得した技術等に基づくもの、本学の教職員等又は学生等が所有する知的財産権をもとに設立又はその設立に深く関与するもの。人材活用型は、教職員又は学生等が設立に深く関与し、本学の講義・実習・課外活動・大学環境から得た経験や発想を契機に起業したもの（教職員等は兼業規程で許可された内容であること）、及び教職員等・学生等であった者が退職・卒業・修了後原則3年以内に設立者となる又は設立に深く関与するもの。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'attr_recognition_decider', 'unknown', null, '認定の決裁者・審査主体を明記した公開資料は確認できなかった。所管組織は横浜市立大学研究・産学連携推進センター設置規程（平成31年4月1日制定）第2条第7号「アントレプレナーシップ教育及び大学発スタートアップ創出に関すること」と第4条第7号「スタートアップ推進部門」（いずれも令和7年8月1日から適用）。同規程第7条のセンター会議の協議事項は部門間調整・特任教員等の受入・客員教員の称号付与で、ベンチャー認定の審査は書かれていない。申請手続は学内専用サイトに限定。', 'unknown', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/opilab/gjok7g0000001o94-att/a1776317284082.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_cert_pre_registration', 'unknown', null, '設立登記前の申請受付、認定予定通知、条件付認定の可否を示す記載は、研究ポータルの大学発スタートアップ創出支援ページにも、公開されている関連規程（利益相反マネジメント規程、研究・産学連携推進センター設置規程、土地・建物長期貸付要領）にも見当たらない。認定申請の手続は学内専用サイトに掲載され、外部から閲覧できない。', 'unknown', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'attr_validity_years', 'unknown', null, '認定称号の有効期間・更新可否を定めた公開記載は確認できなかった。研究ポータルの支援ページ注記に「称号付与以外の支援については、支援期間中に限ります」とあり、支援メニューに期間の限定があることは読み取れるが、支援期間の長さも称号自体の有効期間・更新手続も公開されていない。認定企業一覧は「支援開始年月」のみを掲載し、終期を示していない。', 'unknown', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_head_office_registration', 'established', '法人登記上の住所使用可（有償）', '研究ポータルの大学発スタートアップ創出支援ページ本文に、支援の具体例として「法人登記上の住所使用」を明記。同ページ注記で、優遇措置は利益相反等の観点から無償ではなく一定程度の費用を徴収すること、称号付与以外の支援は支援期間中に限ることが示されている。受け入れる建物・住所や手数料の細目は学内専用サイト掲載で外部からは確認できない。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_facility_lease', 'established', '居室・研究室の長期貸付、貸付料の優遇措置', '支援内容に「本学土地・建物長期貸付料（居室・研究室長期貸付）の優遇措置」を明記。根拠は公立大学法人横浜市立大学土地・建物長期貸付要領（平成17年4月1日制定、平成28年4月1日最近改正）で、第2条により1月以上を長期と定義、第8条第1項で貸付は有償、第10条第2項第9号で理事長が特に必要と認める場合は2分の1を限度に減額、第7条で賃貸借契約は5年以内。福浦キャンパスのオープンイノベーションラボ内産学連携ラボ（12室）は施設利用要領第3条により共同研究法人が入居資格で、認定ベンチャー専用枠の記載はない。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/opilab/gjok7g0000001o94-att/a1754459180825.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_shared_equipment', 'established', '研究設備・研究機器利用の優遇措置', '支援内容に「本学研究設備、研究機器利用の優遇措置」を明記。共用機器は研究・産学連携推進センター設置規程第2条第6号「研究設備・機器の共用に関すること」および第4条第6号のコアファシリティ部門が所管。共用機器の利用ページは学内向け予約システムと大学連携研究設備ネットワークの案内が中心で、機器によって利用料が必要とあるのみであり、認定ベンチャーを含む学外者の料金区分は公開されていない。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_name_logo_use', 'established', '称号付与と本学商標の使用', '研究ポータルの大学発スタートアップ創出支援ページ本文に「横浜市立大学発認定ベンチャーの称号付与、本学の商標使用」と明記。称号は研究成果活用型・人材活用型の2区分で、認定企業一覧にも各社の称号区分が掲載されている。同ページ注記により、称号付与以外の支援は支援期間中に限るとされ、称号自体の使用期間の限定は書かれていない。商標使用の具体的条件（ロゴの様式、表示方法、承認手続）は学内専用サイト掲載で外部からは確認できない。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_ip_license', 'established', '知的財産権・ノウハウ使用の優遇措置', '支援内容に「知的財産権、ノウハウ等の使用に関する優遇措置」を明記。同ページ注記で「知的財産権、ノウハウ等を使用する場合、申請の事前相談時にヒアリングを行い協議します」とされ、個別協議方式である。独占的実施権の付与、実施料の減免、株式による対価の受領といった具体的な優遇条件は公開されていない。研究ポータルの特許・知財ページにも知的財産ポリシーや知的財産取扱規程のPDFは掲載されておらず、発明届出書と特許登録一覧のみが公開されている。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_equity_rule', 'not_started', '出資・新株予約権取得の定めなし', '公立大学法人横浜市立大学定款第22条（業務の範囲）は6号の限定列挙で、大学の設置経営、学生支援、受託・共同研究等の連携活動、公開講座、教育研究成果の普及・活用促進、附帯業務のみを掲げ、研究成果活用事業者への出資を業務としていない。第24条の資本金も横浜市からの出資を定めるにとどまる。研究ポータルの大学発スタートアップ創出支援ページの支援メニューにも、株式・新株予約権の取得は挙げられていない。', 'official', 'https://www.yokohama-cu.ac.jp/univ/corp/teikan/tt534t0000000646-att/teikan250314.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_gap_fund', 'established', 'GAPファンド申請支援（GTIE共同機関）', '支援内容に「GAPファンドの申請支援」を明記。GTIE（Greater Tokyo Innovation Ecosystem）の共同機関として、同ページのニュース欄でGAPファンドエントリーコース第4回採択（2026年1月13日）、GAPファンドエクスプロールコース採択（2025年10月24日）、JST「ディープテック・スタートアップ国際展開プログラム（D-Global）」採択（2026年3月6日）を公表している。学内独自のGAPファンド・起業準備資金・POC資金の制度は公開資料では確認できない。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_accelerator', 'established', '伴走支援・オフィスアワー・客員起業家制度', '支援内容に「外部有識者（市大卒の税理士、ベンチャー支援者等）のご紹介、個別相談の実施」「大学発スタートアップ創出ナビゲーションセミナーの開催」を明記し、2026年4月20日に個別相談の「オフィスアワー」開設を告知。J-PEAKSの記事ではスタートアッププロデューサーが大学発認定ベンチャーの選定、事業計画の作成、GAPファンドの獲得、法人設立までの伴走支援を担うと説明。客員起業家（EIR）は雇用契約でなく業務委嘱、基本契約期間約6か月で、2026年8月19日に募集終了。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_coi_sidejob', 'established', '利益相反規程が支援対象を明記、兼業は許可制', '公立大学法人横浜市立大学利益相反マネジメント規程（平成19年6月1日制定規程第151号、令和3年10月1日最近改正）第3条第4号が、マネジメント対象として「公立大学法人横浜市立大学発ベンチャーの支援に関する規程第2条に規定する企業等が、同規程第4条に定める本学の支援を得る場合」を明記。適用範囲は役員・常勤教職員等（第2条）、第8条で事例発生前の申出、第9条で回避要請等の指導を定める。人材活用型の認定要件にも「教職員等は兼業規程にて許可された内容であること」とあり兼業は許可制。兼業規程本文は非公開で、申請様式のみ公開。', 'official', 'https://www.yokohama-cu.ac.jp/amedrc/ethics/conflict/ng5j70000000012t-att/riekisouhan-manejimennto-kitei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'attr_support_fee', 'established', '称号付与以外は有償（一定程度の費用）', '研究ポータルの大学発スタートアップ創出支援ページ注記に「優遇措置については利益相反等の観点から、無償ではなく一定程度の費用を頂戴します」「称号付与以外の支援については、支援期間中に限ります」と明記。施設側も土地・建物長期貸付要領第8条第1項で貸付は有償が原則、第12条で光熱水費・共益費を含む維持管理経費はすべて使用者負担と定めている。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'attr_certified_count', 'established', '18社（企業名・事業内容・支援開始年月を公開）', '研究ポータルの大学発スタートアップ創出支援ページ「本学発・認定企業一覧」に、2026年9月10日時点で18社を掲載。各社の企業名、事業内容、支援開始年月、称号区分を公開している。内訳は研究成果活用型15社、人材活用型3社。支援開始年月は2016年8月から2026年8月まで分布し、2022年以降の認定が大半を占める。なお同大学のJ-PEAKS記事（2026年4月13日）は当時の認定数を16社と記している。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_cert_rule', 'established', '称号「会津大学発ベンチャー」の授与制度', '会津大学における起業支援に関する規程（平成27年3月31日規程第3号、最終改正2025年4月1日）第3条第1号が支援メニューの筆頭に「会津大学発ベンチャーの称号付与」を掲げ、細目は「公立大学法人会津大学の研究成果等を活用したベンチャーへの称号の授与について」（平成24年4月1日施行）に定める。同定め第2で称号名を「会津大学発ベンチャー」と規定。固定資産使用料規則別表2-2は「認証会津大学発ベンチャー」の語を用いる。', 'official', 'https://u-aizu.ac.jp/files/page/intro/regulations/reg142_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'attr_eligible_scope', 'established', '特許技術活用型・研究成果活用型・人材移転型ほか計7区分', '称号の授与について第3で、a本学又は本学教員が所有する特許をもとに起業（特許技術活用型）、b本学で達成された研究成果又は習得した技術をもとに起業（研究成果活用型）、c教職員や学生（学部生・院生を問わず、在籍中かどうかも問わない）が設立者となるか設立に深く関与して起業（人材移転型）。同第2項でd本学で学んだ内容をもとに創業、e本学でベンチャービジネス論等を学んで起業を決意、f県内設立から5年程度以内に本学と共同研究等、gその他学長が認めた場合も申請可。', 'official', 'https://www.ubic-u-aizu.jp/images/stories/pdf/h24kijyun.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'attr_recognition_decider', 'established', '学長が可否決定（申請は会津大学長宛）', '称号の授与について第4で申請書（様式1）を会津大学長へ提出、第5で学長が称号授与の可否を決定し申請者へ通知、第6で称号記（様式2）を授与。一方、起業支援に関する規程第4条は称号を含む支援の申請先をUBICセンター長とし、第5条でセンター長が別に定める場合を除き可否を決定して学長へ報告すると定める。認定委員会に相当する審査組織は公開規程に見当たらない。株式等の取得のみ理事長決裁・職務発明審査会審査。', 'official', 'https://www.ubic-u-aizu.jp/images/stories/pdf/h24kijyun.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_cert_pre_registration', 'established', '個人でも申請可、起業予定者も施設利用対象', '称号申請書（様式1）の添付書類は「法人においては登記簿謄本、個人においては住民票」で、法人登記のない個人でも申請できる。起業支援に関する規程第2条第1号も起業者を「起業した個人又は法人」と定義。UBICインキュベーション施設ページの研究開発室使用対象者は「会津大学の教員又は学生が起業した法人（設立後5年以内）、又は起業しようとする個人」。認定予定通知・条件付認定の定めは公開規程に見当たらない。', 'official', 'https://www.ubic-u-aizu.jp/incubation/kenkyu-kaihatsu.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'attr_validity_years', 'established', '称号は期限なし（取消規定あり）、施設は年度更新', '称号の授与について第7は、社会的信用を失墜する行為・公序良俗違反、その他保持させるに値しないと学長が判断した場合に授与を取消し称号記を返還させると定めるのみで、有効期間と更新の規定はない。起業支援に関する規程第7条も取消事由（信用失墜、事業活動の実態消滅、本人申出、事業報告不提出等）のみ。産学イノベーションセンター使用規程第7条は施設側を1許可1年以内・年度ごと更新、研究開発室の上限を教員学生5年、その他3年と定める。', 'official', 'https://www.ubic-u-aizu.jp/images/stories/pdf/h24kijyun.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_head_office_registration', 'established', '可。研究開発室等の入居期間中に限る', '起業支援に関する規程第3条第6号「本学の住所を法人登記の住所として利用」。同号は第2号の研究開発室又は第3号の先端ICTラボのプロジェクトルームを使用するときに限るという条件付きで、登記に関して必要な事項は別に定めるとする。UBIC「起業に向けた支援」ページも、本学施設を利用して事業活動を行うベンチャーは入居期間中に本学を法人登記の所在地として活用できると明記。登記自体の使用料は固定資産使用料規則に定めがない。', 'official', 'https://u-aizu.ac.jp/files/page/intro/regulations/reg142_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_facility_lease', 'established', 'UBIC研究開発室・LICTiAプロジェクトルーム、有償', '起業支援に関する規程第3条第2号から第4号で研究開発室、先端ICTラボのプロジェクトルーム、UBICインキュベーションスペースの利用を規定。産学イノベーションセンター使用規程第7条で使用期間は1許可1年以内・年度更新、研究開発室の上限は教員および学生が最長5年、その他の使用者が最長3年、起業した学生はセンター長審査で延長可。固定資産使用料規則別表2-1で研究開発室個室は1室1年あたり大798,600円、中638,880円、小319,440円。', 'official', 'https://www.u-aizu.ac.jp/files/page/intro/regulations/reg099_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_shared_equipment', 'established', '先端ICTラボ・センター設備を有償利用、認定枠で減免', '起業支援に関する規程第3条第5号で先端ICTラボのデータセンタークラウドサービスやサイバーセキュリティウォールーム等の利用を規定。固定資産使用料規則別表2-1は研究サーバ一般1月35,000円、AIクラウド1月50,000円、3Dシアターと運動解析ルームは1回単位、インキュベーションスペースは1IDカード1月3,000円。別表5-3第1号で認証会津大学発ベンチャーの先端ICTラボ使用を日・時5/10、月3/10まで減免。', 'official', 'https://www.u-aizu.ac.jp/files/page/intro/regulations/reg106-3_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_name_logo_use', 'established', '称号使用可・称号記授与。ロゴ条件は非公開', '称号の授与について第6で学長が称号記（様式2）を申請者へ授与、同第2項で本学は称号を授与したことにより法的責任を負わないと明記。第8で学長は称号を受けた者へベンチャー支援に関する情報を提供するとともに、学内外のイベントやセミナー等を通じて称号を授与したベンチャー企業である旨を広くPRすると定める。大学ロゴマーク・校章の使用条件を定めた規程は、公立大学法人会津大学の法人規程一覧および公開ページで確認できなかった。', 'official', 'https://www.ubic-u-aizu.jp/images/stories/pdf/h24kijyun.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_ip_license', 'established', '実施料減免と株式等による対価支払を請求可', '起業支援に関する規程第3条第7号は、起業者が本学所有の知的財産権の使用許諾に関し、「会津大学における大学発ベンチャーに対する対価として取得する株式等の取扱規程」に基づく株式等によるライセンス等の対価支払、および社会全体の利益等を考慮した実施料の減免などの措置を求めることができると定める。独占的実施許諾を優遇する規定は、教員等の職務発明等に関する規程および共同研究取扱規程には見当たらない。', 'official', 'https://u-aizu.ac.jp/files/page/intro/regulations/reg142_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_equity_rule', 'established', '株式・新株予約権の取得規程あり（2025年4月施行）', '会津大学における大学発ベンチャーに対する対価として取得する株式等の取扱規程（2025年4月1日施行）第3条で、相手方が大学発ベンチャーであり、対価相当の現金を保有しない、資金繰りに窮する、経営に重要な影響を及ぼす、理事長が認めるのいずれかに該当するとき、ライセンス等の対価の一部又は全部を株式等で取得できる。第4条で理事長が職務発明審査会に審査させ外部専門家の意見も聴取、第5条で取得決定。第10条第2項は議決権等の経営参加権を原則不行使。', 'official', 'https://www.u-aizu.ac.jp/files/page/intro/regulations/reg165_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_gap_fund', 'established', 'みちのくGAPファンド（MASP参画）STEP1最大500万円', 'UBICのスタートアップ支援ニュースが、東北・新潟の大学等で構成する「みちのくアカデミア発スタートアップ共創プラットフォーム（MASP）」の令和8年度みちのくGAPファンド公募を掲載。STEP1はモノづくり・Deep-Tech枠と医療系・創薬枠が各500万円以下、ソーシャル・イノベーション枠が200万円以下、STEP2は6,000万円以下。対象はMASP参画大学の研究者・大学院生。会津大学単独の学内GAPファンドや起業準備資金の制度は公開情報で確認できなかった。', 'official', 'https://www.ubic-u-aizu.jp/incubation/news/8gap.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_accelerator', 'established', 'UBIC専任教員の伴走・起業相談窓口・アントレ教育', '起業支援に関する規程第3条第8号で、学部生又は院生として在籍する起業者はUBIC専任教員等から経営戦略の相談、事業計画書の作成支援、税理士等の専門家の紹介など事業活動に係る支援を受けられると定める。UBIC「起業に向けた支援」ページは起業相談と特許相談の窓口を明示し、学外者は本学の知的財産権を利用した起業を対象とする。アントレプレナーシップ教育ページにイノベーション・創業教育プログラム、ICT創業トライアルプログラム、会津IT日新館を掲載。', 'official', 'https://www.ubic-u-aizu.jp/incubation/support.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_coi_sidejob', 'established', '研究成果活用兼業は学長許可、利益相反は毎年度申告', '公立大学法人会津大学職員兼業規程（平成18年4月1日規程第43号）第2条で、教員が研究成果活用企業の役員等を兼ねるには学長の許可が必要、第3条に7項目の許可基準、第5条で年1回の報酬額を含む報告義務、第11条で許可期間は1年以内・更新可。利益相反マネジメントに関する要綱（最終改正2026年4月1日）第5条で利益相反委員会を設置、第12条で毎年度4月末までの自己申告書提出を義務化。株式等取扱規程第12条は同要綱に基づく株式保有状況調査を規定。', 'official', 'https://www.u-aizu.ac.jp/files/page/intro/regulations/reg053_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'attr_support_fee', 'established', '有償。認証ベンチャーは使用料5/10減免', '固定資産使用料規則第3条・別表2-2第3号は「認証会津大学発ベンチャーが実施する事業で、使用に際し料金を徴収しないとき」使用料を5/10まで減免と定める。備考1で研究開発室を除外するのは減免事由1・2・4のみのため、ベンチャー減免は研究開発室にも及ぶ。別表5-3第1号は先端ICTラボを日・時5/10、月3/10減免。産学イノベーションセンター使用規程第5条第3項で減免を受ける場合は使用料減免申請書（様式3）を提出。称号授与や起業相談自体の手数料の定めはない。', 'official', 'https://www.u-aizu.ac.jp/files/page/intro/regulations/reg106-3_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'attr_certified_count', 'established', '40社（2026年3月3日現在）、企業名と事業内容を公開', 'UBIC「大学発ベンチャー紹介」ページに「会津大学発ベンチャー（2026年3月3日現在）」として40社の企業名と事業内容の一覧を掲載。同ページから「会津大学発ベンチャーへの称号の授与について」（PDF）と称号申請様式（PDF・Word）へリンクしている。機関自身の公開一覧であり、外部調査の機関別件数は用いていない。', 'official', 'https://www.ubic-u-aizu.jp/incubation/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_cert_rule', 'established', 'あり、称号「鹿児島大学認定ベンチャー」を授与', '根拠は「国立大学法人鹿児島大学発ベンチャーの認定及び支援に関する規則」（平成28年5月26日規則第51号、令和8年3月10日施行の改正を反映）。第5条で、学長が認定した大学発ベンチャーに対し別に定める称号記により「鹿児島大学認定ベンチャー」の称号を授与すると規定。第1条は事業化・製品化を推進するイノベーションの担い手の育成と支援を目的に掲げる。イノベーションセンターの「鹿児島大学認定ベンチャー称号・支援」ページでも同制度を紹介。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'attr_eligible_scope', 'established', '教職員・学生・退職卒業3年以内・共同研究/技術移転5年以内の5類型', '同規則第2条が定義を5号に限定列挙。第1号は教職員が本学または本人所有の知的財産権・本学で達成した研究成果等を活用して設立、もしくは設立に深く関与した企業等。第2号は学生が自己所有の知的財産権または本学での研究成果等を活用して設立した企業等。第3号は本学を退職・卒業・修了・退学した者で、退職等から設立までが3年以内の者による企業等。第4号は設立後5年以内に本学と共同研究等を行いその成果を事業化する企業等。第5号は設立後5年以内に本学から技術移転を受けた企業等。申請書別記様式第1号の⑬「ベンチャー設立形態」でア〜オのいずれかを選択させる。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'attr_recognition_decider', 'established', '学長（大学発ベンチャー認定審査会の審議を踏まえ決定）', '同規則第3条第2項で、学長は申請があったとき南九州・南西諸島域イノベーションセンターに設置する「大学発ベンチャー認定審査会」に付議し、その審議結果を踏まえて認定の決定を行い、結果を文書で申請者に通知すると規定。同条第3項で審査会の運営等は別に定めるとされるが、その内規は公開されていない。第12条により事務は研究推進部社会連携課が処理し、大学の「大学発ベンチャー支援」ページでも申請先を同課産学・地域連携係としている。第4条第1項の申請条件審査も同じ経路。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_cert_pre_registration', 'established', '創業前申請可、個人は1年以内創業の誓約書を添付', '申請書様式「大学発ベンチャー認定申請書」（別記様式第1号、第3条関係）の⑥「事業開始日等」に、事業開始日・設立日と並んで「事業開始予定日」欄を置く。添付資料の(1)bで「1年以内に創業を行おうとする個人にあっては、その旨の誓約書」を求め、記入要領(7)は⑯「事業予定及びその準備活動のスケジュール」を「創業を行おうとする場合にのみ記入」としており、創業前の申請を様式が明示的に想定している。法人については添付資料(2)で設立の日が確認できる書類または定款等の写しを求めるにとどまり、設立登記前の申請、認定予定通知、条件付認定の明文はない。', 'official', 'https://www.kagoshima-u.ac.jp/research/b-form001_20240314.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'attr_validity_years', 'established', '支援期間5年、1年単位で通算10年まで延長可', '同規則第11条第2項で、施設・設備の貸付、クリエイティブ産業創出拠点施設の貸付、バーチャルオフィス利用の支援期間を原則として認定後5年に達する日の属する年度末までとし、必要な場合は1年を単位として通算10年に達する日の属する年度末まで延長できると規定。第3項で学長が必要と認めた場合は10年経過後もさらに学長が認めた期間まで延長可。第4項で延長申請には第3条第2項の認定手続を準用する。大学の「大学発ベンチャー支援」ページも支援の有効期間を授与日から5年、通算10年まで延長可と記載。認定自体の期限は定めがなく、第10条の取消し事由による。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_head_office_registration', 'established', '可、産学交流プラザの住所で法人登記（有償）', '同規則第11条第1項第1号アが「産学交流プラザ棟の居室（法人登記上の住所の使用を含む。）」を有償貸付の対象とし、第7項で同居室の利用および第3号のバーチャルオフィス利用における法人登記上の住所は産学交流プラザの住所とすると明記。したがって居室に入居しないバーチャルオフィス利用だけでも学内住所での商業登記が可能。第5項で居室の施設使用料は国立大学法人鹿児島大学不動産管理規程（平成16年規則第77号）により、第8項でバーチャルオフィス利用料は別表のとおり支援利用開始前に一括納入と定める。イノベーションセンターのページも支援内容に「本学の所在地における法人登記上の住所の使用承認」を挙げる。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_facility_lease', 'established', '産学交流プラザ棟居室は有償、mark MEIZANは無償', '同規則第11条第1項第1号アで産学交流プラザ棟の居室を有償貸付、第2号で本学が貸与を受けている鹿児島市クリエイティブ産業創出拠点施設を無償貸付と規定。イノベーションセンター「事業化支援プロジェクト」ページによると、センターが管理するインキュベーション施設は産学交流プラザ棟内に実験室9室と研究室7室、医歯学総合研究科に研究室1室、鹿児島市クリエイティブ産業創出拠点施設「mark MEIZAN」にシェアオフィス5区画。同ページの入居者リスト（2025年8月1日現在）では大半の部屋を認定ベンチャーが使用。認定ベンチャー称号・支援ページは、産学交流プラザ居室は空室があればすぐ入居できると案内。期間は第11条第2項の5年・通算10年。', 'official', 'https://www.krcc.kagoshima-u.ac.jp/start-business/startup-support-project/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_shared_equipment', 'established', '研究設備等を有償貸付、学内規則の遵守が条件', '同規則第11条第1項第1号イが「研究設備等」を本学施設・設備等の有償貸付の対象として列挙し、第6項で研究設備等の利用については本学の定める規則等を遵守しなければならないと規定。全学の共用機器の枠組みとしては「国立大学法人鹿児島大学コアファシリティ推進本部規則」（令和4年7月21日規則第69号）第1条が、基盤的・先進的な研究設備・機器を学内外の研究者が共用する仕組みの強化と、共用機器等の導入・更新等の一元管理を定める。ただし同規則に認定ベンチャーを名指しした条項はなく、認定ベンチャーの利用根拠はベンチャー規則側の有償貸付。料金区分の詳細は公開されていない。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_name_logo_use', 'established', '称号授与、学章・マスコットを所定規則に基づき使用可', '同規則第5条で「鹿児島大学認定ベンチャー」の称号を称号記（別記様式第2号）により授与。第11条第1項第6号で「学章及びマスコットキャラクターの使用」を支援として規定し、第9項で当該使用は鹿児島大学学章に関する規則（平成28年規則第26号）および国立大学法人鹿児島大学マスコットキャラクター使用取扱要項（平成26年2月10日学長裁定）その他契約書等の定めによるとする。第5号で本学の広報誌・Webサイト等における広報も支援対象。申請書別紙「希望する支援内容等」に学章及びマスコットキャラクターの使用を希望する欄があり、称号使用によって生じた損失・損害について大学は法的責任を負わない旨も明記。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_ip_license', 'established', '知財使用の優遇措置、対価を株式等に代替し現金支払を免除・軽減', '同規則第11条第1項第4号が「本学が所有する知的財産権、ノウハウ等の使用に関する優遇措置」を支援として規定。優遇の具体形として「国立大学法人鹿児島大学におけるライセンス等の対価として取得する株式等取扱規則」（令和3年4月22日規則第25号）第3条があり、大学発ベンチャー企業が希望し、研究成果を活用した事業の有望性が高く、現金による支払いを免除または軽減することが経営の加速のため特に必要と認められる場合に、ライセンス等の対価を現金に代えて株式等で取得できる。独占的実施許諾や実施料率の減免率を定めた条文は公開規程には見当たらない。知的財産規則（平成16年規則第41号）は実施許諾一般を定める。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00001098.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_equity_rule', 'established', '知財ライセンス対価として株式・新株予約権を取得可', '「国立大学法人鹿児島大学におけるライセンス等の対価として取得する株式等取扱規則」（令和3年4月22日規則第25号）が正面から規定。第2条第3号で株式等を株式および新株予約権（新株予約権付社債を含む）と定義。第4条で南九州・南西諸島域イノベーションセンター運営委員会規則第8条に基づく知的財産審査会が取得の可否を審査し、第5条で学長が決定して契約書等を取り交わす。第7条で共益権は原則不行使、第8条で換金可能になり次第売却し、売却は原則として有価証券処分信託等を利用。第9条で新株予約権は行使可能となり次第行使。第10条で利益相反マネジメント委員会がインサイダー取引該当性を個別調査。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00001098.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_gap_fund', 'unknown', null, '［自動検証で否認: 機関数20は誤り(実際15+FVP)。GAP未記載］元の主張(established): 参画するPARKSのGAPファンドプログラムを利用可。イノベーションセンターの「大学発スタートアップ創出プラットフォーム『PARKS』」ページで、本学がPARKS（九州・沖縄の20機関で構成、JST大学・エコシステム推進型スタートアップ・エコシステム形成支援の採択事業）の共同機関として参画し、4ステップの起業活動支援プログラムの提供を受けると明記。PARKS公式サイトの令和6年度GAPファンドプログラム募集ページによれば、応募資格はPARKSに所属する大学の研究者および修士以上の学生で、研究開発費とインキュベーションプログラム等を提供する。同PARKSページは独自VC・PoCファンドを運用するPARKSインターユニバーシティ設立を今後の目標としており、鹿児島大学自身の学内GAPファンドは公開情報では確認できない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_accelerator', 'established', '事業化支援プロジェクト（2年）と相談窓口・ピッチを制度化', 'イノベーションセンター「事業化支援プロジェクト」ページで、本学教職員を対象に、事業化が見込まれる学内の研究シーズや研究活動に対し産学交流プラザ棟等のプロジェクトルームの貸出と事業化に向けた相談・助言支援を行い、利用期間は2年と明記。同センターの「事業化支援相談」ページはアントレプレナーシップ・スタートアップチームを窓口として常設。「KADAI STARTER''s PITCH」ページによれば、NEDOとの起業家支援に係る相互協力の覚書に基づくビジネスプランピッチコンテストを毎年1月最終週金曜に開催し、学生の部も実施。ほかに共通教育科目「起業」、大学院MOT教育プログラム、PARKSの起業活動支援プログラムを「起業」メニューに整理。', 'official', 'https://www.krcc.kagoshima-u.ac.jp/start-business/startup-support-project/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_coi_sidejob', 'established', '役員兼業は学長許可制、申請時に兼業許可と利益相反申告を確認', 'ベンチャー規則第4条第4号が申請条件として、本学職員が認定ベンチャーの役員（個人事業の代表者を含む）に就任している場合、国立大学法人鹿児島大学職員兼業規則（平成16年規則第63号）および国立大学法人鹿児島大学産学官連携に係る利益相反マネジメント規則（平成18年規則第6号）その他の関係規則に定める所要の手続が適正に行われていることを求める。申請書別記様式第1号は、設立形態が教職員設立型（ア）の場合に兼業許可申請日と利益相反マネジメント一次自己申告日の記入を求める。兼業規則第3条第1号が営利企業役員等兼業、第4条が学長許可制、第6条が許可基準を定める。ベンチャー規則第8条で学長がセンター長に定期モニタリングを指示。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'attr_support_fee', 'established', '有償と無償の併用、バーチャルオフィスは月額制の有償', 'ベンチャー規則第11条第1項第1号は施設・設備等を「有償による貸付」と明記し、第5項で産学交流プラザ棟居室の施設使用料は国立大学法人鹿児島大学不動産管理規程（平成16年規則第77号）による。第3号のバーチャルオフィス利用料は第8項および別表（第11条関係）で月額の利用料金を定め、支援利用開始前に請求書により一括納入と規定。一方、第2号の鹿児島市クリエイティブ産業創出拠点施設の貸付は「無償による貸付」、第4号の知財使用優遇措置、第5号の広報、第6号の学章・マスコット使用については料金の定めがない。知財ライセンス対価は現金または株式等（令和3年規則第25号）。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'attr_certified_count', 'established', '18社（2026年4月1日現在）、社名一覧を公開', 'イノベーションセンター「鹿児島大学認定ベンチャー称号・支援」ページに「2026年4月1日現在、『鹿児島大学認定ベンチャー』は以下の18社です」と明記され、i-Analyze、スディックスバイオテック、FineMetrics、食品安全推進センター、クルーシャル・クーリング・パフォーマンス、キュア薬品、TriGo、構造物診断技術研究会、こどものけんちくがっこう、サーブ・バイオファーマ、iCUREX、アーダンラボ、ZIFISH、水と塩の科学（WASS）、ナノシロキサン、Alteonus、琉球昆虫、Aulum IPの社名を一覧公開。一部は企業サイトへのリンク付き。株式会社以外に一般社団法人、NPO法人、合同会社を含む。', 'official', 'https://www.krcc.kagoshima-u.ac.jp/start-business/venture1/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_cert_rule', 'established', '「新潟大学発ベンチャー」称号授与規程による認定制度', '国立大学法人新潟大学における新潟大学発ベンチャーの称号授与に関する規程（令和2年2月21日規程第13号、令和8年3月27日規程第23号まで改正）。第1条で本法人の研究成果又は人的資源を活用して起業したベンチャー企業に「新潟大学発ベンチャー」の称号を授与すると定める。第4条第1項で学長が称号記（別記様式第2号）の交付により授与。第7条で授与・取消しを大学ウェブサイトで公表。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'attr_eligible_scope', 'established', '教職員・学生の知財／研究成果活用企業、退職・卒業3年以内含む', '称号授与規程第2条は「新たな技術又はビジネス手法を基に起業した企業」を前提に5区分を列挙。(1)教職員が所有する知的財産権（職務発明規程第3条第4項の権利）を活用し設立、(2)本学で得られた研究成果又は技術等を基に設立、(3)教職員（退職日から設立日まで3年以内の者を含む）が設立又は設立に深く関与、(4)学生（卒業・修了日から設立日まで3年以内の者を含む）が設立又は設立に深く関与、(5)学長が前4号に準ずると認めたもの。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'attr_recognition_decider', 'established', '学長（社会連携推進機構会議の議を経て決定）', '称号授与規程第3条第1項で申請先は学長（別記様式第1号の申請書）。同条第2項で「学長は、前項の申請があったときは、社会連携推進機構会議の議を経て、称号の授与の決定を行う」。第9条で称号授与に関する事務は研究企画推進部が処理。社会連携推進機構会議規程第2条第6号は「大学発ベンチャーの育成・創出に関する事項」を同会議の協議事項に掲げる。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_cert_pre_registration', 'not_started', '設立済み企業のみ申請可、登記前申請の定めなし', '称号授与規程第3条第1項は申請主体を「称号の授与を希望する企業」と限定。第2条の申請資格5区分はいずれも「起業した企業」「設立した企業」を要件とし、第3号・第4号は「企業設立の日」を起算点に用いる。設立登記前の申請、認定予定通知、条件付認定に関する規定は同規程に置かれていない。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'attr_validity_years', 'established', '3年、更新可', '称号授与規程第4条第2項「認定企業が称号を保持できる期間は、称号を授与された日から3年間とする。ただし、保持期間は、更新することができる」。同条第4項で更新希望時は称号授与申請書により学長へ申請し、審査は第3条第2項（社会連携推進機構会議の議）を準用。公開一覧の認定期間が6年・9年に及ぶ企業があるのは更新の累積による。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_head_office_registration', 'unknown', null, '称号授与規程第4条第3項が認定企業に認めるのはロゴマーク使用と施設・設備の利用のみで、本店所在地としての商業登記に触れていない。固定資産貸付け及び譲与細則第2条第1項第4号ニは研究成果活用事業への不動産貸付を認めるが、登記の可否は明記がない。入居要項やインキュベーション施設の利用規程は公開情報で確認できなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_facility_lease', 'established', '研究成果活用事業（創業準備含む）へ固定資産を原則有償で貸付', '国立大学法人新潟大学固定資産貸付け及び譲与細則第2条第1項第4号ニ「本学の研究成果を活用した事業（創業準備を含む。）を行う中小企業又は個人にその事業の用に供するため本学の固定資産を使用させることが必要と認められるとき」。同項本文で貸付期間は1年を限度（特別な事由があるときは超過可）、同条第2項で「前項による貸付けは、原則として有償とする」。同号ハでTLOへの貸付も規定。称号授与規程第4条第3項も認定企業の施設・設備利用を認める。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110000193.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_shared_equipment', 'established', '共用設備基盤センター登録機器を学外利用者料金で利用可', '称号授与規程第4条第3項で認定企業は本学の管理運営及び教育研究に支障のない範囲で施設・設備を利用できる。新潟大学研究統括機構共用設備基盤センター機器分析部門における機器登録及び登録機器の利用に関する細則第2条は民間機関所属者を「学外者」「学外利用者」と定義し、第11条第1項で利用者は経費を負担、第2項で学外利用者の負担額は同部門登録機器に係る利用料金細則（平成30年細則第36号）の定めによるとする。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110000939.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_name_logo_use', 'established', '称号とロゴマークの使用可、品質保証目的の使用は禁止', '称号授与規程第4条第3項「認定企業は、本学の管理運営及び教育研究に支障のない範囲において、本学のロゴマークの使用及び施設・設備の利用ができる」。第5条第1項で製品・サービス等の内容及び品質を保証するための称号使用を禁止し、第2項で学長は当該使用の停止を命じられる。第6条第2項で取消し後は称号保持の事実を事業に利用してはならない。社会連携推進機構の公開ページも称号授与とロゴ使用許可を明記。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_ip_license', 'established', 'ライセンス対価の株式等による代替払いが可能', '国立大学法人新潟大学におけるベンチャー企業を対象としたライセンス等の対価として取得する株式等取扱規程（令和7年1月24日規程第2号）第1条・第3条。現金での対価支払が困難として申し出があり、事業の有望性が高いこと、現金支払の免除又は軽減が経営の加速に必要と認められることの両方に該当する場合に、知的財産権の譲渡・実施権設定・実施許諾等の対価を株式等で取得できる。職務発明規程には独占的実施許諾や大学発ベンチャー向け対価減免の規定は見当たらない。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110002835.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_equity_rule', 'established', 'ライセンス対価として株式・新株予約権を取得可', '株式等取扱規程第2条第4号で「株式等」を株式及び新株予約権と定義。第4条で職務発明規程第4条の発明審査委員会が取得の可否を審査し学長へ報告、第5条で学長が取得を決定し契約書を取り交わす。第7条で新株予約権は行使可能時に速やかに行使、第8条で共益権は原則不行使、第9条で換金可能となり次第売却、第10条でインサイダー取引防止と株式処分信託の利用を定める。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110002835.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_gap_fund', 'unknown', null, '社会連携推進機構ベンチャリング・センター規程第3条第4号は「大学発ベンチャーの育成・創出に関連した資金の獲得及び運営に関すること」を同センターの業務に掲げるが、学内GAPファンド、起業準備資金、POC資金として制度化された規程やプログラム募集ページは規程集・社会連携推進機構サイトのいずれでも確認できなかった。', 'unknown', 'https://public1.legalcrud.com/niigata_univ/act/110002480.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_accelerator', 'established', 'ベンチャリング・センターによる育成・創出支援', '新潟大学社会連携推進機構ベンチャリング・センター規程（令和5年4月1日社機規程第3号）第2条で、技術シーズ等の連携による大学発ベンチャーの育成・創出支援と、本学を中心としたスタートアップ・エコシステムの構築を目的とする。第3条で教員・学生が関与する大学発ベンチャーの育成・創出と学外機関との連携、学内ネットワークの構築・運営、関連資金の獲得・運営を業務に列挙。第4条でセンター長・副センター長を置き、第5条で運営会議を設置。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110002480.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_coi_sidejob', 'established', '研究成果活用企業の役員兼業は学長許可制、株式取得は利益相反管理対象', '国立大学法人新潟大学職員兼業規程第2章第2節「研究成果活用企業の役員等の兼業」（第10条－第16条）。第11条で研究成果活用企業を研究成果を活用する事業を実施する営利企業と定義し、第12条で学長が許可基準（自らが発明・考案等をした研究成果であること、職務内容が主として研究成果活用事業に関すること、契約関係等の特別な利害関係がないこと等）への適合を認めるときに許可。利益相反マネジメント規程第3条第2号は役職員が企業等から一定額以上の金銭又は株式等を取得するものをマネジメント対象とする。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110000096.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'attr_support_fee', 'established', '称号授与は無償、施設貸付と機器利用は有償', '称号授与規程には申請手数料や称号授与の対価に関する規定がなく、第4条第3項のロゴマーク使用・施設設備利用にも対価の定めがない。一方、固定資産貸付け及び譲与細則第2条第2項は貸付けを原則有償と定め、共用設備基盤センター機器分析部門の細則第11条第2項は学外利用者に利用料金細則所定の額の負担を求める。株式等取扱規程はライセンス対価の現金払いを株式等に代替できる場合を限定的に定める。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'attr_certified_count', 'established', '14社、認定期間付きで一覧公開', '社会連携推進機構の大学発ベンチャーページに認定企業14社が企業名と認定期間付きで掲載（2026年9月10日確認）。最初の認定は2020年7月10日の株式会社アイセック、最新は2025年9月22日認定の株式会社未来農村かりわ総合研究所。称号授与規程第7条が授与・取消しの公表を義務づけている。', 'official', 'https://www.ircp.niigata-u.ac.jp/collaboration/venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_cert_rule', 'established', '有、名工大発ベンチャーの称号を学長が授与', '「名古屋工業大学発ベンチャーに関する規程」（平成28年3月24日規程第28号、平成28年4月1日施行、平成29年・2021年2月・2021年6月改正）。第1条で大学発ベンチャーの適正な支援を目的とし、第3条第1項で学長が第4条の手続を経た企業に「名工大発ベンチャー」の称号を授与すると定める。第5条で称号授与は大学に法的責任を生じさせないと明記。第6条に解散・破産等の報告義務、第7条に返付、第8条に取消しの定めがある。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'attr_eligible_scope', 'established', '教職員・学生の起業、知財活用・技術移転・出資先企業', '発ベンチャー規程第2条の限定列挙。第1号は職員就業規則上の教員・一般職員、特定有期雇用職員、パートタイマー、再雇用職員、または本学の学生が設立者もしくは設立に深く関与した者となって起業したベンチャー企業。第2号は法人所有の知的財産をもとに起業した企業、第3号は法人から技術移転を受けた企業、第4号は法人が出資した企業。卒業生・退職者を対象に含める規定（退職・卒業後○年以内など）は同条に置かれていない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'attr_recognition_decider', 'established', '学長（産学官金連携機構推進会議の審査を経て決定）', '発ベンチャー規程第4条。第1項で申請者（大学発ベンチャーの代表者）が別記様式第1号により学長へ申請、第2項で学長は産学官金連携機構推進会議の審査を経て称号授与を決定し、推進会議は必要に応じ面接の実施と関連資料の提出を求めることができる。第3項で学長が様式第2号により称号を授与する。推進会議は「名古屋工業大学産学官金連携機構規則」第8条に基づく機構の審議機関で、機構長・副機構長・学長指名の理事・研究支援課長らで構成される。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_cert_pre_registration', 'not_started', '設立確認書類の添付必須、登記前申請の定めなし', '発ベンチャー規程の別記様式第1号（第4条第1項関係）「名工大発ベンチャー称号授与申請書」は、商号・所在地・代表者・設立日・資本金・従業員数・事業の概要の記載欄を持ち、末尾に「会社設立が確認できる法的書類を添付のこと」と明記している。設立登記前の申請、認定予定通知、条件付認定を受け付ける規定は同規程・同様式のいずれにも置かれておらず、設立済みであることが申請の前提になっている。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'attr_validity_years', 'established', '原則として永年使用可、更新手続の定めなし', '発ベンチャー規程第3条第2項「名工大発ベンチャーの称号は，原則として永年使用することができる」。有効期間の年限や更新申請の規定は置かれていない。ただし第6条で解散・破産・再生手続・更生手続・不正競争防止法の罰金刑確定・企業活動の実態の消滅等を学長へ報告する義務があり、第8条で定義からの著しい逸脱・社会的信用の失墜等があれば学長が称号授与を取り消せる。取消し後は称号授与を受けていた事実を事業に使用できない（第8条第2項）。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_head_office_registration', 'established', '可、本学所在地での商業登記を認容、料金の定めなし', '発ベンチャー規程第10条第3号「本学所在地を名工大発ベンチャーの所在地とする商業登記を認めること」。同条柱書により、管理運営及び教育研究に支障のない範囲で行う支援として位置づけられる。対価の有無は同条に定めがなく、インキュベーション施設細則にも登記に関する条項はない。実際に大学発ベンチャー企業紹介ページでは、複数社が名古屋工業大学22号館インキュベーションオフィスを連絡先として掲載している。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_facility_lease', 'established', '可、インキュベーション施設を事務室として有償貸与', '発ベンチャー規程第10条第2号で事務室としての施設貸与を支援に列挙し、第9条で産学官金連携機構に名古屋工業大学インキュベーション施設を置き機構長が管理運営を統括すると定める。詳細は「名古屋工業大学インキュベーション施設細則」（平成28年3月24日細則第9号）。第2条の使用資格は名工大発ベンチャーの称号を受けた大学発ベンチャー、または使用資格付与が大学にとって有益と判断される者。第3条で学長が推進会議の審査を経て使用許可の可否と使用期間を決定。第8条で別表第一の使用料（光熱水料を含む月額）を負担。オフィスは13室。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E3%82%A4%E3%83%B3%E3%82%AD%E3%83%A5%E3%83%99%E3%83%BC%E3%82%B7%E3%83%A7%E3%83%B3%E6%96%BD%E8%A8%AD%E7%B4%B0%E5%89%87.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_shared_equipment', 'established', '可、共用設備を学内料金で利用', '発ベンチャー規程第10条第4号「共用設備の利用料金を学内料金にて使用させること」。学外料金ではなく学内料金区分を適用する優遇である。産学官金連携機構の装置利用ページ（分析機器一覧）では各装置に「学内外」「学内のみ」の区別が示され、学内のみ表示でも学外対応可能な場合があると注記されているが、料金表そのものと大学発ベンチャー向けの料金区分は同ページには掲載されていない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_name_logo_use', 'established', '可、名工大発ベンチャーのロゴ使用権を付与', '発ベンチャー規程第10条第1号「名工大発ベンチャーのロゴを使用する権利を与えること」。称号自体は第3条により授与され、原則永年使用できる。第8条第2項で、称号授与を取り消された企業は速やかに称号を返付し、取消日以後は称号授与を受けていた事実を事業に使用してはならないと定める。大学の校章そのものの使用条件については、この規程には別段の定めがない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_ip_license', 'established', '大学所有知財の譲渡を明記、許諾優遇の条件は非公開', '発ベンチャー規程第10条第7号「法人が所有する知的財産を譲渡すること」を支援に列挙する。譲渡であって実施許諾ではない点に注意。「国立大学法人名古屋工業大学知的財産ポリシー」（平成16年4月1日制定、2026年4月8日最終改正）第7条の活用方針では、実施許諾・権利譲渡・産学連携・大学発ベンチャー活用を列挙し、同条第4号で大学発ベンチャーに対し知的財産の活用に関し適切な配慮を行うと定める。独占的実施許諾、実施料の減免、株式・新株予約権による対価の具体的条件は同ポリシーに明記がない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E7%9F%A5%E7%9A%84%E8%B2%A1%E7%94%A3%E3%83%9D%E3%83%AA%E3%82%B7%E3%83%BC.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_equity_rule', 'established', '法人出資・関与ファンドの対象化を明記、手続規程なし', '発ベンチャー規程第10条第5号「法人が関与するベンチャーファンド及び法人の出資対象とすること」を支援に列挙し、第2条第4号は法人が出資したベンチャー企業を大学発ベンチャーの定義に含める。ただし出資の意思決定手続、持株比率、新株予約権（ストックオプション）の取得・行使を定める独立の規程は、大学規則集の全規程一覧に見当たらない（「出資」「株式」を含む規程名なし）。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_gap_fund', 'established', '名工大発ベンチャー応援基金、公募・配分要項は非公開', '大学の起業支援サイト「NITech ENTREPRENEURSHIP」内の「ベンチャー応援基金のご案内」に、名工大発ベンチャー応援基金の使途として、学生のプロトタイピング補助、ビジネスコンテスト参加時の遠征補助、育成カリキュラムの拡充、起業支援、活動場所の提供が挙げられている。試作用の機械や場所など資金以外の寄附も受け付ける。寄附受入を主とする基金で、研究成果の事業化検証に配分するGAPファンドの公募要項・配分基準・採択件数は公開されていない。', 'official', 'https://tongali.web.nitech.ac.jp/for-corp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_accelerator', 'established', 'アントレプレナー育成塾等の育成事業、Edge-NEXT採択', '産学官金連携機構の「アントレプレナー育成事業」として起業支援サイト「NITech ENTREPRENEURSHIP」を運営。文部科学省Edge-NEXT（次世代アントレプレナー育成事業）の採択事業と明記し、起業家・社会人を招くトークイベント「アントレプレナー育成塾」、企業課題解決型の短期集中プログラム「Second Up」、ビジネスアイデアコンテスト参加サポートを実施。対象は学部生・大学院生・教職員。サイト掲載のイベントは2022年2月が最新で、現在の実施状況は同サイトからは確認できない。認定後の伴走メンタリングを制度化した規程は見当たらない。', 'official', 'https://tongali.web.nitech.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_coi_sidejob', 'established', '研究成果活用企業の役員兼業は学長許可、利益相反は自己申告', '「国立大学法人名古屋工業大学職員兼業規程」（平成16年4月1日制定）第3条第2号で、研究成果活用企業の役員・顧問・評議員を兼ねる場合は兼業許可基準に適合すれば学長が許可できると定め、第16条に兼業審査会を置く。「兼業許可基準」第3条は研究成果活用兼業の許可基準として、当該研究成果を自ら発明・考案していること、職務内容が主として研究成果活用事業に関すること、大学との契約関係・権限行使等の特別な利害関係がないこと等9項目を定め、役員任期を考慮した期限を付す。利益相反マネジメント規程では株式等の経済的利益の取得を自己申告事項とするが、兼業許可と利益相反部会の審査を接続する条文はない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%85%BC%E6%A5%AD%E8%A8%B1%E5%8F%AF%E5%9F%BA%E6%BA%96.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'attr_support_fee', 'established', '施設・共用設備は有償、称号とロゴと登記は料金の定めなし', 'インキュベーション施設細則第8条で、使用責任者は別表第一に定める月額使用料（光熱水料を含む）を負担し、大学の請求書の納入期限までに納付する。第9条で使用期間満了・許可取消し時の原状回復義務、第10条で損害賠償義務、第11条で細則に定めのない事項は国立大学法人名古屋工業大学資産貸付規程によると定める。共用設備は発ベンチャー規程第10条第4号により学内料金区分の適用であって無償ではない。称号・ロゴ使用・商業登記の認容については対価の定めが置かれていない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E3%82%A4%E3%83%B3%E3%82%AD%E3%83%A5%E3%83%99%E3%83%BC%E3%82%B7%E3%83%A7%E3%83%B3%E6%96%BD%E8%A8%AD%E7%B4%B0%E5%89%87.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'attr_certified_count', 'established', '14社、称号授与日つき一覧を公開', '産学官金連携機構の「大学発ベンチャー企業紹介」ページに14社を掲載。各社について会社名・代表者・称号授与日・資本金・主な事業内容・連絡先を記載している。称号授与日は平成29年（2017年）1月から2024年4月までで、平成29年授与が大半を占める。ページ本文に累計認定社数を示す記述はなく、14社は掲載企業を数えた実数。', 'official', 'https://sanren.web.nitech.ac.jp/sangaku/university-ventures/venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_cert_rule', 'established', '医薬基盤・健康・栄養研究所発ベンチャー認定制度', '国立研究開発法人医薬基盤・健康・栄養研究所発ベンチャーの認定に関する規程（令和2年6月18日令和2規程第3号、直近改正令和7年6月26日令和7規程第27号）に基づく。第2条は「ＮＩＢＮ発ベンチャー」を、研究所の知的財産または研究所に関連する技術・知識等の研究成果を活用し本規程に基づき称号を認められたものと定義し、第2項で規程所定の支援を受けられると規定。公式サイト「医薬基盤・健康・栄養研究所発ベンチャーの認定について」も2020年6月開始と記載。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'attr_eligible_scope', 'established', '知財活用型・研究成果活用型、職員要件なし', '認定規程第2条の定義は「研究所の所有する知的財産又は研究所に関連する技術・知識等の研究成果を活用するベンチャー企業」で、職員・学生・退職者といった人的属性の要件は置かれていない。第5条の認定条件は、研究所の研究成果の活用が期待できること、研究所の業務に支障を与えないこと、事業内容等が公序良俗に反しないこと、その他ＮＩＢＮ発ベンチャーとして不適当でないことの4号。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'attr_recognition_decider', 'established', '理事長（ベンチャー認定委員会への諮問・答申）', '認定規程第4条。希望者は様式1の申請書に事業内容・使用する知的財産などの書類を添えて理事長に提出し、理事長が審査をベンチャー認定委員会に諮問する。委員会は審査と必要に応じた面接を行い理事長へ答申し、理事長が答申を基に認定の可否を決定して通知する。委員会は第3条で認定・取消し等の審議機関として研究所に設置。主管部署は第12条で戦略研究支援部（健都に関するものは健都戦略研究支援部）。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_cert_pre_registration', 'not_started', '設立登記後の申請のみ、条件付認定の定めなし', '認定規程第4条の手続は様式1の申請書提出のみで、設立登記前の申請、認定予定通知、条件付認定の規定はない。様式1「発ベンチャー認定申請書」は申請者を法人とし、主たる事務所の所在地・法人の名称・代表者氏名の押印を求め、添付書類に会社定款、事業計画書、会社経歴書、決算報告書（直近2カ年分）、代表者の履歴書を挙げる。公式サイトの認定2社もいずれも設立日の後に認定日がある。', 'official', 'https://www.nibn.go.jp/introduction/disclosure/regulations/venture_nintei_youshiki1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'attr_validity_years', 'established', '期限なし、上場等で支援不要となれば失効', '認定規程第5条は、認定条件の各号のいずれにも該当することを要件として認定の日から有効とし、ＮＩＢＮ発ベンチャーが発行する有価証券が金融商品取引所に上場した場合等支援の必要がなくなった場合に失効すると規定。有効年数や更新手続の定めはない。第9条で理事長による取消し、第10条で本人からの解除申出を規定し、第8条は認定時に指定した日および以後6か月ごとの事業状況報告を義務づける。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_head_office_registration', 'unknown', null, '認定規程第6条第1項第一号は所内の事務室・研究室の貸与を定めるが、商業登記上の本店所在地としての利用可否には触れていない。貸与契約の根拠である研究所資産貸付取扱要領（平成28年要領第6号）は各種規程等ページに掲載がなく非公開。産官学連携ページにもインキュベーション施設の入居要項に相当する公開文書は見当たらず、公開情報では可否を判定できない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_facility_lease', 'established', '所内に事務室・研究室を確保し貸与、資産貸付契約', '認定規程第6条第1項第一号「事務室又は研究室として研究所内に場所を確保し、貸与すること」。同条第2項は、貸与に当たり研究所資産貸付取扱要領（平成28年要領第6号）に基づく契約を締結すると規定し、有償の資産貸付契約として扱う建て付け。施設名、貸付期間、貸付料の額は規程にも公式サイトにも記載がなく、当該要領も非公開。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_shared_equipment', 'established', '研究設備等の利用を許可、料金区分は非公開', '認定規程第6条第1項第二号「研究設備等の利用を許可すること」を支援メニューとして明記。認定ベンチャー向けの利用料金区分、申込手続、対象機器の一覧を定めた公開文書は確認できなかった。生物資源については別途、生物資源の分譲等に関する規程が各種規程等ページに掲載されている。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_name_logo_use', 'established', '称号「NIBN発ベンチャー」付与、商標等の使用許可', '認定規程第2条は本規程に基づき「ＮＩＢＮ発ベンチャー」と称号することが認められたものと定義。第6条第1項第五号は「研究所が所有する商標等に関して使用を許可すること」を支援に掲げ、同条第3項で職務発明等規程（平成17年規程第44号）に基づく契約を締結すると規定。第9条第2項は認定取消し後に称号および認定を受けていた事実を利用した事業を禁止。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_ip_license', 'established', '一定期間の優先的実施許諾、実施許諾料の減免可', '認定規程第6条第1項第四号は「研究所の知的財産権を基にした事業について、一定期間、優先的に実施許諾を行うこと」を規定。同条第3項は職務発明等規程に基づく実施許諾契約を締結し、理事長が適当と認めるときは実施許諾料を減免できると規定。知的財産ポリシー（令和3年8月17日）第9項は研究所が認定するベンチャーへのライセンスを活用手段に挙げ、第10項は非独占的実施権を原則としつつ必要な場合に期間制限付きの独占的実施権を付与できるとする。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_equity_rule', 'established', '株式・新株予約権の取得保有規程あり（令和5規程第6号）', '国立研究開発法人医薬基盤・健康・栄養研究所発ベンチャーに対する支援に伴う株式又は新株予約権の取得及び保有に関する規程（令和5年2月1日令和5規程第6号、直近改正令和7年10月15日）。第3条は認定規程第6条の支援を行った場合に、事業の有望性等を満たすとき株式等を取得できると規定。第4条で理事長がベンチャー認定委員会に審議させ、第8条で議決権は原則不行使、第7条第3項で売却は原則として処分信託を利用。', 'official', 'https://www.nibn.go.jp/introduction/disclosure/regulations/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_gap_fund', 'unknown', null, '認定規程第6条第1項の支援は、場所の貸与、研究設備等の利用許可、シーズ開発の支援、優先的実施許諾、商標等の使用許可、その他理事長が必要と認める支援の6号で、資金提供は明記されていない。産官学連携ページにもGAPファンド、起業準備資金、POC資金に相当する公開制度は見当たらない。第六号が包括規定であるため制度なしとは断定できず、公開情報では判定できない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_accelerator', 'established', 'シーズ開発支援を規程に明記、主管は戦略研究支援部', '認定規程第6条第1項第三号「研究成果の実用化に向けた、シーズ開発の支援を行うこと」。第12条は主管部署を戦略研究支援部（健都に関するものは健都戦略研究支援部）と規定。同部は「医薬品等の開発振興」ページでプログラムディレクター・プログラムオフィサーによる実用化に向けた指導・助言を行うとするが、認定ベンチャー専用のアクセラレーションプログラム名や公募窓口は公開されていない。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_coi_sidejob', 'established', '兼業は理事長承認制、利益相反委員会が株式保有を確認', '職員就業規則（平成17年4月1日17規程第2号）第9条は営利団体の役職員・顧問・評議員の兼職および営利事業への従事を理事長の承認制とし、無報酬でも事前届出を要する。第11条は医薬品・医療機器関連企業の株式取引を自粛としつつ、自らの研究開発の社会実装を目的に設立されるベンチャーへの出資は事前届出により除外。株式等取得保有規程第10条は、利益相反管理規程（平成20年11月11日20規程第14号）の利益相反委員会が兼業・共同研究で関与する職員の株式保有状況等を個別調査すると規定。', 'official', 'https://www.nibn.go.jp/introduction/disclosure/regulations/syuugyou.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'attr_support_fee', 'established', '有償、資産貸付契約と実施許諾契約（許諾料は減免可）', '認定規程第6条第2項は事務室・研究室の貸与を研究所資産貸付取扱要領に基づく契約によると規定し、第3項は実施許諾を職務発明等規程に基づく実施許諾契約によるとした上で、理事長が適当と認めるときは実施許諾料を減免できると規定。第4項は支援を行った場合に株式または新株予約権を取得できるとし、株式等取得保有規程第3条は現金による支払の免除・軽減を取得判断の要素に挙げる。料率や貸付料の額は非公開。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'attr_certified_count', 'established', '2社、公式サイトで一覧公開（2026年4月30日現在）', '公式サイト「医薬基盤・健康・栄養研究所発ベンチャーの認定について」は2026年4月30日現在の認定企業として、株式会社プロテオバイオロジクス（認定日 令和4年3月25日、設立日 令和3年9月2日）とVitaCure Bio Inc.（認定日 令和7年6月25日、設立日 令和7年3月24日）の2社を、事業内容とともに掲載している。', 'official', 'https://www.nibn.go.jp/sankangaku/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_cert_rule', 'established', 'JAXAスタートアップ支援制度（名称使用許可制）', '2004年運用開始の「JAXAベンチャー認定制度」を2025年8月28日に改正し「JAXAスタートアップ支援制度」へ。事業計画の審査と認定制度を廃止し、要件適合企業へ名称を付与する名称使用許可制へ移行。称号は「JAXAスタートアップ」「JAXAパートナースタートアップ」（英表記 JAXA Startup / JAXA Partner Startup）。公式サイトに「その企業や事業内容に関してJAXAとして『認定』をすることは致しません」と明記。根拠規程はJAXAスタートアップ支援規程（パートナースタートアップ支援約款第1条・第2条で規程名を確認、規程本文は非公開）。', 'official', 'https://www.jaxa.jp/press/2025/08/20250828-1_j.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'attr_eligible_scope', 'established', '職員が取締役の企業と成果・特許活用企業の2区分', 'JAXAスタートアップ＝JAXAの知的財産又は業務で獲得した知見を利用した製品・サービスの市場提供を主たる事業とし、当該知財・知見に必要な知識を有するJAXA職員が取締役（合同会社は業務執行社員）として経営に関与する会社。JAXAパートナースタートアップ＝JAXAとの共創・共同研究成果の活用、JAXA特許の許諾契約締結による活用、JAXA開発機器の譲受け活用、JAXA事業の移管のいずれかを主たる事業とする会社で、職員の関与は問わず宇宙航空以外の業種も可。共通要件としてアドバイザリー・コンサルティングを主たる事業とする会社は対象外。学生・卒業生の区分は設けられていない。', 'official', 'https://aerospacebiz.jaxa.jp/startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'attr_recognition_decider', 'established', '機構が名称使用を許可、事務は新事業促進部', 'JAXAパートナースタートアップ支援約款第2条第2号に「スタートアップ規程第7条に基づきJAXAによって『JAXAパートナースタートアップ』の名称の使用を許可された会社」とあり、許可主体は機構。約款は「国立研究開発法人宇宙航空研究開発機構 新事業促進部長」名義で、申請窓口も新事業促進部の問い合わせフォーム。2025年8月改正で従来の認定審査会は廃止された。機構内部の決裁権者の役職はJAXAスタートアップ支援規程が非公開のため確認できない。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_cert_pre_registration', 'not_started', '設立済み会社が要件、登記前申請の定めなし', 'JAXAパートナースタートアップ募集ページに掲載された許可要件（JAXAスタートアップ支援規程からの抜粋、約款第2条関係）は4項目の限定列挙で、その第4号が「日本法に基づき適法かつ有効に設立され、かつ存続する会社であること」。設立登記済みの会社であることが許可の前提であり、設立登記前の申請・認定予定通知・条件付認定の定めは要件にも約款にも置かれていない。', 'official', 'https://aerospacebiz.jaxa.jp/startup-partner-app/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'attr_validity_years', 'established', '1年間、自動延長、通算上限10年', 'JAXAパートナースタートアップ支援約款第5条。支援期間は名称使用許可の日より1年間（第1項）。期間満了の1か月前までに機構又は被支援会社のいずれかが書面で不延長を通知しない限り1年間自動延長され、以後も同様（第2項）。延長後の上限は名称使用許可の日より10年、又は被支援会社の設立より10年（休業期間を証明できる場合はその期間を加算）（第3項）。第12条による名称使用許可の取消時は、その時点で支援期間が終了（第4項）。やむを得ない事情による中断期間は通算期間に加算しない（第5項）。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_head_office_registration', 'not_started', '本店登記の受入制度なし', 'JAXAパートナースタートアップ支援約款第7条第1項が支援措置を限定列挙しており、第1号は情報提供・推薦、資金調達支援、投資家対応、販路・提携企業開拓支援、専門家紹介、経営セミナー情報提供、広報支援、第2号は各種相談事項への対応にとどまる。施設の提供や機構所在地での商業登記の受け入れは列挙にない。機構の施設利用は宇宙航空研究開発機構設備等供用約款による設備の時間貸しで、同約款第4条が転貸等を禁止し第10条が原状回復・明渡しを義務づけており、事務所賃貸や登記用住所の付与を想定していない。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_facility_lease', 'not_started', '起業用の部屋貸与なし', 'JAXAパートナースタートアップ支援約款第7条第1項の支援措置の限定列挙に、起業用の部屋・研究室・インキュベーション施設の貸与は含まれていない。新事業促進部が公開する支援メニューは共創（J-SPARC）、JAXA LABEL、特許・技術利用、施設設備供用、実証機会提供、スタートアップ支援制度、出資で構成され、インキュベーション施設の入居制度は掲載されていない。施設設備供用は風洞・エンジン試験設備・細胞培養装置等の試験設備を有償で使わせる制度であり、起業用の居室提供ではない。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_shared_equipment', 'established', '施設設備供用制度、有償（使用料＋技術料）', '新事業促進部の施設設備供用制度。学術研究、科学技術に関する研究開発、宇宙の開発・利用を行う企業・大学・研究機関が対象で、原則として個人利用は不可。調布の風洞・飛行シミュレータ、相模原の超音速/遷音速風洞・宇宙探査実験棟、角田の高温衝撃風洞・ロケットエンジン試験設備、筑波の細胞培養装置・静電浮遊炉等。有償で、平成27年4月1日の改定により技術料が導入された。募集は年2回の定期募集（2月上旬・9月上旬）と随時募集。契約は設備等利用承諾書＋宇宙航空研究開発機構設備等供用約款、又は個別契約書。認定スタートアップ向けの料金区分や減免の記載はない。', 'official', 'https://aerospacebiz.jaxa.jp/solution/facility/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_name_logo_use', 'established', '名称とシンボルロゴを使用可、ガイドライン準拠', 'JAXAパートナースタートアップ支援約款第6条。名称使用許可を受けた日から「JAXAパートナースタートアップ」（英表記 JAXA Partner Startup）の名称および別添1「JAXAパートナースタートアップシンボルロゴマーク」を使用できる（第1項）。使用にあたっては機構が別途提示する「名称使用ガイドライン」および「ロゴデザインマニュアル」に従う（第2項）。支援期間終了後又は第12条による取消後は使用を中止する。第16条により、会社の沿革等、過去の事実として使用する場合のみ使用を存続できる。なお製品に付すJAXA LABELは商品化許諾等を対象とする別制度。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_ip_license', 'not_started', 'スタートアップ向けの減免・株式対価なし', 'JAXA知的財産利用のてびき（2024年9月）別記3の対価算定方式は、知財種別ごとの一律料率（特許2.0％、技術情報1.0％等）と、価値×関与度×特約条件による算定式で構成される。特約条件は「利用が特に困難」「国・地方公共団体等の事業や公益に資する事業」「その他特殊の事情」の3項目のみで、ベンチャー・スタートアップの減免区分は置かれていない。株式や新株予約権を対価とする定めも同てびきにない。許諾期間は最長3年で3年ごとに更新。知的財産ポリシー第5節は「産業振興の促進に向けて非独占的な利用を基本」とし、合理的な場合に独占的・一部独占的許諾を行うが、これは一般規定で認定企業向けの優遇ではない。', 'official', 'https://www.jaxa.jp/about/ip_policy/data/chizairiyou_tebiki_202409.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_equity_rule', 'unknown', null, '［自動検証で否認: SPACE WALKERは現行実績表になし、認可時期も2月説と3月主張が不一致］元の主張(established): 直接出資と間接出資（LP出資）を実施。2021年4月の科学技術・イノベーション創出の活性化に関する法律の改正により、JAXAは同法第34条の6に基づき、研究開発成果に係る成果活用事業者等に対する出資並びに人的及び技術的援助の業務を行える。出資機能は直接出資（1号、成果活用事業者）、間接出資（2号、ベンチャーキャピタルファンド）、TLO等（3号、成果活用等支援法人）の3類型。実績は直接出資が株式会社天地人と株式会社SPACE WALKER、間接出資がFrontier Innovations 1号投資事業有限責任組合へのLP出資（2024年3月に文部科学大臣認可、研究開発法人として初）。新株予約権の取得に関する記載は公開資料に見当たらない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_gap_fund', 'not_started', '起業前資金の給付なし', 'JAXAパートナースタートアップ支援約款第7条第1項の支援措置の限定列挙には、行政・外部提携機関の支援策の情報提供と推薦、資金調達支援、投資家による技術的質問への対応が含まれるが、機構自身が起業準備資金やPOC資金を給付する制度はない。出資機能は活性化法第34条の6に基づき設立済みの成果活用事業者やファンドへ出資するものであり、起業前のギャップファンドではない。学内GAPファンドに相当する制度は新事業促進部の公開メニューに存在しない。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_accelerator', 'established', '約款第7条の伴走支援とJ-SPARC共創', 'JAXAパートナースタートアップ支援約款第7条第1項第1号が、行政および外部提携機関による各種スタートアップ支援策の情報提供とこれへの推薦、資金調達支援、投資家による技術的質問への対応、販売販路および提携企業開拓支援、専門家の紹介、会社経営に関するセミナー情報の提供、広報支援を規定し、第2号がその他各種相談事項への対応を規定する。別枠で宇宙イノベーションパートナーシップ（J-SPARC）が、事業意思のある民間事業者とJAXAがパートナーシップを結び共同で宇宙関連事業の創出を目指す研究開発プログラムとして運用されている。出資先へはハンズオンポリシーに基づく人的・技術的援助を実施。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_coi_sidejob', 'established', '兼業は許可制、利益相反マネジメント制度あり', '就業規則第7条（兼業の制限）が「職員は、別に定めるところにより、兼業することができる」と定め、附則第2条が第7条に基づく「許可又は承認」と明記しており、兼業は別途定める規程による許可制。兼業細則そのものは公開されていない。利益相反は平成26年度から利益相反マネジメント制度を導入し、役職員への自己申告の義務づけ、利益相反マネジメント委員会の設置、外部弁護士によるアドバイザー配置を実施。文部科学省提出資料（2026年1月28日）でも「JAXAの利益相反マネジメント規程」および実務面の「出資に伴う利益相反マネジメントガイドライン」の存在が示されている。JAXAスタートアップは職員が取締役として経営に関与することが要件。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.jaxa.jp/about/compliance/index_j.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'attr_support_fee', 'established', '無償、専門家依頼の実費のみ企業負担', 'JAXAパートナースタートアップ支援約款第7条第2項に「機構は、前項に基づき被支援会社に対して前項各号の支援を行う場合、これを無償で提供する。ただし、被支援会社の求めにより機構が別途専門家等に依頼する場合に生じた実費については、被支援会社が負担する」と規定。名称・ロゴの使用料に関する定めはない。ただし施設設備供用（使用料および技術料）と知的財産の実施許諾（対価算定方式による実施料）は本制度とは別の制度で有償。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'attr_certified_count', 'established', 'JAXAスタートアップ13社、パートナー10社', '新事業促進部のJAXAスタートアップ支援制度ページで社名と事業概要の一覧を公開。2026年9月10日時点の掲載を数えると、JAXAスタートアップが13社（Astro Wave Technologies、emblem、Starry Canvas、Star Signal Solutions、ロケットリンクテクノロジー、WHERE、ツインカプセラ、SEESE、武蔵スカイプラス、天地人、DATAFLUCT、Space Cubics、Flow Sensing Lab）、認定期間満了が2社（パッチドコニックス、オリガミ・イーティーエス）、JAXAパートナースタートアップが10社。2025年8月までの旧制度によるJAXAベンチャー認定企業もJAXAスタートアップとして併載されている。', 'official', 'https://aerospacebiz.jaxa.jp/startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_cert_rule', 'established', 'JAMSTECベンチャー支援規程に基づく認定制度', '知的財産情報ページに「JAMSTECベンチャー制度」は2006年4月制定、認定企業は「JAMSTECベンチャー」と記載。2009年5月29日の機構プレスリリース脚注が根拠規程名を「JAMSTECベンチャー支援規程」と明示し、平成18年4月25日発足とする。令和6年度業務実績等報告書（項目別-133）は平成17年度開始の最長10年の支援制度と説明し、令和6年度に規程改正を実施したと記載。規程条文そのものは非公開。', 'official', 'https://www.jamstec.go.jp/ip/j/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'attr_eligible_scope', 'established', '機構の知財を活用する設立中〜設立後5年以内の企業等', '2009年プレスリリース脚注に「機構の知的財産を活用して事業を行うベンチャー企業等（ただし、設立中又は設立後5年以内のものに限る）からの申請に基づき」と明記。知的財産情報ページは対象を「JAMSTECの知的財産を活用して事業活動を行う企業又は個人等」とする。令和6年度業務実績等報告書は「職員がベンチャー起業をする際の創業期の負担の軽減に重きを置いた」制度と説明。研究機関のため学生・卒業生の区分はない。', 'official', 'https://www.jamstec.go.jp/j/about/press_release/archive/2009/20090529_2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'attr_recognition_decider', 'unknown', null, '認定の決裁者や審査委員会を明示した公開文書は確認できなかった。令和6年度業務実績等報告書（項目別-134）には、ベンチャー相談から起業化までの伴走支援を対外戦略課が中心となり外部専門家と共に事業性評価を行ったとあり、事務局は対外戦略課とみられる。2009年プレスリリースの問合せ先は事業推進部推進課。決裁権者の記載はどちらにもない。', 'unknown', 'https://www.jamstec.go.jp/j/about/research_assessment/pdf/r6_eval_rep.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_cert_pre_registration', 'established', '可（設立中の事業主体も申請対象）', '2009年プレスリリース脚注が対象を「設立中又は設立後5年以内のもの」とし、設立登記前の事業主体を申請対象に含める。知的財産情報ページの認定企業一覧では合同会社オフショアテクノロジーズの設立日と認定日がいずれも2018年4月2日で同日認定。条件付認定や認定予定通知という運用の有無は公開情報では確認できない。', 'official', 'https://www.jamstec.go.jp/j/about/press_release/archive/2009/20090529_2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'attr_validity_years', 'established', '原則5年、最長10年（5年目に事業性評価）', '2009年プレスリリース脚注に「認定期間は原則5年間」。令和6年度業務実績等報告書（項目別-133、136）は「最長10年間の支援制度」とし、令和6年度改正で「5年目を事業性・成長性評価の一つの区切りとし、新株予約権を行使するか放棄するか決定する」と記載。知的財産情報ページの一覧では株式会社オーシャンアイズが2019年11月25日認定、2023年11月24日認定満了。更新手続の明文は非公開。', 'official', 'https://www.jamstec.go.jp/j/about/press_release/archive/2009/20090529_2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_head_office_registration', 'established', '可（横浜研究所住所で本店登記の実例）', 'JAMSTECニュース2018年5月10日は、認定ベンチャー合同会社オフショアテクノロジーズの本店を「神奈川県横浜市金沢区昭和町3173-25」と公表。この住所は機構横浜研究所の所在地「〒236-0001 神奈川県横浜市金沢区昭和町3173番25」と一致する。機構自身の公表による実例であり受入れは確認できるが、商業登記の受入れを定めた規程や有償・無償の別を示す公開文書は確認できなかった。', 'official', 'https://www.jamstec.go.jp/j/jamstec_news/20180510/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_facility_lease', 'unknown', null, '起業用の居室やインキュベーション施設の貸与を示す公開情報は確認できなかった。外部共用の対象は横須賀本部の多目的プール施設、超音波水槽装置、高圧実験水槽装置、中型高圧実験水槽装置、多目的実験水槽、海洋研修棟講義室等の実験設備で、居室提供の記載はない。産業連携ページの連携メニューも共同研究・受託研究等・技術指導・MTAの4つで、施設賃貸を含まない。', 'unknown', 'https://www.jamstec.go.jp/j/about/equipment/yokosuka/faci2.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_shared_equipment', 'established', '特定共用施設を使用可、基本使用料50%減額または無償', '「特定共用施設の外部共用について」2.使用料の優遇に「JAMSTECベンチャーとして認定された企業がその事業実施を目的として使用される場合等では、使用料の優遇が可能」「優遇は、機構の基準に基づき基本使用料の50%あるいは無償となります」と明記。消耗品費等の実費は原則自己負担。使用料は機構が定める「受託等対価積算規則」に基づき徴収し、使用契約を締結する。', 'official', 'https://www.jamstec.go.jp/j/about/equipment/yokosuka/faci.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_name_logo_use', 'established', '称号「JAMSTECベンチャー」使用可、ロゴ条件は非公開', '知的財産情報ページが認定企業を「JAMSTECベンチャー」として一覧掲載し、JAMSTECニュース2018年5月10日も「JAMSTECベンチャーとして認定されました」と告知しており、称号の対外使用が認定の効果として運用されている。機構ロゴは「JAMSTECロゴマーク」ページによれば標章制定規程で形状・色彩を定め平成18年1月1日から正式な標章として使用されているが、第三者の使用条件を示す公開文書は確認できなかった。', 'official', 'https://www.jamstec.go.jp/ip/j/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_ip_license', 'established', '知的財産の実施等許諾権の優遇', '2009年プレスリリース脚注が優遇措置として「知的財産に対する実施等許諾権の優遇」を挙げる。知的財産情報ページも支援内容に「実施許諾における優遇措置」を明記。独占的許諾の可否、対価の減免率、株式対価によるライセンスの可否は公開情報では確認できない。令和6年度業務実績等報告書は、支援措置の対価として認定要件に新株予約権付与を加えたとする。', 'official', 'https://www.jamstec.go.jp/j/about/press_release/archive/2009/20090529_2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_equity_rule', 'established', '認定要件として機構への新株予約権付与、活性化法で出資可', '令和6年度業務実績等報告書（項目別-134）に「JAMSTECベンチャー認定の要件の1つに『ベンチャーが機構に対し新株予約権を付与すること』を新設」「5年目を事業性・成長性評価の一つの区切りとし、新株予約権を行使するか放棄するか決定する」制度へ規程改正を実施と記載。あわせて中長期計画（18頁）と中長期目標が、科学技術・イノベーション創出の活性化に関する法律に基づく成果活用事業者への出資並びに人的及び技術的援助を業務として明記。', 'official', 'https://www.jamstec.go.jp/j/about/research_assessment/pdf/r6_eval_rep.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_gap_fund', 'unknown', null, 'GAPファンド、起業準備資金、POC資金に相当する学内資金制度を示す公開情報は確認できなかった。中長期計画・中長期目標・令和6年度業務実績等報告書のベンチャー支援に関する記述は、伴走支援、セミナー、知的財産と施設の優遇、活性化法に基づく出資に限られ、起業前の研究者へ資金を配分する枠組みの記載はない。', 'unknown', 'https://www.jamstec.go.jp/j/about/project/pdf/keikaku2026.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_accelerator', 'established', '相談から起業化までのワンストップ伴走支援と養成塾', '令和6年度業務実績等報告書（項目別-133）に「JAMSTECベンチャー起業に向けた支援メニュー」を拡充し、内外の専門家と共に事業性の評価に関与して「ベンチャー相談から起業化までのワンストップ伴走支援を強化した」と記載。全役職員向け「アントレプレナーシップ養成塾」セミナーを令和7年2月に開催し定例化、令和7年度は事業計画書の作り方等の実践講習を予定。中長期計画もスタートアップ支援エコシステムの構築を明記。', 'official', 'https://www.jamstec.go.jp/j/about/research_assessment/pdf/r6_eval_rep.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_coi_sidejob', 'established', '兼業は事前許可制、利益相反マネジメント委員会が審査', '定年制職員（研究系）就業規程（平25規程第80号）第61条第1項第1号が「自己の業務を営み、又は業務を兼務し、若しくは他の業務に自己の名義を貸与するとき」を事前許可事項と定める。利益相反マネジメントポリシーは狭義の利益相反と責務相反を対象に、利益相反マネジメント委員会と外部有識者の利益相反アドバイザーを設置し、定期自己申告・事前自己申告・ヒアリング・是正勧告、理事長の最終判定を規定。株式保有の許可要件は非公開。', 'official', 'https://www.jamstec.go.jp/j/about/management_policy/index2.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'attr_support_fee', 'established', '原則有償、施設使用料50%減額・無償、実費は自己負担', '「特定共用施設の外部共用について」は認定ベンチャーへの優遇を基本使用料の50%または無償とし、「使用に係る消耗品費等の諸費用（実費）分は原則ご負担いただきます」と明記。知的財産は実施等許諾権の「優遇」であり無償化の記載はない。令和6年度業務実績等報告書は、投入した支援措置に見合うリターンを得るため認定要件に新株予約権付与を加えたとする。共同研究・受託研究の間接経費は研究費の30%。', 'official', 'https://www.jamstec.go.jp/j/about/equipment/yokosuka/faci.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'attr_certified_count', 'established', '4社（一覧公開、うち2社は認定満了）', '知的財産情報ページ「JAMSTECベンチャー認定企業一覧」に4社を掲載。株式会社OceanFluidics（2025年3月10日認定）、株式会社オーシャンアイズ（2019年11月25日認定・2023年11月24日満了）、合同会社オフショアテクノロジーズ（2018年4月2日認定）、株式会社フォーキャスト・オーシャン・プラス（2009年6月1日認定・2019年3月31日満了）。中長期目標はモニタリング指標に認定企業数を設定。', 'official', 'https://www.jamstec.go.jp/ip/j/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_cert_rule', 'established', '大学発ベンチャー取扱要領に基づく称号認定', '「国立大学法人宮崎大学における大学発ベンチャーの取扱要領」（平成30年2月14日決定・実施）。第3条第1項第1号で「宮崎大学発ベンチャー」と称することを認めることを支援内容に規定。要領全文は研究・産学地域連携推進機構 産学・地域連携部門の「宮崎大学発ベンチャー企業」ページに掲載（ウェブ上の見出し表記は「宮崎大学発ベンチャー企業」）。第13条第2項で、認定に際し契約が必要と認められる場合は別途契約を締結。公開規程集（国立大学法人宮崎大学規程集）にはこの要領のPDFは収載されていない。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'attr_eligible_scope', 'established', '知財・研究成果由来、教職員と学生、退職卒業1年以内', '要領第2条: (1)本学又は本学の教職員等（学生を含む）が所有する知的財産権をもとに起業、(2)本学で達成された研究成果又は習得した技術・手法等に基づく起業、(3)教職員等が設立者となる又は設立に深く関与（退職・卒業後の起業は退職・卒業から起業まで1年以内に限る）、(4)本学が起業に際し出資又は出資斡旋するもの又はしたもの、(5)その他研究・産学地域連携推進機構長が認めたもの。同条第2項で、本学の職務や本学で得た知識・経験から著しく離れて発想した技術・アイデアに基づく起業は(1)〜(3)に該当しないと除外。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'attr_recognition_decider', 'established', '機構長が判定、研究・産学地域連携推進会議が決定', '要領第6条で研究・産学地域連携推進機構長が支援の可否を判定し、第7条で研究・産学地域連携推進会議が審議・決定、結果は機構長が書面で当該企業に通知。第8条で称号使用の決定は機構ウェブサイト等で公表。連携推進会議は宮崎大学研究・産学地域連携推進会議規程（令和4年9月22日制定）第3条・第4条により機構長を議長として組織される。事務は要領第12条により機構事務部産学・地域連携課。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_cert_pre_registration', 'established', '申請様式で起業前の申請可、登記予定住所を記入', '公式様式「宮崎大学発ベンチャーの支援申請書」の「7.宮崎大学の関与」各号が「起業するもの又は起業されたもの」と設立前を含む書き方になっている。「5.住所及び連絡先」に「宮崎大学の住所を登記に使用したい→この場合、下記＜住所＞には登記予定の大学施設の住所を記入すること」とあり、登記前の申請を受け付ける様式。ただし要領本文には登記前申請・認定予定通知・条件付認定の明文規定は無く、添付資料として「会社設立に関する証明書（現在の定款等）」を求めている。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/mediafile/venture_request.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'attr_validity_years', 'established', '期限の定めなし、毎年6月末の活動報告と取消規定', '要領には認定（支援決定）の有効期間・更新の規定が無い。第9条で支援決定を受けた企業に毎年6月末日までの活動内容報告書の提出を義務づけ、第10条で届出事項の変更・解散・破産等の報告義務、第11条で定義からの著しい逸脱・信用失墜・活動実態の消滅・本人からの申出等の場合に機構長が支援決定を取り消せると規定。活動内容報告書の様式には「宮崎大学発ベンチャー認定日」欄があり有効期限欄は無い。期間の制限は学内本店登記（最大3年＋2年延長）に限られる。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_head_office_registration', 'established', '可、最大3年＋2年延長、施設利用が前提で有償', '要領第3条第1項第3号: 同項第2号の施設利用を認めた場合、最大3年間は登記の住所を当該施設の住所とすることを認め、大学発ベンチャーからの申出があり機構長が適当と認める場合は更に2年を限度に延長できる。支援申請書にも「大学施設の住所を登記に使用する期限は、原則、採択後最大3年間」と明記され、申請様式で大学住所での登記希望を選択する。第3条本文ただし書で支援内容に応じ一定の対価等を要求でき、施設利用規程第11条で使用料と1か月以上利用時の光熱水費実費を負担。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_facility_lease', 'established', '研究・産学地域連携推進施設、研究と事務所用、有償', '要領第3条第1項第2号で、本学教職員との共同研究・技術指導を受けた研究、本学の研究成果や習得技術の事業化を行う場合に本学施設の利用等を認める（各施設の利用規程による）。宮崎大学研究・産学地域連携推進機構（研究・産学地域連携推進施設）利用規程（令和4年9月22日制定）第2条第8号「大学発ベンチャーの研究及びそのオフィス業務」、第3条第5号「大学発ベンチャーの役職員」を利用範囲・利用者資格に明記。第4条で機構長への利用申請と承認、第11条で使用料負担と1か月以上利用時の光熱水費実費。申請書提出前に当該部局長の了承が必要。', 'official', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/8-2-6.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_shared_equipment', 'unknown', null, '［自動検証で否認: 全学共用設備の記述は8-2-6.pdfに無い(別規程由来)］元の主張(established): 推進施設の分析機器と全学共用設備を利用可、有償。研究・産学地域連携推進施設利用規程第2条第1号で分析機器類を使用する研究、同条第8号で大学発ベンチャーの研究を利用範囲に規定し、第9条で機器の搬入、第11条で使用料と光熱水費実費を負担。全学の共用設備は宮崎大学における研究設備の共同利用に関する規程（令和2年11月26日制定）により共同利用設備管理委員会が利用料を設定して宮崎大学設備情報データベースに登録・公開し、第5条・第6条で受託試験・検査の依頼者や学内外の共同研究等の関係者に利用を認める。共同利用規程には大学発ベンチャーを名指しした条項は無い。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_name_logo_use', 'established', '「宮崎大学発ベンチャー」称号の使用承認', '要領第3条第1項第1号で「宮崎大学発ベンチャー」と称することを認める。第8条で称号使用の決定は機構ウェブサイトへの掲載等により広く公表。活動内容報告書の様式で称号の使用状況（パンフレット・名刺等への掲載、企業ホームページ、メディアへのプレスリリース、製品の外装等）の報告を求めている。大学ロゴマーク・校章の使用条件を定めた規程は、公開されている国立大学法人宮崎大学規程集の一覧には見当たらなかった。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_ip_license', 'established', '優先ライセンス・条件優遇・権利譲渡が可能', '国立大学法人宮崎大学職務発明等規程（平成16年4月1日制定、令和4年10月1日改正施行）第18条（大学発ベンチャー）: 本法人は、職務発明等の事業化を目的として起業された会社に対し、他に優先して当該職務発明等に係る知的財産権をライセンスし若しくはライセンス条件を優遇し又は権利譲渡をすることができる、と規定。独占許諾の明文は無く「他に優先して」の表現。事務は機構事務部産学・地域連携課（第19条）。', 'official', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/2-4-3.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_equity_rule', 'established', 'ライセンス対価として株式・新株予約権を取得可', '国立大学法人宮崎大学におけるライセンス等の対価として取得する株式等取扱規程（平成29年1月26日制定、令和4年10月1日改正施行）。第2条第5号で大学発ベンチャー企業を定義、第3条で相手方が現金を保有しない等の場合に対価の一部又は全部を株式等で取得でき、法令遵守に問題がある場合等は取得しない。第4条で学長が機構長に諮問して可否を決定、第5条で新株予約権は行使可能次第行使、第6条で議決権は原則不行使、第8条で換金可能になり次第売却、第9条で収入から必要経費を控除した額の50%を発明者等が請求可能。', 'official', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/2-5-52.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_gap_fund', 'unknown', null, '要領第3条第1項が挙げる支援は、称号使用、施設利用、登記住所、機構による起業・起業後経営の相談業務、その他機構長が必要と認める支援であり、資金支援は列挙されていない。第2条第4号に「本学が、起業に際して出資若しくは出資斡旋するもの又はしたもの」との定義はあるが、これは認定対象の定義であり資金制度の根拠ではない。学内GAPファンド、起業準備資金、POC資金の制度は機構サイトおよび公開規程集で確認できなかった。列挙に包括条項があるため制度なしとは断定しない。', 'unknown', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_accelerator', 'established', '機構が起業・起業後経営の相談業務を担当', '要領第3条第1項第4号で、研究・産学地域連携推進機構が起業や起業後の経営等について相談業務にあたることを支援内容として規定。宮崎大学研究・産学地域連携推進機構規則（令和4年9月22日制定）第3条第4項第3号で「大学発ベンチャーの育成及び支援に関すること」、同項第5号で「企業等に対する技術相談、技術指導及び研修の実施に関すること」を産学・地域連携部門の業務と規定。期間や選抜を伴うアクセラレーションプログラムの制度化は、公開情報では確認できなかった。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_coi_sidejob', 'unknown', null, '［自動検証で否認: 兼業の学長許可制は2-4-15.pdfに無い(別規程由来)］元の主張(established): 兼業は学長許可制、利益相反委員会が自己申告で管理。要領第4条第5号で、教職員が設立に深く関与して起業した場合は職員兼業規程等に定める手続・承認が適切になされていることを支援の条件とする。職員兼業規程（平成16年4月1日制定）第6条で事前に部局長経由で学長へ申請し許可を受ける、第4条第2項で営利企業の事業に関与する職・職責が重大な職・常勤職は別に定める場合を除き原則不許可、第4条第3項で週平均8時間以内、同条第4項で許可期間は原則2年以内。利益相反マネジメント規程（平成18年5月25日制定）第3条で兼業と企業からの株式等の経済的利益を管理対象とし、利益相反委員会が自己申告書等の調査に基づき審議・勧告、第18条で相談窓口を設置。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'attr_support_fee', 'established', '支援内容に応じ対価を要求、施設は使用料と実費', '要領第3条第1項本文ただし書に「本学は支援内容に応じて一定の対価等を要求できるものとする」と明記。施設利用は研究・産学地域連携推進施設利用規程第11条で機構が別に定める経費を使用料として負担し、1か月以上利用する者は光熱水費を実費負担。共用設備は研究設備の共同利用に関する規程第11条で共同利用設備管理委員会が別に定める利用料を負担。称号使用と相談業務そのものの対価の有無は、要領および公開情報からは特定できなかった。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'attr_certified_count', 'established', '12社、機構サイトで企業名一覧を公開', '研究・産学地域連携推進機構 産学・地域連携部門「宮崎大学発ベンチャー企業」ページに12社の企業名一覧を掲載（バイオプロジェクト、ひむかAMファーマ、宮崎国際教育サービス、Smolt、MabGenesis、LOCOBOT、namstrops、LumiD&NAファーマ、地域資源ブランディング、ブルーインフラテクノロジーズ、VOICE_lab、うんこ電池）。多くは企業サイトへのリンク付き。要領第8条で称号使用の決定は機構ウェブサイトへの掲載等により公表すると規定。ページに基準日の記載は無く、2026年9月10日閲覧時点の掲載数。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910')
